INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray XO Barbados Rum 20th Anniversary Extra Old 40%', 'https://www.uhrskov-vine.dk/planteray-barbados-rum-20th-anniversary-xo-extra-old', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationxo.png', 'Denne unikke Barbados rom er efterlagret på fine små cognacfade hos cognachuset Pierre Ferrand i hjertet af Cognac i Frankrig. De bløde franske limousine egefade, som først er blevet brugt til modning af den allerbedste Grande Champagne Cognac, bidrager med blød frugt, revet appelsinskal og fine vaniljetoner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Reserva Exclusiva Rum 12 år Venezuela 40%', 'https://www.uhrskov-vine.dk/diplomatico-reserva-exclusiva-rum-12-ar-venezuela', 319, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplomatico_exclusiva_flaskefoto.png', 'Guldmedalje - Ministry of Rum Tasting Competetion 2007 ★★★★★★, 93 Point & Bedste Rom - Ekstra Bladet Diplomatico Rom er en en fabelagtig mørk gylden rom fra Venezuela. destilleret på melasse i kober potstills og derefter 12 års lagring. Diplomatico er en fyldig, sød go frugtig rom. Super kvalitet til pengene!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Original Dark Double Aged Rum 40%', 'https://www.uhrskov-vine.dk/planteray-original-dark', 219, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-original-dark.jpg', 'Her kan man virkelig tale om en klassiker! Planteray Original Dark Rum er fast inventar på verdens bedste barer; der findes bare ikke ret mange flasker, der kan konkurrere på kvaliteten til den pris! Rommen har to komponenter: en del fra Barbados og en del fra Jamaica. Begge er lavet på melasse og fra Barbados kommer de bløde karamel- og kokosagtige noter, mens Jamaica (Long Pond Distillery) leverer den velkendte frugtige kvalitet og lidt ekstra intensitet. Rommen er afrundet med lidt sukker – 15 gram per liter – hvilket giver en sødmefuld smagsoplevelse, uden at rommens karakter overdøves.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Centenario XO Rum Solera Gran Reserva Especial 40%', 'https://www.uhrskov-vine.dk/ron-zacapa-centenario-xo-rum-solera-gran-reserva-especial', 1095, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/z/a/zacapaxo.png', 'Vandt platin i Canada på "Rum Award festival". En af favoritterne blandt romelskere! Ron Zacapas 25 år gamle Solera rom er fuldendt mesterstykke fra samme hus som laver den 23 år gamle Solera rum. Yderst eksklusiv rom i klassisk, smuk flaske. Blend af de absolut bedste rom-sorter fra Guatemala med min. 25 år på bagen. En himmelsk rom - hverken mere eller mindre. Som lillebroderen Ron Zacapa Centenario 23 Solera kan man ikke få nok, men prisen gør at man disponerer denne rom lidt bedre. Den har lige en lidt blødere oplevelse og virker som den totale fuldendelse af et mesterværk!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario Numero 15 Reserva Especial 40%', 'https://www.uhrskov-vine.dk/ron-millonario-solera-15-reserva-especial-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom06377.jpg', 'Denne Ron Millonario var den første i Ron Millonario-serien, og bliver stadig anset som brandets flagskib. Den er særlig kendt blandt mange og er rigtig god til dig, der måske skal til at starte dit eventyr. Tidligere kom denne flaske klædt i bast - også kaldet "basten" i daglig tale. Ron Millonario produceres på et destilleri i den nordlige del af Peru. Destilleri Pomalca i byen Chiclayo. Der er tale om en Spirit Drink, og de 15 år er en gennemsnitsalder på det der er i flasken. Duft En dyb, fyldig og vedholdende duft i næsen af kandiserede frugter, kakao, kokos, blomme og nellike Smag Ganen mødes til at begynde med af nelikke, hvorefter smagen bliver mere sødmefyldt og fyldig og rummer smag af sirup, toffee, rosin, figen, dadler karamel og mørk farin Eftersmag Smagen slutter af med en nærmest kage-lignede eftersmag som holder ved, men som dog slutteligt efterlader ganen med en frisk følelse', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Goslings Black Seal, Bermuda Black Rum 40%', 'https://www.uhrskov-vine.dk/goslings-black-seal-bermuda-black-rum', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/o/goslings-black-seal-rum_1_1.jpg', '96 Point & "best buy" - World Spirits Championships Gosling Black Seal har en rig, kompleks smag, velafbalanceret og nuanceret med vanilje og karamel. Imponerende nok til at vinde “The Beverage Testing Institute” højeste ære, som er Platinum Medalje.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Meticho Chocolate & Toffee 40%', 'https://www.uhrskov-vine.dk/rum-nation-meticho-chocolate-toffee-40', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/e/metichochoc.png', 'En chokoladebar for voksne. Meticho Chocolate & Toffee er en lækker rombaseret spiritus, som lader dig give efter for din søde tand, og som inviterer en tur på chokoladefabrikken eller forbi bageren. Baseret på en helt særlig hemmelig opskrift; Central Amerikansk rom anvendes som basen, hvortil der tilsættes naturlige smagsgivere: chokolade,  toffee , vanilje og karamel. Det giver varmen fra rommen sammen med en cremet, smøragtig og lækker fylde fra de forskellige smagsgivere - nærmest som konfekt. Nyd den  on the rocks , i en drink helt for sig selv eller sammen med en dessert.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray 3 Stars White Rum 41,2%', 'https://www.uhrskov-vine.dk/planteray-3-stars', 209, TRUE, NULL, 41.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-3stars_1.jpg', 'Planteray 3 Stars er en blanding af rom fra 3 af ”stjernerne” i den caribiske romproduktion: Barbados, Trinidad og Jamaica – og deraf navnet. Blandingen består af ulagret Barbados-rom, 2-3 år gammel Trinidad-rom, ulagret Jamaica-rom og et touch af vellagret Jamaica-rom, som giver en dybde i smagen man normalt sjældent finder i ”cocktailrom”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Seleccion Triple Aged Rum 42%', 'https://www.uhrskov-vine.dk/dos-maderas-seleccion-rum-42', 425, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmaderasseleccion.png', 'En delikat romblanding fra Barbados og Guyana. To lande med deres egen romstil. Begge lande laver nemlig rom på pot stills og kolonneapparat. Den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede på mere moderne kolonneanlæg.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s Rum Gunpowder Proof 54,5%', 'https://www.uhrskov-vine.dk/pusser-s-rum-gunpowder-proof-54-5', 379, TRUE, NULL, 54.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/pussers-gunpowder-proof.jpg', 'Pusser''s Navy Gunpowder Proof Rum er en serie af ægte sømandsrom, der holder den engelske flådes traditioner i hævd. Som den vel eneste rom destilleres Pusser''s stadig på gamle træ-destillatorer, hvilket må siges at være så klassisk, som noget kan være, og derudover giver det rommen en utrolig fylde. Pusser''s Navy Rum er en rom-stil helt for selv…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Overproof OFTD Artisanal Rom 69%', 'https://www.uhrskov-vine.dk/planteray-overproof-oftd-rom', 329, TRUE, NULL, 69, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/f/oftsd.png', 'OFTP står for Old Fashioned Traditional Dark. Her har Plantation lavet en rom på hele 69%. En intens rom med noter af kaffe, orange, blommer og trøfler i næsen. I smagen får du cremet karamel, mørk chokolade og vanilje, med hint af kanel, rosiner og eg. En utroligt varm og intens rom fra Plantation, som går fantastisk både for sig selv og i cocktails.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rum 10 år Panama 40%', 'https://www.uhrskov-vine.dk/malteco-rum-10-ar-panama', 269, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco-rum-10yo_2_1_1.jpg', 'Denne rom er fra Panama og bliver produceret af de samme, som laver Ron Zacapa. Alene dét gør, at man sætter forventningerne rimelig højt, inden man trækker proppen op at den aflange, mørke flaske. De høje forventninger bliver dog heller ikke gjort til skamme, for dette er en yderst spændende og lækker rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Caribbean Triple Aged Spirit Drink 5+5 år P.X. 40%', 'https://www.uhrskov-vine.dk/dos-maderas-caribbean-spirit-drink-5-5yo-px', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmaderas55.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco 2013 Vintage Reserva, Panama 44,4%', 'https://www.uhrskov-vine.dk/malteco-rum-2013-vintage-reserva-44-4', 319, TRUE, NULL, 44.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco_reserva_2011_new.jpg', 'Sødlig, fyldig og yderst vellavet Vintage rom fra Panama, som er destilleret i 2011 – og aftappet i 2023. Stor viskositet med ’tunge gardiner’. Duften er cremet, sødlig og med tydelige noter af melasse, puddersukker, brændte nødder og hvid chokolade. Saftig, sød og cremet smag med stor koncentration og harmoni. Her finder du lækre smagsnoter af chokolade, sød lakrids, melasse, brændte figner og dadler samt mocca. Meget flot længde på eftersmagen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados Rum Grande Reserve 40%', 'https://www.uhrskov-vine.dk/planteray-barbados-grande', 239, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/r/grandereserve.png', 'Plantation Grande Reserve er en blanding af forskellige rom fra Barbados, som alle ligger et til tre år på bourbonfade i troperne, før de efterlagres sammen i gamle, franske cognacfade på Chateau Bonbonnet i hjertet af Grande Champagne. Farve:  Gylden Duft:  Moden, tropisk frugt. Kokosnød og vanilje. Smagsnoter:   Bløde og sødmefulde noter af kandiseret frugt. Den samme kokosnote, vi fandt i duften, går igen i smagen…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Smith & Cross Traditional Jamaica Rum 57%', 'https://www.uhrskov-vine.dk/smith-cross-traditional-jamaica-rum-57', 279, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/m/smithcross.png', 'En Navy Strength udgave af den klassiske Smith og Cross Jamaica rom, lige til at sippe ren, behagelig blød og med velkendte noter af eksotisk frugt og krydderier, en kompleks rom med en bred vifte af smagsoplvelser med lidt ekstra spark. Rommen er “non-chill filtered” for at bevare hele smagsoplevelsen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Panama 10 år 40%', 'https://www.uhrskov-vine.dk/rum-nation-panama-10-yo', 325, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04901.jpg', '10 års rom destilleret af Rum Nation fra Panama. Rommen dufter delikat, frisk, sød og frugtagtig. Smagen af sukkerrør dominerer uden at være for markant, udover den sukker-rige smag toppes den af med noter afhonning, rosin og mælkechokolade. Den har dog også små hints af appelsin og abrikos. Denne rom er altså en sød og blød rom, men den har ikke en trættende sødme. Den er ligetil, en ideel rom for nybegynderen der foretrækker en sød og behagelig rom. Rum Nation er en verdensomspændende romserie, udelukkende bestående af specifikt udvalgte fade fra et nøje udvalgt destilleri. Resultatet er et udvalg af ”single rom” fra mange forskellige nationer. Alle tro mod spiritussens hjerte, unik og uforglemmelig. Denne gang fra Panama, hvor den er produceret og lagret i 10 år på Jack Daniels fade. Bliv en ”Citizen of Rum Nation”, det er en fantastisk rejse gennem en verden af rom!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario Rum 10 Aniversario Reserva 40%', 'https://www.uhrskov-vine.dk/ron-millonario-rum-10-aniversario-reserva-40-70cl', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-millo-aniver-10.jpg', 'Spændende Rom nyhed. Ron Millonario 10 Aniversario Reserva er en ny opskrift fra den talentfulde Fabio Rossi, specielt designet til at tilbyde en friskere, mere duftende og lettere version af den søde, rige smagsprofil som er normalt forbundet med Ron Millonario. Denne moderne blanding er rom samlet fra en høj procentdel af lettere/mildere rom som er modnet i friske bourbon fade, og en lille del af ældre rom modnet i tidligere sherryfade for at tilføje en krydderet kompleksitet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Pineapple, Original Dark Rum 40%', 'https://www.uhrskov-vine.dk/planteray-pineapple-rum-original-dark', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-pineapple-rum.jpg', 'Pineapple Rom Projektet er skabt ud fra historisk nysgerrighed og er endt med at blive et yderst velsmagende resultat. Kort fortalt er Plantations nye Pineapple Rum et blend af hvid og mørk rom, som henholdsvis er blevet destilleret med ananasskræl og lagt i blød (infusion) i mørk rom. Til slut "vies" det hele på fade i flere måneder.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 8 år Pure Single Jamaican 46%', 'https://www.uhrskov-vine.dk/hampden-estate-8yo', 599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden-estate-7yo-46_1.jpg', 'Hampden Estate 8 års er en jamaicansk rom fra et af Caribiens ældste og mest famøse destillerier. På Hampden produceres en karakteristisk, frugtig og kraftig stil, som er højt elsket af spiritusnørder verden over. Dette nye Hampden-udtryk er udviklet i samarbejde med Velier, og alt er gjort rigtigt: rommen er lagret 7 år i troperne og uden tilsætning af sukker eller farvestof – det er svært at komme tættere på rom-nirvana…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario XO Reserva Especial, Peru 40%', 'https://www.uhrskov-vine.dk/ron-millonario-xo-reserva-especial-peru-40', 849, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-millonario-xo-reserva_2.jpg', 'Den ældste aftapning af Ron Millonario –også kaldet XO. En Solera Rom med en alder omkring 15-20 år og idag en af de ældste sydamerikanske Rom. Ejer og blender Fabio Rossi, udvælger kun de bedste fade til denne rom, hvilket gør denne rom helt sublim. Farven er flot mørk gylden og med en duft af appelsin, melasse, karamel og en anelse tobak. (Tidligere kåret til verdens bedste rom i henholdsvis 2008 og 2009.)', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s 14 år Fine Old Rum, Barbados 48%', 'https://www.uhrskov-vine.dk/doorlys-14-aar-fine-old-rum-barbados-48', 699, TRUE, NULL, 48, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/doorlys14.png', 'Martin Doorly stiftede rom mærket Doorlys i de tidlige 1920-ere. I 1992 blev Martin Doorly Rum købt af RL SEALE.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Gran Anejo, Guatemala & Belize Rum 42%', 'https://www.uhrskov-vine.dk/planteray-rum-gran-anejo-guatemala-belize', 339, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-gran-anejo-guatemala_2.jpg', 'Kompakt og intens høj ester rum. Mørke frugter og meget saftig. Smag: Figner, akaicehonning, rosiner og kamilleblomst. Meget blød og tyk på ganen. Eftersmagen er lang og svagt røget. En næsten likøragtig rom. Meget blød og delikat. En perfekt ledsager til kaffen. Plantation Rum serien udtrykker en unik og bred serie af gamle kvalitets rom fra Caribien…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rum 25 år Reserva Panama 40%', 'https://www.uhrskov-vine.dk/malteco-rum-25-ar-reserva', 699, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco-25yo-reserva-guatemala_2.jpg', 'Malteco rum er i stilen en Guatemala rom på trods at oprindelseslandet er Panama. Destilleriet Varela Hermanos der laver Malteco rum ligger i byen Pesé i den sydlige del af det centrale Panama. I 1908 etablerede den daværende ejer, Don José Varela Blanco, den første sukkerfabrik. Senere, i 1936, åbnede romfabrikken, som lige siden har produceret rom af høj kvalitet. Varela Hermanos er den største leverandør af rom til hjemmemarkedet i Panama, og leverer mere end 90% af al rom til de lokale. Rommen er destilleret på kolonne-kedler og er derfor i den elegante, lette stil, hvilket også er kendetegnede for rom fra Guatemala. Rommen bliver lagret på 220 liters brugte bourbonfade af hvid, amerikansk eg. Tønderne giver rommen en passende kontakt med fadet, hvor mindre tønder ville give for meget kontakt og større tønder for lidt. Malteco 25 rum er en helt igennem udsøgt rom, hvor melasse, farin, svesker, tørrede rosiner og en lækker cremethed går igen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate 12 Års Rare Casks Jamaica Rum, 43%', 'https://www.uhrskov-vine.dk/appleton-estate-rare-blend-12-ar-jamaica-43', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/p/appleton12.jpg', 'Appleton Estate Extra 12 års Jamaica rom er ældet i mindst 12 år i egetræsfade og er udråbt som et uovertruffent mesterværk af ege-aldring. Farve: blændende og lys bronze. Næse: modne dufte af valnødder, muskatnød, appelsin og vanille, samt noter af kaffe, kakao, ristet eg og mandel. Smag: Smøragtig og cremet brun sukker. Eftersmag: Bittersød og saftig. Appleton Estate Extra 12 år er en dristig og selvsikker rom, der bør nydes rent eller on the rocks.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pura Vida XO Costa Rica 40%', 'https://www.uhrskov-vine.dk/pura-vida-xo-costa-rica-40', 509, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/puravida.png', 'Costa Ricas nye rom-stjerne! Costa Rica er en af verdens bedste sukkerrørsproducenter, og det udnytter man virkelig her: Pura Vida XO er lavet på både melasse, sugarcane honey og frisk sukkerrørssaft. Den er lagret primært i Costa Rica på bourbonfade, og får en finish på gamle cognac tuns. En fyldig og kompleks rom for både kendere og nybegyndere.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo 12 år, Añejo Gran Reserva Panama Rum, 40%', 'https://www.uhrskov-vine.dk/abuelo-anejo-12-anos-rum-panama-40', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/b/abuelo12.png', 'En duft af Rørsukker, let krydret, nougat, mokka, lys chokolade, vanilje. Smager af frisk og syrlig med en fyldig sødme. En lang eftersmag af sødme som fylder hele munden. Produceres i Panama af Varela Hermanos, som oprindeligt har lært romhåndværket i Cuba. Mere rund end den 7 årige og blød, lidt til den søde side. Indbegrebet af imødekommende Caribisk rom. Fra Panama er "bedstefar rommen" nu kommet til Danmark.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Stroh 80 Rom, Austria Inländer Rum 80% 50cl', 'https://www.uhrskov-vine.dk/stroh-80-rom-austria-inlander-rum-50-cl', 179, TRUE, 50, 80, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/t/stroh_1.png', 'En umådeligt stærk version af den østriske kult rom med en alkoholprocent på 80%. Lækker i kaffe, tilsæt evt. flødeskum, bruges også til kagebagning, desserter, cocktails og er at anbefale til en romtoddy, hvis halsen giver dig problemer. Vi anbefaler ikke at du drikker Stroh 80 rent - nyd den fortyndet eller med mixer efter eget valg.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Ron Prohibido 15 år Solera Rom 40%', 'https://www.uhrskov-vine.dk/el-ron-prohibido-solera-15-reserva-mexican', 329, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/el-ron-prohibido-solera-15-reserva.jpg', 'El Ron Prohibido som betyder “den forbudte rom”, er en mexicansk blended rom, som stammer helt tilbage fra 1700 tallet. Rommen lagret i en 15-års solera system. Rommen har en sød duft og meget intense hints af tørret frugt, rosiner og svesker. Smagen dækker et bredt spektrum bla. vanille, træ, valnød, smør, chokolade og kaffe.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Quorhum 12 Anos Solera Den Dominikanske Republik', 'https://www.uhrskov-vine.dk/ron-quorhum-12-anos-solera-den-dominikanske-republik', 395, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-quorhum-12yo_2.jpg', '12 års Ron Quorhum fra Den Dominikanske Republik, udgivet af Oliver & Oliver. En sød, subtilt urte noter, fyldt med karamel sødme, lakrids og eg.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pampero Aniversario Reserva Exclusiva 40%', 'https://www.uhrskov-vine.dk/pampero-aniversario-40', 269, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/pampero-aniversario_3_1.jpg', 'En lækker premium, gylden rom fra Venezuela, med den høje standard som landet er kendt for. Pampero Ron Extra Anejo er fyldig og meget frugtagtig Rom, med en strålende glat, vedholdende finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Cask Strength 65%, 50cl', 'https://www.uhrskov-vine.dk/ron-patridom-xo-cask', 599, TRUE, 50, 65, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomxoc.png', 'Sød og blødhed der går over i fuld power. Meget intens og fyldig med smag af vanilje, karamel, honning og kanel, meget lang og krydret eftersmag der bare bliver ved og ved. De ekstra procenter giver en ekstra power til smagen som udfolder nuancerne på smukkeste vis.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve Finest Original Saint Lucia Rom 40%', 'https://www.uhrskov-vine.dk/chairman-s-reserve-finest-saint-lucia-rom-40', 325, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/h/chairmanog.png', 'Chairman’s Reserve Original Rum er flagskibet for St. Lucia Distillers, som har vundet adskillige guldmedaljer ved flere forskellige smagninger. Den mørk-gyldne rom et blend af Coffey og pot stills og er gennemsnitligt lagret i 5 år på ex bourbon tønder. Dette giver rommen velbalancerede aromaer og en struktureret smag med en lang cremet finish, hvilket gør Chairman’s Reserve Original Rum til en absolut ”must-have rom”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario Rum 10 Aniversario Cincuenta 50%', 'https://www.uhrskov-vine.dk/ron-millonario-rum-10-aniversario-cincuenta', 335, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04513.jpg', 'Denne rom er sidste skud på stammen i Ron Millonario Familien. Det er den samme rom, som den "mildere" bror (Ron Millonario 10th Aniversario), men denne rom er blot tappet med 50% i stedet for de 40%.Ron Millonario produceres på et destilleri i den nordlige del af Peru. Det har længe været en hemmelighed, hvor det var, men nu har direktør Fabio Rossi afsløret, at der er destilleriet Pomalca i Chiclayo, som ligger i det nordlige Peru. Duft Sød, dyb og rund. Melasse, er det første der rammer næsen, sammen med noter af vanilje, banan og pære og æbler. Kraftig duft, der stammer fra den høje alkoholprocent (50%). Smag Kraftig smag pga. alkoholprocenten, som virkelig får sødmen fra melassen til at blomstre. Noget af mørk chokolade og tørrede frugter. Eftersmag Sødmefuld eftersmag med noter af honning, som samtidig er ren og direkte. Alkoholen sætter igen præg på oplevelsen, men er ikke overvældende. Cremet karakter med noter af cola. Denne rom er sidste skud på stammen i Ron Millonario Familien. Det er den samme rom, som den ’mildere’ bror (Ron Millonario 10th Aniversario), men denne rom er blot tappet med 50% i stedet for de 40%. Kommentar Det høje alkoholindhold, gør noget helt specielt godt ved denne dram - den skal bare prøves!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo 7 år, Añejo Panama Rom, 40%', 'https://www.uhrskov-vine.dk/abuelo-anejo-7-anos-rum-panama-40', 289, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/b/abuelo-7.jpg', 'Abuelo Anejo 7 Anos Rum, Panama har de sidste par år modtaget flere priser. Produceres i Panama af Varela Hermanos, som oprindeligt har lært romhåndværket i Cuba. Meget rund og blød, lidt til den søde side. Indbegrebet af imødekommende Caribisk rom. Næse: Fyldig duft, orange og kandis. Smag: kompleks, sukkeret spiller godt med krydderierne og gør rommen spændende.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM, Blanc Agricole Rom, Martinique 50%', 'https://www.uhrskov-vine.dk/rhum-j-m-blanc-agricole-rom-martinique-50', 309, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/h/rhum-jm-50-blanc-martinique.jpg', 'Denne Blanc Agricole Rom fra Rhum J.M er lavet på sukkerrør som betragtes at være de bedste på Martinique øen. Det er en rom med masser af smagsnuancer, du får bla. noter af tropisk frugt, mango, bananer og Papaya. En meget jordnær Rom som har en aromatisk duft af tropiske frugter, og som har en fyldig, frisk og en anelse tør finish. San Francisco World Spirit Competition 2012: Guld Medalje', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ypioca Reserva Cachaca 38%', 'https://www.uhrskov-vine.dk/ypioca-reserva-cachaca', 239, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/carvalho.png', '.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Jamaican Rom Xaymaca Special Dry 43%', 'https://www.uhrskov-vine.dk/plantation-jamaican-rum-xaymaca-dry', 299, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-xaymaca-special-dry.jpg', 'Xaymaca Special Dry er arketypen af en "old-school" Jamaica rom. 100% pot still destilleret og med udtryksrige smagsindtryk der leder tankerne mod eksotiske bananer og ananas. En rom der bør nydes som en god whisky, eller til cocktails der kræver lidt røg og tørhed. Xaymaca har ligget på tidligere Cognac fade.  Distillation  Clarendon : Pot Still (Vendôme) Long Pond : Pot Still (John Dore) Tropical ageing : 1-3 years in Bourbon casks  Continental ageing : 1 year in Ferrand casks', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Quorhum 15 Anos Solera Den Dominikanske Republik 40%', 'https://www.uhrskov-vine.dk/ron-quorhum-15-anos-solera-den-dominikanske-republik', 449, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-quorhum-15yo_2_1.jpg', 'Denne Ron Quorhum 15 års fra Den Dominikanske Republik giver en særlig fin smagsoplevelse, farven er dyb mørke brun. Den er lagret på Bourbon fade. I duften finder du eksotisk frugt, karamel og rosiner. Smager af honning med overgangen til ahornsirup, og antydninger af karamel og hasselnødder.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation 2021 Black Cask, Barbados & Guatemala Edition 40%', 'https://www.uhrskov-vine.dk/plantation-2021-black-cask-barbados-guatemala-edition-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/blackcask2021.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Guadeloupe Blanc Rom Agricole 50%', 'https://www.uhrskov-vine.dk/rum-nation-guadeloupe-blanc-rom-agricole-50', 275, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-guadeloupe-blanc-agricole.jpg', 'Denne hvide rom fra Rum Nation er en Agricole og har en saltet duft, med noter af grønne oliven og mynte. Smagen er intens uden at være aggressiv, og man får straks smagsnoter af havvand og oliven, en meget appetitvækkende rom. Eftersmagen er meget sukkersød, så den komplementer den saltede smag rigtig godt. Denne rom er perfekt til Cocktails, eller med knust is.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Come Hell or High Water, XO Rum Giftpack 40%', 'https://www.uhrskov-vine.dk/hell-or-high-water-xo-rum-40', 339, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/x/o/xorum.png', 'Hell or High Water er en rom-serie med nøje komponerede blends af rom fra Guyana, Barbados, Jamaica og Den Dominikanske Republik. Udtrykket ”come hell or high water” betyder, at man vil gøre alt for at opnå sit mål, uanset hvilke forhindringer man møder. Det er da klart, at enhver business oplever sine op- og nedture, men de to gutter, Olli og Jouko, har nok haft uforholdsvis mange af de sidstnævnte. De nævner blandt andet en ildebrand i produktionsanlægget, jordskælv, at være tæt på konkurs et dusin gange og én nærdødsoplevelse (hvad??)… Hell or High Water repræsenterer denne lange rejse gennem alskens udfordringer – og som de siger: ”A rough journey makes a smooth rum”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados Rum 20th Anniversary XO Extra Old, Box +2 glas', 'https://www.uhrskov-vine.dk/plantation-barbados-rum-20th-anniversary-xo-extra-old-box-2-glas', 499, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteray2glas.png', 'Denne sjældne og unikke Barbados rom er efterlagret på fine små cognacfade hos cognachuset Pierre Ferrand i hjertet af Cognac i Frankrig. De bløde franske limousine egefade, som først er blevet brugt til modning af den allerbedste Grande Champagne Cognac, bidrager med blød frugt, revet appelsinskal og fine vaniljetoner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Jamaica 5 år Oloroso Sherry Finish 50% (2019)', 'https://www.uhrskov-vine.dk/rum-nation-jamaica-5-ar-sherry-finish-50', 399, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-jamaica-5yo-sherry-finish.jpg', 'Denne Rum Nation rom har en dyb duft af bla. kamfer, sukker og lidt gærede noter. Den har en tør og krydret smag, med antydninger af rosiner og gammelt træ, som er med til at danne baggrund for den sødme der giver det overordnede indtryk. Du får en robust jamaicansk rom, som er gjort blidere og mere rund, ved dens sherryfads-lagring.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Volbeat Rom, Limited Edition 20 års Single Estate Guyana Rum, 40%', 'https://www.uhrskov-vine.dk/volbeat-rum-limited-edition-20-rom-40', 2395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/o/volbeat20.png', 'Volbeat markerer sit 20-års jubilæum ved at udgive en sjælden rom i et meget begrænset antal. Volbeat kunne i 2021 fejre sit 20-års jubilæum - og som sanger og guitarist Michael Poulsen siger, så er det er vigtigt at fejre de gode ting i livet. Derfor gik Volbeat på jagt efter den perfekte rom, som ville være værdig til at markere og fejre denne store milepæl for det internationalt anerkendte og grammy-nominerede danske rockband. Volbeat har efter lang tids søgen nøje udvalgt denne 20-års jubilæumsrom fra Guyana i det nordlige Sydamerika. Denne rom, som er tappet på eksklusive flasker med Volbeat skullwing-vedhæng i Danmark, har været lagret 20 år på amerikanske egetræsfade i Guyana. Det er en helt igennem unik single estate rom, som kun er produceret i 2.400 nummererede flasker, der er tappet fra ni forskellige fade, som Volbeat selv har udvalgt til deres helt specielle 20-års jubilæumsrom. Hver enkelt flaske er nummereret med både fad- og flaskenummer, og rommen leveres i Volbeats nøje udvalgte jubilæumsemballage. "Vi har lagt en stor indsats i at vælge den rigtige flaske og lave en eksklusiv emballage, der afspejler Volbeat-ånden," siger Michael Poulsen. En lækker og helt fantastisk rom med fyldig og ren smag med noter af vanilje, egetræ og læder - og så er den lagret til perfektion i netop 20 år, så både Volbeat og Volbeat Limited Edition Rum har fælles rødder i 2001. Mens Michael Poulsen og Jon Larsen lagde grunden til, hvad der skulle blive de allerførste Volbeat-sange i Danmark, begyndte Diamond Distillery at destillere det, der skulle blive Volbeat Limited Edition Rum på den anden side af Atlanten i Guyana. Volbeat Limited Edition Rum var oprindeligt planlagt til at komme på hylderne i 2021, det officielle år for Volbeats jubilæum, men blev forsinket på grund af generelle forsyningskædeudfordringer, hvor især efterspørgslen efter flaskeglas gjorde det umuligt. Det er dog historie - nu er den her, klar til at blive nydt blandt gode venner og god musik. ”Vi hå', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dictador 20 år Solera Rom, Columbia 40%', 'https://www.uhrskov-vine.dk/dictador-20yo-solera-icon-reserve-rom-columbia', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/dic20.jpg', 'Dictador serien er en solera-lagret colombiansk rom med en helt unik smag. Serien består af Dictador 12 år, 20 år og 2 XO-udgaver. Allerede fra 12-års udgaven får man rom af en høj kvalitet. Det er værd at bemærke, at Dictador Rum er lavet på Solera-metoden, hvor man angiver rommens maksimum-alder. Dette er en anderledes rom-stil, som man på et eller andet tidspunkt bør prøve..', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Luxus Barbados-Guyana Rom, 40%', 'https://www.uhrskov-vine.dk/dos-maderas-luxus-10-5-barbados-guyana-rom-40', 1249, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dos-maderas-luxux-10-5_2.jpg', 'Master blenderen udvælger nøje mellem de mest eksklusive rom fra Barbados og Guyana. Når den ønskede blanding er fundet, lagrer man rommen 10 år i Caribien. Efter denne del af lagringsprocessen, bliver blandingen sejlet over Atlanten, til Williams & Humbert i Spanien, hvor anden del af lagringen begynder.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM XO Tres Vieux Agricole Rhum, Martinique 45%', 'https://www.uhrskov-vine.dk/rhum-j-m-xo-agricole-rom-martinique-45', 599, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/h/rhum-jm-xo-martinique_2.jpg', 'Et god aldret agricole rom fra Martiniques Rhum JM. Den har en dyb farve og stor aroma efter års modning i gamle Bourbon fade. Den har en generøs buket af ristede noter og citron, som komplimenterer de søde toner af mango og passionsfrugt. Oplevelsen er er forstærket af et strejf af peber, kanel og muskatnød. Concours Mondial de Bruxelles 2012 : Guld Medalje Rhum JM X.O Tres Vieux er en rhum agricole fra Martinique. Den er lavet på frisk sukkerrørssaft og har ligget minimum 6 år på egetræsfade, der før har været brugt til bourbonlagring. Til sidst er den tappet ved ganske fornuftige 45% alkohol. Resultatet er en helt klassisk agricole-rom, der kombinerer det bedste fra den tropiske fadlagring med friske noter af sukkerrør og det martinikanske terroir. Farve:  Rav. Duft:  Egetræsnoter (brunet smør og vanilje), tørret frugt og ingefær. Smagsnoter:  Fyldig og krydret i munden, med noter af ingefær, nødder og hints af vanilje. Serveringsforslag:  Bør nydes rent. Den plantage, hvor  Rhum JM  produceres i dag, var oprindeligt blot et sukkerraffinaderi, men da Jean-Marie Martin købte ejendommen i 1845, skiftede han fokus fra sukker til rom. Jean-Marie havde hurtigt spottet, at de unikke forhold i markerne for foden af Mont Pelée skabte sukkerrør af en uovertruffen kvalitet, som ville gøre sig fortrinligt i rhum agricole. Og den dag i dag dyrker man stadig 100% af destilleriets sukkerrør på de stejle skråninger af den vældige vulkan. JM fremhæver 4 ting, der er afgørende for terroiret: den frodige, vulkanske jord, den tropiske fugtighed fra det lave skydække, ventilationen fra havbrisen der blæser ind på vulkanen og køler markerne ned samt den gode dræning i de stejle bjergsidemarker. For at bevare alle sukkerrørets aromaer presses de indenfor 1 time af høsttidspunktet! Ved siden af destilleriet og markerne ligger kældrene, hvor en del af rommen lagres i længere perioder. Ved JM bruger man fortrinsvis bourbonfade af amerikansk egetræ, men nu og da ses også nye, ubrugte fade', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s 12 år Fine Old Rum, Barbados 43%', 'https://www.uhrskov-vine.dk/doorly-s-12-ar-fine-old-rum-barbados-43', 429, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/doorlys_fine_old_rum_12_yo_barbados.png', 'Doorly''s 12 år Fine Old Barbados Rum er lagret 100% i 12 år, og den er som det øvrige rom fra Foursquare en blanding af potstill rom (ca. 10%) og kolonnedestilleret rom (ca. 90%). En fremragende 12 år gammel Barbados med unik kompleksitet og fylde. Stor Rom og ikke mindst til pengene !!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Ron Prohibido 12 år Solera Rom 40%', 'https://www.uhrskov-vine.dk/el-ron-prohibido-12-ar-rum-40', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/el-ron-prohibido-12yo_1.jpg', 'El Ron Prohibido som betyder “den forbudte rom”, er en mexicansk blended rom, som stammer helt tilbage fra 1700 tallet. Rommen lagret i en 12-års solera system. Modnet i tønder, der har været brugt til søde rosin vin, det er en sød rom med bitre noter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Isle of Fiji Rum 40%', 'https://www.uhrskov-vine.dk/plantation-isle-of-fiji-rum-40', 329, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50641076.jpg', 'Det er med stor fornøjelse vi kan præsentere den nyeste tilføjelse til Plantations ”Signature Blends”-serie: Isle of Fiji! Vi har i lang tid været enormt begejstrede over rommen fra South Pacific Distillery i Fiji, og Plantations udgave spiller på alle de rigtige tangenter, mens en fin sødme (16 gram sukker per liter) gør den nem at gå til, også for begyndere. Rommen er sammensat af komponenter destilleret på både pot stills og Coffey still, og den er lagret først på bourbonfade, for så at få Plantations karakteristiske ”finish” på cognac-fade. Det hele hænger utroligt godt sammen, og vi må endnu engang sande, at dette totalt undervurderede destilleri giver de fleste af sine caribiske konkurrenter kamp til stregen. .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Come Hell or High Water Spiced Rum 38%', 'https://www.uhrskov-vine.dk/hell-or-high-water-spiced-rum-38', 199, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/p/spiced.png', 'Come Hell or High Water Spiced Rum er skabt af One Eyed Spirits. De har hyret rom-stjernen Don Pancho Fernandez, som har 50 års erfaring som master blender, til at kreere det perfekte blend, og han har valgt forskellige rom fra Trinidad, som er smagt til med sukker, vanilje og andre eksotiske krydderier. Den kraftige, krydrede smag er pakket fint ind i karamelsødme og eftersmagen er lang og varmende. Farve : Mahogni. Duft : Intens duft af smeltet smør, vanilje og egetræ. Smagsnoter : Stor sødme og noter af karamel, banan, allehånde, nelliker og vanilje. Lang, varmende eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate 21 år Single Estate Rum Jamaica, 43%', 'https://www.uhrskov-vine.dk/appleton-estate-21-ar-single-estate-jamaica-rum', 949, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/p/appleton.jpg', 'En overdådig blanding af de fineste lagrede rom fra Appleton Estate. Denne 21 års rom er en utrolig elegant og kompleks rom, som udgør et unikt blend af de bedste håndvalgte fade fra Nassau Valley. Alle fade bringer sit til den samlede unikke karakter og lagret tropisk i mindst 21 år.  Resultatet er en luksus rom med bemærkelsesværdig finesse og kompleksitet. Appleton Estate 21 Year Old Nassau Valley Caks er en hyldest til deres ejendoms frodige og frugtbare hjem siden 1749 i Jamaicas Nassau Valley. Aromaen af appelsinskal, muskatnød, vanille, mandler, kaffe og kakao, mens smagen tilfører noter af nødder, melasse og eg.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XII Two Oaks Panama Rom 40%', 'https://www.uhrskov-vine.dk/abuelo-two-oaks-panama-40', 549, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04721_1.jpg', 'En fantastisk blød smag - der tænder op for en ny lidenskab overfor rom. Abuelo Two Oaks er en dejligt blød 12 år gammel rom, der er blevet modnet i to karakteristiske egetræsfade. Først i udvalgte ex-bourbon fade, derefter i helt nye men ekstra forkullede fade af amerikansk eg. Fadene tilberedes af eksperter i Napa Valley, Californien. De udvælger dem, rister dem ved 180 ° C i 60 minutter for at forsigtigt åbne træet og skruer derefter varmen op til 220 ° C for at få den dybe forkullning på 8mm, som de gerne vil have. Denne totrinsproces, gør det muligt for rommen at trække ekstremt meget smag fra træet og der skabes et naturligt kulfilter, der giver en usædvanligt blød Two Oaks finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Seleccion de Familia Rum 43%', 'https://www.uhrskov-vine.dk/diplomatico-seleccion-de-la-familia-43', 499, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplomatico-seleccion-de-familia.jpg', 'Modnet i 12 år i en kombination af amerikansk hvid eg, ex-bourbon og ex-sherry-fade, Diplomatico Seleccion de Familia er en kompleks rom med en tør, bittersød kant sammen med noter af karamelliserede bananer, hvid peber, ingefær, rosiner og figner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('R.L. Seales Barbados Rom, 46% 70cl', 'https://www.uhrskov-vine.dk/rl-seales-barbados-rom-46-70', 399, TRUE, 70, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/e/sealesrom.jpg', 'Der er 4 destillerier på Barbados, som alle laver en speciel romstil, som kaldes ”Barbados stil.” Den kraftige og aromatiske rom laves på pot still destillationskedler, som vi kender fra whiskyverden. Den blide og afrundede rom laves på mere moderne kolonne destillationsanlæg. Begge typer rom indgår i den traditionelle Barbados rom blanding. Foursquare Destilleriet lægger desuden meget stor vægt på at være miljøvenligt og hele destilleriet er lavet af et italiensk ingeniørfirma (Green Engineering) i 1996. Alle organiske affaldsprodukter bliver renset og genbrugt som gødning på sukkerrørsmarkerne. Selv det co2 som dannes ved gæringsprocessen opsamles og renses, så det kan bruges i øl eller sodavandsproduktion.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve, The Forgotten Cask Finest Saint Lucia Rom, 40%', 'https://www.uhrskov-vine.dk/chairman-s-reserve-finest-saint-lucia-rom-the-forgotten-cask-40', 435, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/forgotten-casks.jpg', 'I 2007 ramte en voldsom brand destilleriet på Saint Lucia. Under genopbygningen måtte kældermesteren improvisere og finde nye steder til lagringen af fadene – og i processen blev enkelte fade glemt. Først fire år senere dukkede de op igen, efter at have lagret markant længere end planlagt. Resultatet var en rom med en helt særlig og uventet karakter. Som en hyldest til denne historie har Chairman’s Reserve skabt The Forgotten Casks – en ekstra-lagret rom med dybde og personlighed. Hos Uhrskov Vinhandel er vi vilde med netop denne type rom, hvor historien kan smages i glasset.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s XO Fine Old Rum, Barbados 43%', 'https://www.uhrskov-vine.dk/doorlys-xo-fine-old-rum-barbados-40', 359, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/doorlyxo.jpg', 'Doorly''s XO Fine Old Rum er et unikt blend af gammel rom, som ekstraordinært fadlagres i spanske Oloroso Sherry egetræsfade. Det er ganske uhørt i rom branchen, og det gør Doorly''s XO til en unik rom med masser af kompleksitet, fylde og balance.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Edicion Negra Solera Gran Reserva 43%', 'https://www.uhrskov-vine.dk/ron-zacapa-edicion-negra-43', 699, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/z/a/zacapaedicionnegra.png', 'Inspireret af traditionelle maya ritualer, er denne “slow-aged” rom siges håndværksmæssigt at være et sandt udtryk for Guatemalas arv og kultur. Produceret af sukkerrør dyrket i vulkan-skygget lavland og lageret 2.300 meter over havets overflade i den kølige luft i Guatemalas højland i amerikanske egetræsfade, resultatet er en mørk rom med en røget intensitet og accentueret eg og krydrede noter. Så denne Zapaca tager et skridt væk fra de søde flødekaramel noter som identificeret i Zapaca 23.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Albion 2004 El Dorado Rare Collection Silver Edition, Demerara 60,1%', 'https://www.uhrskov-vine.dk/albion-2004-el-dorado-rare-collection-silver-edition-demerara', 1895, TRUE, NULL, 60.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/l/albion-2004-el-dorado-rare_1.jpg', 'Distilled in 2004 – Single Still • Single Still – Single Marque Bottled at cask strength of 60,1% in 2018  •  100% Continuous ContinuousCoffey Still  •  Non-Blended / Non-Chill Filtered  •  100% Tropically aged in Guyana for at least 14 years.  Lightamber color.  Smell: Rich notes of molasses, vanilla, burned sugar and cocoa with an elegant spiciness.  Taste: Sweet with brown sugar, toffee, caramel and honey. In good balance with the bitterness of the wood.  Very long finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Peruano 8 år Rum Limited Edition 42%', 'https://www.uhrskov-vine.dk/rum-nation-peruano-8yo', 299, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05054.jpg', 'Denne 8 års Rum Nation rom har en smøragtig duft som er meget sød, nærmest en mælkechokolade-agtig duft. Smagen er rig og intens, men ikke for skarp. Smagsnoterne er rosin, figner, dadler, kanel, peber og behagelige tanniner. Den har en slags pebret eg finish, lidt fløjlsagtig med cola og sukkerte. En nem og sød rom, med et strejf af krydderi.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Mantuano Ron Extra Anejo 40%', 'https://www.uhrskov-vine.dk/diplomatico-mantuano-ron-extra-anejo-40', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/manutano.png', 'Don Juancho Meléndez hvis portrait er afbilledet på flasken, han var en mand der drømte stort og han var inspirationen bag Diplomatico Rum. Han havde titlen "Mantuano", hvilket er titlen på en lokal adelsmand og han brugte sin tid på at raffinere smagen på den fineste rom - det var hans passion. Don Juancho havde været stolt over denne udgivelse, en ekstraordinær blend af forskellige 8 års rom. Med hints af tør frugt, træ og vanilje. Det er den ideelle ingrediens til en sofistikeret cocktails er også velegnet helt plain som den er.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dictador 12 år Solera Rom, Columbia 40%', 'https://www.uhrskov-vine.dk/dictador-12-ar-solera-rom-columbia-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/dictador12.jpg', 'Duft af varm cremet vanilje og karamel, med toner af brændt honning og mælkechoklade. I smagen fornemmes blød og sød karamel og vanilje, kakaopulver og lidt sød lakrids. Eftersmagen er temmelig fedmefyldt og olieret med knassende rørsukker og et let strejf af kanel. Elegant rom i Caribisk topklasse. Dictador Rum destilleres delvist i kobber Pot Stills og Kontinuerlige Stills.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Santiago De Cuba 12 Års Extra Anejo, Cuba 40%', 'https://www.uhrskov-vine.dk/ron-santiago-de-cuba-12-aar-extra-anejo-386', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/santiago_de_cuba_12.jpg', 'Ron Santiago de Cuba Añejo Superior 12 Years Old er en rom lavet på sukkerrørsmelasse og destilleret på kolonnekedler i ”den lette roms vugge”, Santiago de Cuba. Rommen er lagret på en blanding af brugte og nye fade af amerikansk hvideg i minimum 12 år – i Cuba refererer alderen på etiketten til den yngste bestanddel i blendet, her er ingen ”solera”!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clément Rhum Blanc Agricole, Martinique 40%', 'https://www.uhrskov-vine.dk/clement-blanc-agricole-rom-martinique-40', 249, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/6/1/61qlqq5qh2l._sy741_.jpg', 'Clément blanc agricole rom er lavet af det bedste udvalg af de fineste sukkerrør fra Clement gården i Martinique. Sukkerrørene bliver høstet så tæt på jorden som muligt for at få den højeste koncentration af sukrose (sukker). Derefter bliver de destilleret ganske tæt på selve sukkerrør-marken for at bevare og sikre sig den friskhed man finder i denne udsøgte agricole rom, som betyder at den ikke er sødet efter den er destilleret. Clément Blanc Premiere Canne er gæret og destilleret på frisk sukkerrørssaft. Efter destillationen hviler den 9 måneder i ståltanke før frigivelse. Rommen er ikke fadlagret og bevarer alle derfor alle de friske sukkerrørsaromaer. En flot fremvisning af det martinikanske terroir!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XV 15 års Napoleon Cognac Cask Finish, 40%', 'https://www.uhrskov-vine.dk/abuelo-rum-xv-napoleon', 629, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/n/a/napoleonpog.jpg', 'Ron Abuelo XV 15 års Napoleon Cognac Cask Finish Rum er en mørk Panama rom med bløde noter af tørret frugt og kaffe. Abuelo Napoleon er blot en ud af en spændende triologi fra Abuelo. De 2 andre rom i serien har lagt på delvis "Sherry Finish" og en på "Port Finish". Abuelo Napoleon Cognac Cask Finish er lagret på amerikanske bourbonfade og efterlagret på Cognacfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Santiago De Cuba 11 Års Anejo Superior, Cuba 40%', 'https://www.uhrskov-vine.dk/ron-santiago-de-cuba-11-aar-extra-anejo-42', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/santiago_de_cuba_11.jpg', 'Ron Santiago de Cuba Añejo Superior 11 Years Old er en rom lavet på sukkerrørsmelasse og destilleret på kolonnekedler i ”den lette roms vugge”, Santiago de Cuba. Rommen er lagret på en blanding af brugte og nye fade af amerikansk hvideg i minimum 11 år – i Cuba refererer alderen på etiketten til den yngste bestanddel i blendet, her er ingen ”solera”!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo Centuria Reserva De La Familia, 30 år Solera Rum, 40%', 'https://www.uhrskov-vine.dk/abuelo-centuria-reserva-de-la-familia-30-ar-solera-rum-40', 1199, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/b/abuelo-centuria-reserva-de-la-familia_3.jpg', 'Ron Abuelo Centuria Reserva de la Familia er en af verdens helt store rom. Ikke mindre end en fantastisk oplevelse. Og der er en grund til at Centuria er kåret som Bedste Nye rom ved Golden Rum Barrel Awards Oktober 2011 i London. Abuelo Centuria har også opnået 95/100 points på Romhatten.dk', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate Signature Blend 40%', 'https://www.uhrskov-vine.dk/appleton-estate-signature-blend', 235, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/signature.jpg', 'Appleton Estate Signature Blend er en “blended rom”, hvilket betyder, at det er en kombination af flere rom af forskellige stilarter og aldre og og har derfor ikke selv en aldersbetegnelse. Denne Jamaicanske Rom er en blanding af 15 forskellig rom, i en alder på gennemsnitligt 4 år. Rommen er afbalanceret, med kompleks citrus, frugtagtige og søde noter, med subtile appelsinskal, tørret abrikos, frisk fersken, og en antydning af melasse og træagtige noter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO, Den Dominikanske Republik 42%', 'https://www.uhrskov-vine.dk/ron-patridom-xo-42', 579, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomxo.png', 'Ron Patridom serien består af fire aftappninger med hver deres egen fascinerende smagsegenskab. Rommen destilleres af Alcoholes Finos Dominicanos, der kun forarbejder deres egen sukkerrør, hvilket sikrer at der kun benyttes Dominikanske sukkerrør. Ron Patridom XO er en premium rom fremstillet af både frisk sukkerrørsjuice og melasse. Rommen lagres i Den Dominikanske Republiks tropiske klima, i amerikanske og franske egetræsfade, i en periode fra tolv til femten år.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco 20 år Reserva Rom, Panama 40%', 'https://www.uhrskov-vine.dk/malteco-rum-20-ar-reserva-guatemala-41', 499, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-malteco-20-years-old-reserva-del-fundador-41.jpg', 'På næsen har Malteco 20 noter af krydderier, tobak, samt noter af toast/ristet brød og egetræet. På tungen er den intens og vedholdende, Krydderierne og tobakken kommer tydeligt igennem, der er også lette noter af vanille. Malteco 20 har en super lang finish, med vanille, egetræ og sødme. Malteco 20 fås i 70cl og i 20cl størrelser.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 3 Batch 1, Bellevue 23 års Rum, 55,5%, RomDeluxe', 'https://www.uhrskov-vine.dk/bellevue-23-collectors-series-rum-3-1-romdeluxe-55-5', 1259, TRUE, NULL, 55.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/bellevuebatch1.png', 'Denne rum er destilleret på Bellevue destilleriet. Destilleriet ligger i hjertet af den største sukkerrørs plantage på øen Marie Galante i Guadeloupe. Godset Bellevue au Moule og deres destilleri blev etableret i slutningen af 1800 tallet. Deres berømte vindmølle er bygget tilbage i 1821. Bellevue er i øvrigt det første destilleri i Caribien som har forpligtet sig til at beskytte miljøet ved at have en 100% ikke forurenende produktionsproces. Rommen er en yderst sjælden gammel aftapning på hele 23 år Det er en single cask aftapning af ren kolonne destilleret rom, baseret på melasse. Den er lagret/modnet både tropisk og kontinentalt i bourbon fade, hvor der ikke er tilsat hverken farve eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Barbados 8 år - Limited Release 40%', 'https://www.uhrskov-vine.dk/rum-nation-barbados-8-limited-release-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05038_-_rum_nation_-_barbados_8_yo_-_gb.png', 'Rum Nation, en verdensomspændende romserie, udelukkende bestående af udvalgte fade fra et og samme destilleri. Resultatet er et udvalg af ”single rom” i en begrænset mængde, tro mod spiritussens hjerte, unik og uforglemmelig. Bliv en ”Citizen of Rum Nation”, det er en fantastisk rejse gennem en verden af rom! En sødere og mere frugtagtig udgave af vores berømte Barbados rum. Lagret i 8 år i et tropisk klima. Den har den en vedvarende fløjlsagtig mundfølelse og en rundhed, der gør den særlig velegnet til en eftermiddag', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus 25 år Barricas de Malt Whisky Finish 43%', 'https://www.uhrskov-vine.dk/opthimus-25-ar-barricas-de-malt-whisky-finish', 799, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/p/opthimus-whisky-finish-25yo_2.jpg', 'En spændende spirit drink, som er sendt på marked af Oliver & Oliver med base i Den Dominikanske Republik. Firmaet har ikke selv et destilleri. Deres spidskompetence er, at opkøbe romdestillater i Carribien og så blande den på bedste vis. Det er altid en hemmelighed, hvilke rom, der indgår i de forskellige blends. Det er dog ikke nogen hemmelighed, at en stor del af dem stammer fra Cuba, hvor Oliver familien har sine rødder, og havde et romdestilleri i slutningen af det 18. århundrede. Den øvrige rom er fra Panama, Trinidad, Colombia og Nicaragua, men en stor del kommer også fra deres egen ø, Den Dominikanske Republik. Da de grundlagde firmaet, hyrede de nogle cubanske destilleriarbejdere og fik lov til at købe omkring 100.000 liter god cubansk rom. Så med lidt god vilje kan man sige, at firmaet har gode cubanske rødder. Næse Honning, kandis, sirup, moden frugt en snert af malt whisky. Utrolig fantastisk duft. Smag Markant sødme, nougat smelter ned i tungen, meget fed og fyldig rom. Krydderi fra malt whiskyen Tomatin Eftersmag Lang, fyldig eftersmag. Luftige krydderier og en sød hale. Fuldendt symbiose af rom og whisky', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Rum Caraibes 40%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-rum-caraibes-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/n/indes-caraibes-40pct_2.jpg', 'Compagnie des Indes Rhum Caraibes er spændende blended Rom fra en af branchens seneste og nye uafhængige aftapper. Florent Beuchet fra Compagnie des Indes blender sin egen rom, som spænder fra et lækkert sødmefuldt latinsk inspireret blend, til et mere krydret og fyldigt fransk og engelsk blend bestående af suveræne rom´s fra Guyana, Trinidad og Barbados.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Santiago De Cuba 20 Års Extra Anejo Gran Reserva, Cuba 40%', 'https://www.uhrskov-vine.dk/ron-santiago-de-cuba-20-aar-extra-anejo-gran-reserva-40', 1995, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/2/0/20yo-bottle.jpg', 'Ron Santiago de Cuba Extra Añejo 20 Years Old er en rom lavet på sukkerrørsmelasse og destilleret på kolonnekedler i ”den lette roms vugge”, Santiago de Cuba. Med denne rom nærmer vi os toppen af poppen hos destilleriet, som første gang frigav en 20-år gammel rom for at fejre byens 485-års jubilæum. Forvent masser af dybde og kompleksitet', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Meticho Rum & Citrus 40%', 'https://www.uhrskov-vine.dk/rum-nation-meticho-rum-citrus-40', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/e/metichorumcitrus.png', 'En blanding af smagen fra italienske appelsinskal og en blød mellemamerikansk rom, hvor den specielle opskrift også indeholder andre citrusfrugter, såsom rød appelsin, citron og mandarin. Et tydeligt strejf af ægte vanilje og et par dråber af hemmelige aromaer, kategoriserer denne rombaserede spiritus. Resultatet er let, sød og honningfyldt likøragtig drik - præcis så glat og frugtagtig som det det skal være! Drik den ren efter middagen eller n yd den kold eller med isterninger - en forfriskende  oplevelse! Den Perfekte Meticho "Mørk og Stormfuld" Cocktail Isterninger i et glas 1 del Meticho 3 dele Franklin & Sons Ginger Beer 2 stk limebåde Går også udemærket i en Rom & Cola eller Rom & Lemon Isterninger i et glas 1 del Meticho 2-3 dele Cola / Franklin & Sons Lemon Tonic Citronskive', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate 8 Års Reserve Blend Jamaica, 43%', 'https://www.uhrskov-vine.dk/appleton-estate-reserve-blend-43', 279, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/e/reserve.jpg', 'Appleton Estate Reserve Blend er en "blended rom«, hvilket betyder, at det er en kombination af flere rom af forskellige stilarter og aldre, derfor har denne Rom ikke en specifik aldersbetegnelse. Der er udvalgt 20 rom med et gennemsnitsalder på 8 år. Appleton Estate Reserve Blend en Jamaicansk Rom der er fyldig, glat og med fine afbalancerede krydder og nøddeagtig noter, efterfulgt af noter af honning, vanille, og en antydning af hasselnød - alt sammen pakket ind i rig tørret appelsinskal.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk & Sweeney 12 år Reserva Den Dominikanske Republik 45%', 'https://www.uhrskov-vine.dk/kirk-sweeney-12-ar-den-dominikanske-republik', 499, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/w/sweeney12.png', 'En 12 -årig Dominikansk rom, udvalgt af The Other Guys (den berømte Californiske vinproducent) og opkaldt efter "ROM-skonnerten", der smuglede Rom fra Caribien til det nordøstlige USA under forbudstiden i det gamle Amerika. Skibet blev beslaglagt i 1924, men rommen kan du få lige her.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clément XO Rhum Vieux Agricole, Martinique 42%', 'https://www.uhrskov-vine.dk/clement-xo-rhum-agricole-martinique', 599, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clementxo.png', 'Clément XO er en del af Cléments ”Grand Reserve”-serie, som dækker over destilleriets ældre og mere eksklusive aftapninger. Rommen bærer betegnelsen XO, som efter Martiniques AOC-forskrifter betyder, at den er lagret minimum 6 år. I dette tilfælde er der tale om både ”virgin” (ubrugte) fade, og brugte, re-charred fade. Rommen er naturligvis lavet på frisk sukkerrørssaft…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Panama Decanter 18 år 40%', 'https://www.uhrskov-vine.dk/rum-nation-panama-18yo-solera-40', 529, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-panama-18yo_1_1.jpg', 'Denne Panama rom fra Rum Nation er med ny emballage og karaffelflaske, både farverig og livlig. Det er en ny og forbedredt udgave af vores søde og bløde Panama 18 år. Sukkerrørets rigdom og finessen i den spanske destillations stil, giver liv til en lys rom med en stor aromatisk kompleksitet, rig på tropiske frugter, dadler og chokolade. Sukkerindholdet er reduceret til under 20 gr/liter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clément Canne Bleue, Blanc Agricole 50%', 'https://www.uhrskov-vine.dk/clement-canne-bleue-50', 299, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clement-canne-bleue-50.jpg', 'Skabt med den intense aromatiske saft ved kun at benytte de blå sukkerrør, hvilket giver en usædvanlig hvid rhum. Clément Canne Bleue hviler i mere end seks måneder i et rustfrit stål fad. Destilleret med vulkansk kildevand, der skaber en bemærkelsesværdig, velintegreret, fyldig, hvid Rhum Agricole, fyldt med karakter og smag. Lette aromaer og smag af frisk marengs, pulveriseret sukker, agurk og smidige frugtnoter, men stadig med en tør fyldig krop.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus 15 år Solera Oporto Finish, Den Dominikanske Republik, 43%', 'https://www.uhrskov-vine.dk/opthimus-oporto-15solera-oporto', 499, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/p/opthimus-oporto-15yo_2.jpg', 'Opthimus Rum 15 års Oporto er en begrænset speciel aftapning af en vidunderlig rom fra Oliver & Oliver Int. Distillery. Lagret i 15 år og afsluttet i de tidligere portvinsfade med en stor duft af honning, vanille og masser af frugt.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Monarch St. Lucia Rum, 40%', 'https://www.uhrskov-vine.dk/admiral-rodney-monarch-rum-40', 559, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/o/monarch.png', 'Admiral Rodney HMS Monarch Rum er et godt, gennemmodnet og vellavet produkt, som byder på pæn dybde og en god kompleksitet. Og hvis man har en sød tand, så vil jeg sige, at det er en af de bedre sødet romaftapninger på markedet. - Romhatten.dk En søstærk rom fra St. Lucia, udviklet og tappet eksklusivt til Danmark! Admiral Rodney HMS Monarch er opkaldt efter skibet af samme navn, som bl.a. deltog i Slaget om Skagerrak. Rommen er lavet på melasse og destilleret på kolonnekedler, hvorefter den er lagret på både bourbonfade og portvinsfade, hvilket giver den fyldige rom masser af rød frugt og et strejf af sødme. Farve : Mahogni. Duft : Noter af rosiner og vanilje og et touch af røde bær. Smag : Blød og sødmefuld med behagelig farin, konfekt og kandiseret frugt inden en lang eftersmag stjæler showet med hint af egetræ og varme krydderier i en balanceret og kompleks oplevelse. Serveringsforslag : Bør nydes rent', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Carribbean Rom Ron Anejo 5+3 år 37,5%', 'https://www.uhrskov-vine.dk/dos-maderas-rom-5-3', 299, TRUE, NULL, 37.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dos-maderas-5-3_2.jpg', 'Dos Maderas 5+3 rom er en gylden rom med lys, ravgul farve. Unik blend af rom fra Caribien med 2-trins lagringsproces, der skaber en forældet rom med unik karakter. Tør, men blød og harmonisk afrundet smag med strejf af tørret frugt, krydderi og karamel. Noter af vanilje og let sherry impact. Dos Maderas 5+3 rom lagres 5 år i Caribien i amerikanske egetræsfade og herefter 3 år i 20 års Dos Cortados sherryfade i Williams & Humberts Bodega i Jerez, Spanien.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation 2022 Black Cask, Barbados & Cuba Edition 40%', 'https://www.uhrskov-vine.dk/plantation-2022-black-cask-barbados-cuba-edt-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/u/cubabc.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Ron Millonario XO Reserva Especial, Peru, 40% 150 cl', 'https://www.uhrskov-vine.dk/ron-millonario-xo-reserva-especial-peru-40-magnum-150-cl', 1895, TRUE, 150, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-millonario-xo-reserva-mg_2.jpg', 'Limited Edition af deres XO Solera blot i "voksen-størrelse". Kun 38 flasker kom til Danmark. Ron Millonario XO er efter mærkets ejer, Fabio Rossi: ”magic in a bottle”. men er ca. 15-20 år gammel rom og lavet på solera metoden. Dette gør den til en af de ælste sydamerikanske rom. Fabio Rossi udvælger kun de bedste fade til denne rom, hvilket gør denne rom helt sublim.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa LA PASION Heavenly Cask Collection 40%', 'https://www.uhrskov-vine.dk/ron-zacapa-la-pasion-the-passion-cask-40', 649, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ronzacapalapasion.png', 'Perfekt balance med noter af røde bær, blommer, rosiner, kaffe, chokolade og silkebløde indtryk af pekannødder og karamel. Fyldig, rund og bare dejlig.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 21 År Black Decanter, Panama 43%', 'https://www.uhrskov-vine.dk/rum-nation-21-black-decanter-panama-43', 749, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04909.png', 'Rum Nation Panama 21 år Decanter Black er en blended rom, produceret af håndværkere, der udøver sin ekspertise på det bedste destilleri i Panam - Varela Hermanos Destillery.  Rum Nation Panama 21 år er fremstillet af sukkerrørmelasse, kontinuerligt destilleret i kolonnedestillationsaparat og modnet lokalt i Amerikanske tønder af egetræ (Quercus alba) i mindst 21 flere år. Opskriften inkluderer en stor procentdel endnu ældre rom for at give karakter og kompleksitet. Et resultatet af ​​årtiers eksperimentering og en lang tradition med elegance, tyk sødme og tørret frugt ... Den perfekte deluxe rom til enhver begivenhed!  Panama 21 Decanter Black kommer i en luksuriøs gaveæske. Duft  Stor påvirkning af sukkerrøret, dyb, mørk, rosinagtig, med et vinagtigt tip fra sherry og brandy fade Smag  Tunge noter af sukkerrør og meget rig på ester. Intens sødme med dadler, rosiner, honning og chokolade. Bliver end mere aromatisk med medicinske urter, cinchona, bergamot, sort te og kaffe Eftersmag  Mere og mere krydret med kanel og peber. Sødmen er i perfekt balance med den egagtige indflydelse. Lang, evig, sej og tyk Kommentar  En vidunderlig gammel spansk stil, rig på sukkerindhold, men med en dyb og raffineret indflydelse fra fade. Ideel til kendere af den søde Latinerstil på udkig efter kompleksitet og krydderier!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Sajous Haiti 54,2%', 'https://www.uhrskov-vine.dk/clairin-sajous-54-2', 489, TRUE, NULL, 54.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairin-sajous-53pct_2.jpg', 'Clairin Sajous er en hvid rom fra destilleriet Chelo i Magny, Haiti. Rommen laves på 100% frisk sukkerrørssaft fra rør af typen Cristalline, som koges ind til en sirup der kan bruges også længe efter høsten. Denne sirup fermenteres med vildgær og destilleres på en pot still. Rommen er tappet uden nogen former for tilsætningsstoffer, denne batch ved 54,4% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom Selección Exclusiva 12 Solera 40%', 'https://www.uhrskov-vine.dk/ron-patridom-selecion-exclusiva-rom-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/p/rp20-e1646729337621.png', 'Patridom Seleccion Exclusiva er en rombaseret spiritus lavet på både melasse og frisk sukkerrørsjuice. Efter destillering har denne "premium spirit drink" lagret på amerikanske og franske egetræsfade i tropisk klima i Den Dominikanske Republik. Lagringen foregår i mellem 6 og 12 år, og her udvikles duft og smag. Patridom Seleccion Exclusiva dufter af sødt bagværk, budding, karamel og vanilje og har kraftige smagsnoter af mørk sukker, kokosnød og vanilje.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Meticho Coconut 40%', 'https://www.uhrskov-vine.dk/rum-nation-meticho-coconut', 279, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/p/spir6602.jpg', 'Meticho Coconut - Smagen af paradis - på flaske Skibsbruden. Solbrændt. Barfodet i det varme sand. Du vågner på en glemt ø, hvor luften er tung af havsalt og sød kokos. Palmetræerne hvisker historier om eventyr, og i hånden har du en flaske, der sender dig direkte til paradis. Meticho Coconut er din tropiske fristelse – en cremet, blød spiritus med smag af solmoden kokosnød, rundet af med silkeblød karamel, vanilje og et strejf af tropisk chokolade. Lækker, forførende og lidt vild – perfekt til cocktails, over is… eller bare ren nydelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wray & Nephew White Overproof Rum, Jamaica 63%', 'https://www.uhrskov-vine.dk/wray-nephew-white-overproof-rum-jamaica-63', 249, TRUE, NULL, 63, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50642400.png', 'Wray & Nephew White Overproof Rum er en ikonisk jamaicansk rom med hele 63% alkohol og masser af karakter. Den intense profil byder på tropisk frugt, banan, citrus, melasse og klassiske jamaicanske funky estere. En kraftfuld og aromatisk overproof rom, der er særligt velegnet til cocktails, punches og tiki-drinks, hvor den tilfører dybde, varme og autentisk Jamaica-stil.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Mount Gay 1703 Eclipse Rum, Barbados 40%', 'https://www.uhrskov-vine.dk/mount-gay-1703-eclipse-rum-barbados-40', 199, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/M/o/Mount-Gay-Eclipse-Rum.jpg', 'Mount Gay er produceret på basis af sukkerrør, der er dyrket på Mount Gay''s egen plantage samt af vand fra den underjordiske kilde, som løber under plantagen. Mount Gay er det ældste spiritusprodukt på Barbados, fremstillet siden 1703. Mount Gay Eclipse rom har en smag, der i overensstemmelse med duften er blød, rig og velafbalanceret.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Jamaica 5 år Cask Strength Sherry Cask Oloroso 57,84%', 'https://www.uhrskov-vine.dk/rum-nation-jamaica-5yo-cask-strength-sherry-cask-57-84', 499, TRUE, NULL, 57.84, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05719.jpg', 'Kraftig, fyldig og funky – præcis som en jamaicansk rom skal være det! Duft Funky – med fermenterede frugter, hvedemel og trælim. Smag Dejlig integrering af sherryfadet – med brun farin, lakridsrod, kamfer, kanel og vinøse noter. Eftersmag Langvarig, varm og ganske krydret – med noter af hvid pepper og nyslået græs.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados 5 Års Rum, 40% 70cl.', 'https://www.uhrskov-vine.dk/planteray-barbados-5-aars-rum-40', 299, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteray54.jpg', 'Planteray Barbados 5 Years Old er en klassisk Barbados-rom med et twist. Først ligger rommen på bourbonfade i Caribien i mellem 3 og 4 år, hvorefter den undergår Ferrands berømte finish på gamle, franske Cognacfade i 1-2 år, nøje overvåget af de dygtige kældermestre ved Chateau Bonbonnet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Volbeat Rom, Seal the Deal Rum 40%', 'https://www.uhrskov-vine.dk/volbeat-rom-seal-the-deal-rum-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/o/volbeatseal.png', 'Volbeat Seal The Deal Rum er det seneste produkt i Volbeats spiritus-serie. Volbeat Seal The Deal Rum er en lettere rom end bandets tidligere produkter (Rum, Rum II, III og Special Edition). Den er sammensat til at være alsidig nok til både at kunne nydes, præcis som den er, men samtidig også til at kunne bringe jeres favoritcocktail til live. Seal The Deal, som er blandet af håndudvalgte caribiske rom, der fortrinsvis stammer fra Den Dominikanske Republik, Trinidad og Tobago, er en blanding af ulagret og tre til fem år lagret kolonnedestilleret rom, der – inden de transporteres til blanding – har været lagret i fade, som tidligere har været brugt til bourbon. Den gyldne rom har en blød eftersmag med noter af vanilje, appelsin, lakrids og karamel. Volbeats forsanger og guitarist, Michael Poulsen, siger: ”Vi ledte vidt og bredt for at finde en rom, som kunne bruges til enhver lejlighed, og som samtidig var værdig til at bære Volbeats blå stempel – og den fandt vi med Seal The Deal. Vi er ekstremt stolte af at kunne tilføje Seal The Deal til vores serie af rom – og vi kan ikke vente med at se jer hæve glasset eller mixe en cocktail med os.”', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mister Fogg Navy Rum 55,7%', 'https://www.uhrskov-vine.dk/planteray-mister-fogg-navy-rum-557', 449, TRUE, NULL, 55.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/i/misterfogg.png', 'Planteray Mister Fogg Navy Rum er en kraftfuld hyldest til den klassiske britiske flådestil. Den er skabt af et blend fra Barbados, Jamaica, Guyana og Trinidad – fire romnationer, der tilsammen giver en dyb, kompleks og autentisk smagsprofil. Efter tropisk lagring i ex-bourbonfade sejles rommen til Cognac i Frankrig, hvor den gennemgår en anden modning i små egetræsfade. Denne dobbelte lagring tilfører dybde, varme og en afrundet elegance, uden at miste den rå styrke. Med en alkoholprocent på 55,7 % leverer Mister Fogg en intens aroma af tørret frugt, toffee, vanilje og mørk melasse. Smagen er fyldig og krydret med noter af brændt sukker, banan, chokolade og et strejf af røg – alt sammen bundet sammen af en lang, varm eftersmag. Resultatet er en ægte navy strength rom, der balancerer rå kraft med forfinet håndværk. Den kan nydes ren for sin dybe karakter, eller bruges i cocktails, hvor man ønsker en markant og aromatisk rom som hovedrolleindehaver. Planteray Mister Fogg Navy Rum er ikke bare en spiritus – det er en oplevelse af eventyr, tradition og håndværksmæssig præcision.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XV 15 års Tawny Port Cask Finish 40%', 'https://www.uhrskov-vine.dk/abuelo-anejo-xv-15-rom-napoleon-tawny-port-cask-finish-40', 629, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/a/tawnyportcask_1.jpg', 'Abuelo XV Tawny er endnu et godt bud på, at Abuelo er igang med at producere verdens bedste rom. Abuelo XV Tawny er en af 3 aftapninger i XV Finish Collection. Alle 3 rom er 15 år gammel og har fået en efterlagring (finish), på et fad der tidligere har været brugt til lagring af anden spiritus. Navnet på de 3 rom afspejler ikke blot karakteren fra fadet, men også stedet har inspireret til rommens endelig udformning. Napoleon er Cognac fra Frankrig, Oloroso er Sherry fra Spanien og Tawny er Portvin fra Portugal. Duft Tydelig duft af tawny porten, sammen med vanilje og orange noter Smag Portvinen giver en krydret smag, hvorefter rommen overtager med de klassiske abuelo-noter: tobak, orange, vanilje og læder Eftersmag Lang cremet eftersmag, hvor portvinen og rommen skiftevis kommer i bølger Kommentar En rafineret, elegant og helt rigtig ”Single estate rom” - sukkerrørene dyrkes på egne marker, rommen destilleres på egne kolonne kedler og rommen lagres på ex bourbonfade i egne lagerhuse! Baggrundshistorie Rommen laves af Varela Hermanos i Panama. Deres historie strækker sig tilbage til 1908, hvor Don José Varela Blanco, en ung spansk immigrant, oprettede San Isidro sukkermøllen i byen Pesé. Den første sukkermølle i den daværende nyligt skabte Panama republik. Byen Pesé, som selv blev oprettet i midten af det attende århundrede, ligger i en frugtbar dal i midten af Panama. Hovederhvervet i denne dal er nu dyrkning af sukkerrør, som beskæftiger mange lokale bønder. Den moderate nedbør, de kolde nætter og fugtige dage spiller alt sammen en rolle i udviklingen og modningen af rommen. Jo større forskel i temperaturen på de meget varme dage og de kolde nætter, jo hurtigere modnes rommen og jo flere smags- og duftstoffer udvikles der. Så Abuelo romfabrikken ligger ikke tilfældigt i dette ”smørhul”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kill Devil Caroni Trinidad 17 år, Single Cask Rum 63,1%', 'https://www.uhrskov-vine.dk/kill-devil-caroni-trinidad-17-ar-single-cask-rum-63-1', 2995, TRUE, NULL, 63.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/i/kill-devil-caroni-17yo-trinidad_2.jpg', '17 års lagret rom fra Caroni destilleriet i Trinidad. Rommen er destilleret tilbage i december 1998. Denne udgivelse er tappet fra et enkelt fad og aftappet på 63,1% cask strength af Hunter Laing for deres “Kill Devil” serie. Kun 258 flasker blev produceret af denne hæsblæsende Caroni rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s 5 år Fine Old Rum, Barbados 40%', 'https://www.uhrskov-vine.dk/doorly-s-5-ar-fine-old-rum-barbados-40', 229, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/doorly5.png', 'Fra Forsquare Destilleriet på Barbados, kommer denne 5 års Barbados Rom. Martin Doorly var manden der i tidernes morgen stiftede rom brandet Doorly''s tilbage til de tidlige 1920''ere. I 1992 blev Martin Doorly Rum opkøbt af Richard Seale manden bag RL SEALE. Destilleriet hvor Doorley''s blendes og lagres er det hedengangne FOURSQUARE Distillery som er omkring 350 år gammel.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Trinidad Vintage Collection 2003 Terravera Limited Edition 47,8%', 'https://www.uhrskov-vine.dk/planteray-trinidad-vintage-collection-2003-terravera-limited-edition-47-8', 699, TRUE, NULL, 47.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteray2003trinidad.png', 'Man skal altid huske at gemme de HELT STORE SUPERLATIVER til noget ganske særligt – og det er nu de skal i bruge! Planteray kommer med den sidste aftapning i deres Terra Verra serie – og de har gemt noget vanvittigt til sidst!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s 8 år Fine Old Rum, Barbados 40%', 'https://www.uhrskov-vine.dk/doorlys-8-aar-fine-old-rum-barbados-40', 339, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/doorlys8.png', 'Martin Doorly stiftede rom mærket Doorlys i de tidlige 1920-ere. I 1992 blev Martin Doorly Rum købt af RL SEALE.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 1 Ping XIII 14 Year Old Trinidad Distillers 56,8%', 'https://www.uhrskov-vine.dk/plantation-extreme-no-1-ping-13-14-ar-trinidad-56-8', 10995, TRUE, NULL, 56.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-ext-no1-ping-13_2.jpg', 'PING serie består af enkeltfadsaftapninger. Denne specialaftapning kommer fra Plantation Rum. Det er et af de første fade tappet i Extreme-serien. Fadet byder på en unik, fadstyrke, Trinidad-rom, som er lagret i 14 år. Extreme-serien serien tager udgangspunkt i at udvælge de allerbedste fade og give dem en unik behandling, så de kommer til deres ret gennem Cellarmasterens store arbejde.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison du Rhum Gaveæske 3x20cl', 'https://www.uhrskov-vine.dk/la-maison-du-rhum-gaveaeske', 599, TRUE, 20, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-du-rhum-gaveaeske.jpg', 'Super spændende gaveæske fra La Maison du Rhum indeholdene 3 flasker rom med 20 cl i hver flaske.  Gaveæsken indeholder: Rhum de trinidad & Tobago 50%, Rhum de Guadeloupe 44%, Rhum Vieux République Dominicaine 42%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barbancourt 3 Star 4 år Rom 40%', 'https://www.uhrskov-vine.dk/barbancourt-rom-4yo', 269, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbancourt_1.png', 'Denne Barbancourt Reserve Speciale er dobbelt destilleret og ældet i otte år i hvide egetræsfade for at producere en af ​​de fineste rom af sin art i verden. Den er fremstillet af gæret sukkerrørs saft, en opskrift Dupré Barbancourt skabte tilbage i 1862 i Haiti hvor rommen stadig produceres i dag. Den har en velbalanceret smag med en kraftfuld eftersmag af ristede, kogte frugter og citrusfrugter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation British Guyana 7 År Cask Strength Rum 59%', 'https://www.uhrskov-vine.dk/rum-nation-british-guyana', 519, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05091.jpg', 'Rommen kommer fra fra tre forskellige distillationsmetoder (French Savalle, Wooden Coffey og Double Wooden Pot).    Den er blevet blendet og modnet i mere end 4 år i sit tropiske klima efterfulgt af  36 måneder i europa på friske Oloroso sherry fade. Duft Kaffe, røde kirsebær, appelsinskal, aromaer af krydderier, duftende træ og et strejf af læder og rårørsukker Smag  Tør, meget vinagtig og med en tung tilstedeværelse af snerpende tanniner fra oloroso sherry. Blåbær og alle typer røde frugter, appelsinjuice og en antydning af ristet / brændt sukker (crème brûlée) Eftersmag: Meget tør, bliver endnu mere garvet, pebret og med en sherry-hårdhed, der næsten bliver rug Kommentar  Sammenlignet med de normale søde Demerara-rums er denne tappet med fadstyrke - blandingen af destillater fra de tre forskellige metoder - gør den vinagtig og tør - beregnet til elskere af den stramme brittiske stilart!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rumbullion, Navy-Strength Spiced Rum, 57%', 'https://www.uhrskov-vine.dk/rumbullion-navy-strength-spiced-rum-57', 549, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rumbullionns.jpg', 'Rumbullion! Navy-Strength er udformet efter samme opskrift som Rumbullion! Men navyen er en fyldigere variation med en højere ABV, hvilket betyder, at den har endnu mere smag i hver slurk (eller mundfuld – vi er ikke her for at bedømme). Den er lavet på et blend af kvalitetsrom fra Caribien, madagaskansk vanilje, appelsinskal, kanel, nelliker og kardemomme. Der er virkeligt slagkraft i denne rom – på en god måde. Tænk på den som rommens Mike Tyson. Rumbullion! viser stolt sin sørfartsinspiration med deres rå og unikke etiket, der bærer en håndtegnet illustration af et Navy grog tub, med ordene: “The Queen, God Bless Her”. Hver flaske er desuden pakket ind i krøllet brunt papir, der er viklet med garn og forseglet med sort voks.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Renaissance Rum, White Alligator Single Cask Rum, 64,8%', 'https://www.uhrskov-vine.dk/white-allligator-rum-renaissance-distillery-64-8', 1595, TRUE, 70, 64.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/e/rennaisance.jpg', 'Denne rom er noget helt specielt. Det er vores første aftapning, tappet i samarbejde med Renaissance Destillery fra Taiwan. Renaissance Distillery er kendt for at oplyse alle tænkelige informationer på deres baglabel. De er uhyre seriøse med netop den del. Det er en singlecask aftapning som er baseret på molasse. Den er fermenteret i 15 dage, hvor der i processen er tilsat Dunder. Efterfølgende er den lagret i et American new white oak barrel, med en høj ristnings grad. Dette sammen med de høje temperaturer i Taiwan gør at man får en rom der til trods for sine kun 3 år virker meget ældre og mere moden. Der er kun tappet 205 flasker af denne spændende rom. Fakta: Land - Taiwan Baseret på Molasse Fermenteret 15 dage. Dobbelt destilleret, første gang i 7 timer anden gang i13 timer. Af Head distiller Olivier Caen Tropisk lagret på American white oak, heavy char, first fill Tappet i 205 fl. ved fuld fadstykre på 64,8% 70 cl.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Latino Compagnie Des Indes Rum 5 år 40%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-rum-latino-5-ar-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/n/indes-rum-latino-5yo_2.jpg', 'Latino er fremstillet af en blanding af de bedste rom fra forskellige Latinamerikanske lande. Ca 60% udgøres af rom fra Guatemala de sidse 40% er fordelt mellem rom fra Trinidad, Barbados og Guyana. Hver af disse rom''s er lagret individuelt i mindst 5 år på amerikanske bourbon fade, og bidrager hver især til den komplekse og fyldige smag du finder i denne fremragende rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Shibboleth 16 års Expectional Cask Selection 56%', 'https://www.uhrskov-vine.dk/foursquare-shibboleth-16-expectional-cask-selection', 2495, TRUE, NULL, 56, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/foursquareshibbo.png', 'Nr. 16 i serien exceptionelle Cask Selection-udgivelser fra Richard Seale og Foursquare Distillery - Tappet i 2020. Foursquare Rum er produceret af R.L. Seale, et af Barbados ældste handelshuse, en familieejet virksomhed, hvis engagement i rom strækker sig fra far til søn siden 1820. Den nuværende Master destiller, Richard Seale, er en af ​​regionens mest innovative blendere og har en passion for at fremstille perfekt rom med god smag. Foursquare Distillery er, som et af ​​de mest moderne romdestillerier i verden, designet til at være ekstremt bæredygtigt.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus 15 år Solera Malt Whisky Finish, Den Dominikanske Republik 43%', 'https://www.uhrskov-vine.dk/opthimus-15-solera-malt-whisky-finish-43', 425, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/p/opthimus-15-solera-malt-whisky-finish-43_2.jpg', 'En spændende spiritus fra Oliver & Oliver, der med base i Den Dominikanske Republik, opkøber destillater i Carribien, for at blande den på bedste vis. Det er en hemmelighed, hvilke romdestillater, der indgår i de forskellige blends. Det er dog ikke nogen hemmelighed, at en stor del af rommen stammer fra Cuba, hvor Oliver familien har sine rødder, og også havde et romdestilleri i slutningen af det 18. århundrede. Da de grundlagde firmaet, fik lov til at købe omkring 100.000 liter god cubansk rom. Den øvrige rom er fra Panama, Trinidad, Colombia og Nicaragua, men en stor del kommer også fra deres egen ø, Den Dominikanske Republik. Denne 15 års udgave, er en fantastisk komposition af den svære kobling mellem rom og whisky og klart en af deres bedste. Destillaterne er nøje udvalgt af deres rom masterblender. En meget smagsfuld og elegant spirit drink fra en af verdens store producenter Oliver&Oliver, der virkelig har forstand på at forkæle os. Lagret i amerikanske egetræsfade, hvor den tilegner sig en god harmoni og stor kompleksitet og derefter afsluttes modningen i fade, hvor der tidligere været Skotsk Singel Malt Whisky. Duft En sød duft af vanilje, fadtræet, honning og tørret frugt Smag Sødme i en fin harmoni mellem pebernoter, vanilje og whiskyfadets tørhed Eftersmag Tørheden viser sig tydeligt, hvor den sammen med den naturlige sødme og peberen bærer den lange eftersmag med stil Kommentar En forførende spirit drink - naturligvis sød - med tilsat tørhed og fylde fra whiskyfadet - woawh!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cartavio 12 år Solera Rom 40%', 'https://www.uhrskov-vine.dk/ron-cartavio-12yo-solera-40pct', 325, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-cartavio-12yo-solera_1.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kaniche Perfección Double Wood Panama Rom 40%', 'https://www.uhrskov-vine.dk/kaniche-perfeccion-panama', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/a/kaniche-perfeccion-panama_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Caribbean Triple Aged Rum 5+5 år +Tasting Kit', 'https://www.uhrskov-vine.dk/dos-maderas-carribean-triple-aged-rum-5-5-aar-tasting', 499, TRUE, 70, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmade55.png', 'Huset blev grundlagt i 1877 af Sir Alexander Williams, en stor beundrer og connaisseur af sherry – og Arthuur Humbert, specialist i internationale relationer. I 1960’erne besluttede José, Nicolás, Jesús og Angel, som var medlemmer af Medina familien og arbejdede på andre Jerez vinhuse, at starte eget vinhus: José Medina y Compañia. Seneste tilegnelse var Williams & Humbert, som nu lægger navn til alle Medinas aktiviteter. Huset har vundet stort annerkendelse for deres sherry, brandy og rom. Master blenderen udvælger nøje mellem de mest eksklusive rom fra Barbados og Guyana. To lande med deres egen romstil. Begge lande laver nemlig rom på pot stills og kolonneapparat. Den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede på mere moderne kolonneanlæg. Dos Maderas TASTING KIT  består af en flaske Dos Maderas 5+5 rom (70 cl) og 4 små samples: Guyana-Barbados rom (udgangspunktet), Dos Cartados ekstreme tørre sherry, Dos Maderas 5+3 rom og Don Guido ekstreme søde PX sherry. Processen starter med at 5 år gammel Guyana-Barbados rom kommer til Jerez, hvor den lægges i 20 år gamle Dos Cartados fade. Efter tre år er så Dos Maderas 5+3 rommen færdig at drikke. Noget af denne 5+3 rom fyldes nu i 20 årige Don Guido PX fade, og efter yderligere 2 år er så Dos Maderas 5+5 rom færdig (den store flaske). Meningen er at der først smages på den rå rom sample. Herefter den tørre sherry, for at få en idé om, hvad der kommer til at ske med rommen. Nu smages Dos Maderas 5+3 rom, hvor de tydelige spor af den tørre sherry bør kunne fornemmes. Tiden er nu inde til den søde sherry, igen for at forberede sig til det endelige resultat - Dos Maderas 5+5! Gem gerne en lille smule Don Guido PX, som du blander med din sidste sip af 5+5 rommen - det er en fuldendelse af rom og sherry!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare PENULTIMUS Exceptional Cask Selection Single Blended Rum, 57%', 'https://www.uhrskov-vine.dk/foursquare-penultimus-single-blended-rum-57', 1095, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/e/penultimus.png', 'Foursquare Penultimus 57 % er et fantastisk eksempel på moderne kvalitetsrom fra Barbados. Produceret af Richard Seale hos Foursquare Distillery – kendt for kompromisløs transparens uden tilsat sukker eller kunstige tilsætninger. Penultimus er en “Single Blended Rum”, hvor pot still og column still kombineres for at skabe både dybde og elegance. Lagringen på bourbonfade efterfulgt af finish på Moscatel-fade giver noter af appelsinskal, mørk honning, kakao, tørret frugt og varme krydderier. En tør, kompleks og utrolig balanceret rom med lang finish og masser af struktur.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo 5 år, Añejo Reserva Especial Panama Rom, 40%', 'https://www.uhrskov-vine.dk/abuelo-anejo-5-ar-reserva-especial-rum-panama', 199, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/n/anejo.png', 'Abuelo Anejo 5 års Rom fra Panama, en autentisk mørk rom, lavet af sukkerrør, der omhyggeligt er lageret på egetræsfade og kendt for det faktum, at Abuelo er en af de meget få destillerier, der dyrker deres egen sukkerrør.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa LA ARMONIA Heavenly Cask Collection 40%', 'https://www.uhrskov-vine.dk/ron-zacapa-la-armonia-heavenly-cask-collection-40', 649, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ronzacapaarmonia.png', 'La Armonia er perfekt afbalanceret med antydninger af røde bær, pekannødder og det grønne, guatemalanske landskab. Silkeblød, glat og med indtryk af nødder og karamelliserede bær. Fyldig og lækker, silkeblød og overdådig.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 4 ITP 20 år Long Pond, Jamaica 52,1%', 'https://www.uhrskov-vine.dk/plantation-ext-no4-long-pond', 2999, TRUE, NULL, 52.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-ext-no4-long-pond.jpg', 'Endelig vender Plantation Extreme tilbage – og endda med (væsentligt!) fornyet kraft! De foregående år har Extreme-serien bestået af 2 eller 3 aftapninger, men denne gang er der hele 8 aftapninger i holdopstillingen. De eftertragtede flasker er fordelt ud på 7 lande, således at Frankrig, Tyskland, Sverige, Storbritannien, Belgien og Danmark får deres helt egen Extreme, mens der er 2 til de heldige asner i USA. Tilsammen danner kassernes artwork et billede af rommens rejse fra Caribien til Europa. Om det er en samlers drøm eller mareridt vil vise sig, for det bliver nok ikke helt let at få fingrene i alle 8…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 1, Imperial Navy Blend 10-11 års Rum, 57,18%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-rom-imperial-navy-blend-57-18', 619, TRUE, NULL, 57.18, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/m/imperialnavy_2.png', 'Denne rom er et Navy Blend med rom fra 4 forskellige lande, præcis som man gjorde i datiden når Navy rommen blev blendet til sømændene ved den britiske flåde. Disse 4 varianter er mixet sammen til denne perle, så der i alt er 989 flasker - selvfølgelig aftappet ved Gunpowder proof på 57.18% 10 y Trinidad 28%, 10 y Barbados 22%, 11 y Jamaica 26%. 11 y Guyana 24% Der er ikke tilsat sukker eller farve til denne rom, ligesom den er tappet ufiltreret. I duften fornemmer man noter af Vanilje, karamel, kokos, brændt egetræ og moden banan og smagen giver en sødmefuld smag af vanilje og kokos, demerara sukker og egetræ med et strejf af diesel. Collectors Series Rum - aftappet til RomDeluxe - Alder: 10-11 år (Bottled: 03/2021) - Antal flasker: 989 stk - Land: Trinidad, Barbados, Jamaica, Guyana Den er GunPowder Proof, og tappes på 57,18% ABV. Der tappes 989 flasker så vi sikrer der er nok til alle.   Der er ikke tilsat sukker eller farve til denne rom, ligesom den er tappet ufiltreret.   Duft: Her fornemmer man noter af Vanilje, karamel, kokos, brændt egetræ og moden banan Smagsnoter: sødmefuld smag af vanilje og kokos,demerara sukker og egetræ med et strejf af diesel. En virkelig lækker rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 5, Barbancourt 17 års Rum, 60,7%, RomDeluxe', 'https://www.uhrskov-vine.dk/barbancourt-17-aars-collectors-series-rum-rom-de-luxe-60-7', 895, TRUE, NULL, 60.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/s/csr-barbancourt-box.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Plantation XO Barbados Rum 20th Anniversary Extra Old 40% 175cl', 'https://www.uhrskov-vine.dk/magnum-plantation-xo-barbados-175-cl', 1099, TRUE, 175, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-barbados-20-anniver_1_1.jpg', 'VOKSENSTØRRELSE !! Denne unikke Barbados rom er efterlagret på fine små cognacfade hos cognachuset Pierre Ferrand i hjertet af Cognac i Frankrig. De bløde franske limousine egefade, som først er blevet brugt til modning af den allerbedste Grande Champagne Cognac, bidrager med blød frugt, revet appelsinskal og fine vaniljetoner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 11, Panama 16 års Rum, 59,6%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-no-11-panama-16-596', 769, TRUE, NULL, 59.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/o/collectorsseriesrumno11panama596abv70cl-33.png', 'Denne rom kommer fra Panama, hvor den er blevet modnet under den varme tropiske sol i 12 år. I 2018 blev den fragtet til Danmark, hvor den blev lagret yderligere 4 år i det kolde danske klima.Den har været lagret i det samme Ex- bourbon fad hele vejen igennem.   Det er en molasse baseret, Column destilleret rom.   Resultatet er en rigtig varm og lækker rom, som vi håber du vil nyde.Dette kunne være den perfekte ledsager til en god cigar. Fakta: Molasse based / Column distilled Distilled 2006 At a secret distillery Bottled 04/2022 Tropical and Continental aged Aged in Ex- Bourbon cask Cask no. 170 259 bottles Cask Strength at 59,6% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Silver Seal Old Navy 2018 Limited Edition 57%', 'https://www.uhrskov-vine.dk/silver-seal-old-navy-rum', 899, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/silver-seal-old-navy-rum_2.jpg', '1 ud af 1415 flasker Manden bag Silver Seal Rum, Massimo Righi, og Francesco Mattonetti fra ”Very Old Rum” har sammensat dette blend, baseret på gamle britiske traditioner om at blebde rom fra forskellige engelske kolonier. Super spændende navy strength rom lavet på blends af rom fra Guyana, Barbados og Jamaica - tappet ved 57% alkohol som var alkoholstyrken på den rom der blev skænket i den royale britiske flåde igennem 250 år.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate 15 Års Black River Casks Rum, 43%', 'https://www.uhrskov-vine.dk/appleton-estate-15-black-river-casks-43', 499, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/p/appleton15.png', 'Appleton Estate Black River Casks 15 år er et blend af udvalgte rom, der er produceret med det kalkstensfiltrede vand fra Black River. Rommen er nøje udvalgt og sammensat af Appletons højtestimerede Master Blender Joy Spence, der i øvrigt er den første kvindelige Master Blender i spiritusindustrien. Alle rom i Appleton Estate Black River Casks 15 år er lavet på melasse fra Appletons egne sukkerrør og har lagret i 15 år på Number One Select American Oak-tønder, der afgiver ekstra vaniljenoter og gør rommen mere blød og mindre træagtig i smagen. Appleton Estate Black River Casks 15 år har aroma af ristede mandler, hasselnødder og appelsinskal og noter af vanilje, ristet kaffe og melasse', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 24 Panama 22 års Single Cask 63,95%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-24-panama-22-single-cask-63-95', 1259, TRUE, NULL, 63.95, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/2/4/24panama.png', 'Wild Series Rum No. 24 Panama , er en meget spændende rom fra Panama, som kombinerer alt det bedste fra den spanske romstil med de røgede whiskytyper. Denne rom er et blend af kolonne og potstills destilleret rom. Den har lagret hele 20 år i Panamas tropiske klima, inden den er transporteret til Danmark hvor vi har givet den en finish i brugte Islay whiskyfade i 30 mdr. Dette har kombineret de sødmefulde noter fra rommen med en markant røget karakter. Fakta: Distilled 1999 At Secret distillery Bottled 03/2022 Added sugar 9 gr./L. Aged 30 months in ex Islay cask 20Y Tropical aged, continentally finished Cask no. 346 1 of 242 bottles Cask Strength at 63,7% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hansen Golden Rum, 37,50%', 'https://www.uhrskov-vine.dk/hansen-golden-rum-37-50', 149, TRUE, NULL, 37.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hansengolden.jpg', 'Hansen Golden Rum fremstilles af sukkerrør, og efter destilleringen lagres den på gamle egetræsfade. Her udvikler den særprægede og kraftige aroma sig til den harmoniske smag, som Hansen Golden Rum er kendt for. På grund af indholdet af sukker og andre næringsstoffer har Hansen Golden Rum en oplagt varmende og opfriskende egenskab.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Ron Prohibido 22 år Solera Rom 40%', 'https://www.uhrskov-vine.dk/el-ron-prohibido-22-solera-rom-40', 479, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/prohibido22.png', 'Denne mexicanske El Ron Prohibido “Reserva” Solera 22 har fået sit navn efter lagringsmetoden Solera, der blander ældre årgange, så gennemsnitsalderen stiger år for år. Den indeholder rom, som er helt op til 22 år gammel. Smagen har noter af chokolade, brunt sukker, fersken og rosin, der får modspil af sød vanilje og aromatisk kaffe. Server både rommen for nybegynderen og den garvede rom-connoisseur.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s 3 år Fine Old White Rum, Barbados 47%', 'https://www.uhrskov-vine.dk/doorlys-3yo-fine-old-white-rum-47', 259, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04422.jpg', 'Martin Doorly stiftede rom mærket Doorlys i de tidlige 1920-ere. I 1992 blev Martin Doorly Rum købt af RL SEALE. Destilleriet hvor Doorleys blandes og lagres er Foursquare på Barbados - omkring 350 år gammel, og de ældste optegnelser antyder at den særlige rom-vin-mølle tilknyttet molasse fabrikken har været i produktion siden 1730. Destilleriet blev total renoveret i 1995, og fremstår i dag som en blanding mellem historien og den nye teknologi. Samtidig er romproduktionen på stedet blevet erklæret 100% miljø rigtig…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carúpano Reserva 6 Especial Ron Añejo 40%', 'https://www.uhrskov-vine.dk/ron-anejo-carupano-reserva-6-especial', 219, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50643330.jpg', 'Carupano Reserva 6 Especial er en charmerende, lys 80 proof rom, lagret i forseglede ex-bourbon fade op til 6 år og uden erstatning af Angel''s Share. Til produktionen anvendes udelukkende kildevand, hvilket sikrer en større renhed, der garanterer udelukkelsen af uønskede lugte eller smagsstoffer. Carupano Reserva 6 Especial er en spændende, lys cocktail-rom, der introducerer kompleksitet og blide fadnoter til dine drinks!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carúpano Reserva Ron Añejo 12 Exclusiva 40%', 'https://www.uhrskov-vine.dk/ron-anejo-carupano-reserva-12-exclusiva', 269, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50643331.png', 'Carupano Reserva 12 Exclusiva er en spændende 80 proof rom, lagret i forseglede ex-bourbon fade op til 12 år og uden erstatning af Angel''s Share. Til produktionen anvendes udelukkende kildevand, hvilket sikrer en større renhed, der garanterer udelukkelsen af uønskede lugte eller smagsstoffer. Carupano Reserva 12 Exclusiva har tydeligt præg af den Caribiske havluft, der giver et særligt friskt udtryk og noter af saltkaramel. En dejlig rom, der gør sig ganske godt på egen hånd, men giver et helt formidabelt udtryk i dine cocktails!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Demerara Solera N. 14 Rum 40%', 'https://www.uhrskov-vine.dk/demerara-solera-rom-2019', 359, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/e/demerararum.png', 'En rigtig Demerara. Krydret, men også med et hint af røg og meget aromatisk. Den er sød, fløjlsblød og har en næsten smørlignende konsistens. En modsætningernes rom! Perfekt til Demerara cocktails. Duft Mørk, fyldt med ester. Et hint af grill-røg. Smag Sød, cremet og afrundet. Kanel, orangeskal og sort peber. Eftersmag Egetræsfad, kaffe, mørk chokolade, lakrids og anisfrø. Rum Nation - en verdensomspændende romserie, udelukkende bestående af udvalgte fade fra et destilleri. Et udvalg af ”single rom”, tro mod spiritussens hjerte, unik og uforglemmelig. Der er kun én romfabrik tilbage i landet; nemlig Diamond Distillery. Fabrikken har til gengæld overtaget destillationskedler fra de sidste, nu lukkede, destillerier. Det betyder, at de har 10 forskellige kedler til at lave rom på Nogle er ikoniske gamle trækedler, med ”Port Morant” kedlen, som den ældste. Kedlen blev bygget i 1732 og laver stadig rom. Af andre berømte kedler er også ”Enmore” kedlen, som er en kolonne lavet i hård regnskovstræ. Hvilken blanding af kedler der er brugt i denne rom, er en velbevaret hemmelighed, men det er tydeligt, at der er tale om både potstil og kolonnekedel rom. Rum Nation Demerara Solers No. 14 har været lageret i brugte amerikanske Bourbon fade og de sidste 12 måneder i en blanding af sherryfade, der tidligere har indeholdt Olorosso- og Pedro Ximenez sherry.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Austrian Empire Navy, Baron Dahlerup 40%', 'https://www.uhrskov-vine.dk/austrian-empire-navy-baron-dahlerup-40', 475, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/dahlerup.jpg', 'Denne dejlige dram er en vellykket kombination af 5 – 12 år gammel rom fra Barbados og 18 år gammel solera-lagret rom fra Den Dominikanske Republik. En del af rommen har været lagret på Sherryfade, mens en del har været lagret i alle årene på amerikanske ex-Bourbonfade. Denne unikke aftapning er produceret til ære for danske Baron Hans Birch Dahlerup (1790-1872), der i en lang årrække havde ansvaret for den østrigske flåde.  Oplevelsen Det er en virkelig fyldig, fed og sød dram med en god længde i eftersmagen.  Baron Dahlerup Baron Hans Birch Dahlerup (1790-1872) kom til verden i Hillerød i 1790, som søn af en politimester og vejfiskal. Efter slaget på Reden fik han på trods af sin unge alder lyst til at blive søofficer, og allerede året efter som 12-årig blev han kadet. Kun 4 år efter - som 16-årig - var Baron Dahlerup løjtnant. Han er kendt for en glorværdig og bemærkelses- værdig karriere indenfor søværnet. I 1848 forlod han den danske flåde og tog imod en personlig invitation fra den unge kejser Franz Joseph I om at overtage kommandoen over den østrigske flåde. Han kommanderede den kejserlige flåde under flådeblokaden og genbesættelsen af Venedig i 1849. Han rekonstruerede derefter flå- den fra bunden og afvæbnede det meste af den venetianske kommandostab. For at reducere den venetianske indflydelse i flåden til et minimum, indførte han frem for alt de nordiske og angelsaksiske søfartsregler og adopterede en ny generation af unge søofficerer. Dahlerup grundlagde Søværnets Militærakademi i Trieste (1848–1858). Han reducerede skoletiden til tre år, indførte en etårig skole for kadetter og ph.d.-studerende og eliminerede italiensk som undervisningssprog for at forbinde den kejserlige flåde tilbage til hjemlandet og introducerede tysk som kommandosprog. Admiral Dahlerup valgte samtidig Pula i Kroatien, som Østrigs vigtigste flådebase og skitserede den østrigske flådes langsigtede udviklingsretninger. I 1849 blev han udnævnt til viceadmiral for den ø', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Carribbean Rom Ron Anejo 5+3 år 37,5% 20cl', 'https://www.uhrskov-vine.dk/dos-maderas-rom-5-3-20-cl', 125, TRUE, 20, 37.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dos-mad-5-3-20.jpg', 'Dos Maderas 5+3 rom er en gylden rom med lys, ravgul farve. Unik blend af rom fra Caribien med 2-trins lagringsproces, der skaber en forældet rom med unik karakter. Tør, men blød og harmonisk afrundet smag med strejf af tørret frugt, krydderi og karamel. Noter af vanilje og let sherry impact. Dos Maderas 5+3 rom lagres 5 år i Caribien i amerikanske egetræsfade og herefter 3 år i 20 års Dos Cortados sherryfade i Williams & Humberts Bodega i Jerez, Spanien.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Paranubes Rom, Mexico 70cl', 'https://www.uhrskov-vine.dk/paranubes-70cl', 379, TRUE, 70, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/paranubes.png', 'I Oaxacas tågede bjergskove finder man det lille håndværksdestilleri hvor rommen Paranubes kommer til live. Den laves på frisk sukkerrørssaft, ligesom man kender det fra fx  rhum agricole , og destilleres på små kobberkolonner. Alkoholprocenten på 54 er ”still proof”, hvilket vil sige, at den ikke er vandet ned efter destillation – og i øvrigt heller ikke tilsat noget som helst andet. Smagen er fuldstændig unik, og det er ikke tit vi er  så  begejstrede for en ny rom. Det her er verdensklasse!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pullimut 2021 Edition Rom 44 100cl 44,3%', 'https://www.uhrskov-vine.dk/pullimut-2021-edition', 599, TRUE, 100, 44.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/pullimut30-e1613551308610.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Planas Ron Blanco Extra Anejo 47%', 'https://www.uhrskov-vine.dk/diplomatico-planas-ron-blanco-extra-anejo-47', 259, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplomatico_planas_flaskefoto.png', 'Diplomatico Planas Ron Extra Anejo er en super premium hvid rom fra det populære romhus Diplomatico i Venezuela. Rommen er den bedste lyse rom fra Diplomatico og kan klar anbefales til spiritus tunge cocktails hvor rom smagen skal træde i karakter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation XO Barbados 20th Anniversary Extra Old 40, 10cl', 'https://www.uhrskov-vine.dk/plantation-xo-barbados-20-anniversary-extra-old-40-10', 89, TRUE, 10, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation20cl.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XV 15 Års Oloroso Sherry Cask Finish 40%', 'https://www.uhrskov-vine.dk/abuelo-anejo-xv-15-rom-napoleon-oloroso-sherry-cask-finish-40', 629, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/l/olorosocask.jpg', 'Abuelo XV Oloroso er endnu et godt bud på, at Abuelo er igang med at producere verdens bedste rom. Abuelo XV Oloroso er en af 3 aftapninger i XV Finish Collection. Alle 3 rom er 15 år gammel og har fået en efterlagring (finish), på et fad der tidligere har været brugt til lagring af anden spiritus. Navnet på de 3 rom afspejler ikke blot karakteren fra fadet, men også stedet har inspireret til rommens endelig udformning. Napoleon er Cognac fra Frankrig, Oloroso er Sherry fra Spanien og Tawny er Portvin fra Portugal. Duft Læder, vanilje, mandarin og tørret frugt Smag Fed og cremet, noter af brændt orangeskal, abrikos samt søde krydderier Eftersmag Lang sødmefyldt og krydret eftersmag med noter af sød pibetobak og orange skal Kommentar En rafineret, elegant og helt rigtig ”Single estate rom” - sukkerrørene dyrkes på egne marker, rommen destilleres på egne kolonne kedler og rommen lagres på ex bourbonfade i egne lagerhuse! Baggrundshistorie Rommen laves af Varela Hermanos i Panama. Deres historie strækker sig tilbage til 1908, hvor Don José Varela Blanco, en ung spansk immigrant, oprettede San Isidro sukkermøllen i byen Pesé. Den første sukkermølle i den daværende nyligt skabte Panama republik. Byen Pesé, som selv blev oprettet i midten af det attende århundrede, ligger i en frugtbar dal i midten af Panama. Hovederhvervet i denne dal er nu dyrkning af sukkerrør, som beskæftiger mange lokale bønder. Den moderate nedbør, de kolde nætter og fugtige dage spiller alt sammen en rolle i udviklingen og modningen af rommen. Jo større forskel i temperaturen på de meget varme dage og de kolde nætter, jo hurtigere modnes rommen og jo flere smags- og duftstoffer udvikles der. Så Abuelo romfabrikken ligger ikke tilfældigt i dette ”smørhul”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate Pagos, Pure Single Jamaican Rum, 52%', 'https://www.uhrskov-vine.dk/hampden-estate-pagos-pure-single-jamaican-rum-52', 999, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdenpagos.png', 'I Jerez de la Frontera, hvor man laver sherry, betyder ordet ”pagos” vinmarker, og som du nok har regnet ud, er denne jamaica-rom lagret på sherryfade. Der er ikke blot tale om en finish; rommen er lagret udelukkende på sherryfade fra Lustau, der har indeholdt oloroso eller PX-sherry – og det er første gang vi ser det fra Hampden Estate. Alkoholprocenten er på meget velvalgte 52, og den er naturligvis hverken tilsat sukker eller farve. Farve : Mørkt rav. Duft : Mørk chokolade, abrikos, mango og passionsfrugt. Smagsnoter : Balanceret, lang og kompleks, igen med noter af chokolade og kakao, lidt citrus, stenfrugt og varme krydderier. Serveringsforslag : Bør nydes rent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes West Indies 8 Års 40%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-8yo-west-indies', 449, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-8yo-west-indies_2.jpg', 'Rum Compagnie des Indes West Indies er en blød og dog kraftig blend fra den Dominikanske Republik, Panama, Guyana og et lille imput af pot stills fra Barbados. De forskellige rom er lagret i tønder i minimum 8 år.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 8 år Barbados 2019 Rom 40%', 'https://www.uhrskov-vine.dk/rum-nation-barbados-8yo-2019', 385, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04830.jpg', 'Rum Nation, en verdensomspændende romserie, udelukkende bestående af udvalgte fade fra et og samme destilleri. Resultatet er et udvalg af ”single rom” i en begrænset mængde, tro mod spiritussens hjerte, unik og uforglemmelig. Bliv en ”Citizen of Rum Nation”, det er en fantastisk rejse gennem en verden af rom!  En sødere og mere frugtagtig udgave af vores berømte Barbados rum. Lagret i 8 år i et tropisk klima. Den har den en vedvarende fløjlsagtig mundfølelse og en rundhed, der gør den særlig velegnet til en eftermiddag', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Hechicera Rum, Colombia 40%', 'https://www.uhrskov-vine.dk/la-hechicera-rum-colombia-40', 385, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-hechicera-rum_1.jpg', 'Fantastisk Rom fra det sidste familieejede destilleri i Colombia. blandet og lagret mellem 12 og 21 år i hvid eg. Navnet udtales "etch-ee-SEH-Rah« og navnet betyder "Enchantress" på spansk.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 11 år Forsyths 2006 Jamaican Pure Single Rum WPM 57,5%', 'https://www.uhrskov-vine.dk/habitation-velier-forsyths-2006-jamaican-pure-single-rum-wpm-57-5', 999, TRUE, NULL, 57.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/forsyths-wpm-2006-jamaica-pure-single-rum_2.jpg', 'Forsyths 2006 fra Jamaica er en unik rom fra Worthy Park, da den er destilleret uden tilsætning eller farvemidler. Det er en rum med stor harmoni og perfekt balanceret, men en meget kraftfuld rom fra Velier.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Caroni 1994 21 år Trinidad 57,8%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-caroni-1994-21yo-trinidad-57-8', 3495, TRUE, NULL, 57.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-indes-caroni-1994-21_2_1.jpg', 'Endnu en fremragende aftapning fradet nu lukkede Caroni Destilleri på Trinidad. Aftappet af den unge Rom komet Florent Beuchet - manden bag Rhum Compagnie des Indes. Denne Cask Strength aftapning er endnu en enkeltfads aftapning aftappet ved fadstyrke på 57,8%. Destilleret 1994, og aftappet 2015. Rommen er modnet i 21 år på gamle bourbon fade og både lagret i Caribien samt en årrække i Europa efterfølgende.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Caribisk Rom Bog - Et hav af smag', 'https://www.uhrskov-vine.dk/caribisk-rom-bog-mads-heitmann', 299, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/caribisk-rom-bog-mads-heitmann.jpg', 'Mads Heitmann som er ejer og stifter af Romhatten.dk, og Danmarks mest fremtrædende formidler af rom, beskriver i denne bog for både den nye og erfarne rom-interessede romscenen, som den ser ud i dag. Mads går i dybden med produktionen af rom og rykker sukkerrøret op ved roden i jagten på forståelsen af alle de utrolige og utroligt forskellige smagsoplevelser, som findes i den caribiske romregion…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Princessa St. Lucia Rum, 40%', 'https://www.uhrskov-vine.dk/admiral-rodney-princessa-rum-40', 479, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/princessa.png', 'RUM BLEND : Admiral Rodney Princessa contains Coffey still rum pulled off lower sections of the still resulting in a robust and complex flavor profile. This rum is aged from 5-9 years in Bourbon and Port casks before being blended together by our Master Blender.  TASTING NOTES:  Deep mahogany color with honeyed raisins on the nose and a hint of vanilla and tobacco. Sweet with intense brown sugar, crème brulee tones balanced by dry toasty oak. Complex finish with good oak integration, caramel, and tropical spice.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 26 Jamaica 16 års Single Cask 68,4%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-26-16-barbados-single-cask-68-4', 1349, TRUE, 70, 68.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/i/wildseries26jamaica.png', 'Wild Series Rum No. 26 Jamaica er en rom som kommer fra Long Pond destilleriet. Long Pond er kendt for at lave nogle yderst smagfulde rom, med masser af Jamaican funk. De benytter sig af lang fermentering for at sikre at smagen udvikler sig optimalt.  Den er kontinentalt lagret på Ex bourboon fade. Denne aftapning er med sin høje alkoholprocent på over 68 et rigtigt godt eksempel på at jamaicansk rom bliver bedre og mere karakterfuld når det tappes ved fuld fadstyrke. Her er der power på smagene, hvor du møder overmoden banan, der sammen med tørret tropisk frugt og nødder er bare nogle af de indtryk man får i glasset Rommen er tappet ufiltreret, for at sikre den maksimale smag. Fakta: Land Jamaica Destilleri Long Pond Baseret på Molasse Destilleret på Wedderburn Potstill Destilleret Dec. 2005 Tappet April 2022 i 269 fl Kontinentalt lagret i ex Bourbon cask Ester Marque VRW ( 150-250 ) Fad nr. 5 68,4% ABV - 70 cl.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barceló IMPERIAL 40 Premium Blend Anniversario Rum 43%', 'https://www.uhrskov-vine.dk/ron-barcelo-40-anniversario-imperial-rum-43', 1195, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barcelo40.png', 'En særlig blanding af Barceló Imperial''s tidligere reserver, modnet i udvalgte stykker af amerikansk og fransk egetræsfade, begge med forskellige grader af ristning; efterfølgende hvilende i europæiske tanke. Fyrre år dedikeret til at bevare kvalitetstraditionen af Barceló-rom. En gave til dem, der virkelig sætter pris på smagen af en fin kvalitetsrom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Canero 12 år Ron Dominicano Cognac Cask Finished Rom', 'https://www.uhrskov-vine.dk/summum-12-ar-ron-dominicano-cognac-cask-finished-rom', 385, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/roncanero.jpg', 'Ron Canero 12 års Ron Dominicano, Cognac Cask Finished er en blanding af høj kvalitets rom fra Solera. Den er modnet i tidligere bourbon tønder, mindst 12 år. Før den bliver tappet, får den en særlig finish i franske egetræsfade hvor cognac førhen blev lagret. Summum - et latinsk ord, som beskriver den absolutte topkvalitet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Summum 12 år Ron Dominicano, Finished Malt Whisky, Rom', 'https://www.uhrskov-vine.dk/summum-12-ar-ron-dominicano-finished-malt-whisky-rom', 385, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/u/summum-finished-malt_2.jpg', 'Summum 12 års Ron Dominicano, Finished Malt Whisky er en rom fremstillet på hundredeårige opskrifter. Den bliver aldret igennem 6 måneder i single malt whisky fade, som en del af processen. Summum - et latinsk ord, som beskriver den absolutte topkvalitet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('The Last Caroni 23 år Full Proof Heavy Trinidad Rum 61,9%', 'https://www.uhrskov-vine.dk/the-last-caroni-23-yo-trinidad', 15000, TRUE, NULL, 61.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/h/the-last-caroni-23-yo-trinidad_2.jpg', 'Den officielt sidste aftapning fra Velier´s berømte Release serie. The Last Caroni Full Proof Heavy Trinidad Rum er deres 39th release aftapning og caribisk lagret i ialt 23 år. Destileret i 1996 og aftappet i 2019. Efter lukningen 2002 har rommem lagret på det nu forlængst lukket Destilleri  Caroni på Trinidad frem til 2008 for derefter at have været lagret de resterende år i Guyana fremtil 2019.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Tasting Gang 23 år Caroni Full Proof Blended Trinidad Rum, 63,5%', 'https://www.uhrskov-vine.dk/tasting-gang-caroni-full-proff-23', 8500, TRUE, NULL, 63.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/a/tasting-gang-caroni-full-proff-23_2.jpg', 'Tasting Gang 23 Års Caroni Full Proof Heavy Trinidad Rum er deres 38th release aftapning og caribisk lagret i ialt 23 år. Destileret i 1996 og aftappet i 2019. Efter lukningen 2002 har rommem lagret på det nu forlængst lukket Destilleri  Caroni på Trinidad frem til 2008 for derefter at have været lagret de resterende år på DDL Guyana fremtil 2019.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Stroh Jagertee, Austria 40% 50cl', 'https://www.uhrskov-vine.dk/stroh-jagertee-50cl', 129, TRUE, 50, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/t/strogjagertee.png', 'Jagertee er en typisk østrigsk specialitet efter en gammel recept. Her hældes 1 del til 3 dele varmt vand, som så er lige til at nyde i Alperne såvel som på en råkold vinterdag i Danmark.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XII Three Angels Rum 43%', 'https://www.uhrskov-vine.dk/abuelo-12-anos-three-angels-43', 649, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05606.jpg', 'Abuelo XII Anos ”Three Angels”  er en  single estate rum  fra Ron Abuelos destilleri i Panama. Denne dybe og elegante udgivelse er – lig sin lillesøster  Abuelo XII Anos ”Two Oaks”  - en blanding af dobbelt-lagrede 12 års rom, som først lagres i bourbonfade af hvid amerikansk eg, dernæst i ekstra-brændte nye egefade. Til forskel fra  ”Two Oaks ” er denne udgivelse taget udelukkende fra fadene på den øverste række på Ron Abuelos  vintage pallet  varehuse. På den øverste række når temperaturen helt op på 35°C. Dette resulterer i at  angel’s share  (den procentdel af whiskyen der fordamper hvert år) når op på hele 15% - til sammenligning er angel''s share i Skotland kun på ca. 3%. Denne exceptionelt høje  angel''s share  er inspirationen bag navnet  Three Angels . Ekstreme daglig skift i temperatur og luftfugtighed resulterer i en rom med ekstraordinær kompleksitet og smag. Derudover er ” Three Angels ” også tappet ved højere alkoholstyrke end Ron Abuelos andre udgivelser, hvilket perfekt komplimenterer den mere intense smag. Three Angels er en variation af den prisvindende  Abuelo XII Anos ”Two Oaks” , som blandt andet har vundet Dobbelt Guld ved San Francisco World Spirits Competition 2022. Abuelo XII Anos ”Three Angels”  er udgivet ved en ABV på 43%.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Equiano Afro-Caribbean Rum 43%', 'https://www.uhrskov-vine.dk/equiano-afro-caribbean-rum-43', 449, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/l/rl_equiano_bottle_700ml-ap-06102020-scaled.jpg', 'Verdens første Afrikanske-Caribiske Rom. Equiano Rum resultatet af et samarbejde mellem to fantastiske destillerier, som er et blend af to destillater fra henholdsvis Barbados ''Foursquare og Gray''s Distillery of Mauritius. Her er der tale om en ægte rom. Ingen tilsat Farve, ingen tilsat smagsstoffer og bestemt ingen tilsat sukker.  .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carúpano Reserva 18 Ron Añejo Limitada 40%', 'https://www.uhrskov-vine.dk/ron-anejo-carupano-reserva-18-limitada', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50643332.png', 'Ron Carúpano har i 2020 lanceret Ron Carúpano 18 Reserva Limitada, som et led i deres opdatering af hele produkt-porteføljen og skabelsen af deres "Another Level"-image. Carupano Reserva 18 Limitada er en extra-aged rom lagret i forseglede ex-bourbon fade op til 18 år og uden erstatning af Angel''s Share. Til produktionen anvendes udelukkende kildevand, hvilket sikrer en større renhed, der garanterer udelukkelsen af uønskede lugte eller smagsstoffer. En behagelig, blød og velafbalanceret rom - Et klassisk eksempel på hvad Venezuela har at byde på!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carúpano Reserva 21 Ron Añejo Privada 40%', 'https://www.uhrskov-vine.dk/ron-anejo-carupano-reserva-21-privada', 475, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50643334_1.jpg', 'Carupano Reserva 21 Privada er en extra-aged rom lagret i forseglede ex-bourbon fade op til 21 år og uden erstatning af Angel''s Share. Til produktionen anvendes udelukkende kildevand, hvilket sikrer en større renhed, der garanterer udelukkelsen af uønskede lugte eller smagsstoffer. En elegant og velafbalanceret rom med læskende orange-noter - Et klassisk eksempel på hvad Venezuela har at byde på!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 4, The Oddmar Edition 3 års Rum, 43,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/the-oddmar-edition-3-aars-collectors-series', 679, TRUE, NULL, 43.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/h/theoddmar.png', 'Release on Saturday the 21th August at 10.00 ! ! Collectors nr. 4 er the Odmar edition. Den er dedikeret til en af vores gode venner i branchen. Nogle ved måske hvem det er vi taler om når jeg siger at han ofte underholder med historien om dengang han kogte en bæver. ( Og ja han er fra Norge ;-) ) Det er en ung rom på 3 år fra Richland Destilleriet i Georgia. Den er også ganske mild efter vores målestok, da den kun er på 43%.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Beenleigh 2015 Desert Ageing Pure Single Rum, Velier 59%', 'https://www.uhrskov-vine.dk/velier-desert-ageing-2015-beenleigh-pure-single-rum-59', 1599, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/beenleigh_2015.png', 'Destilleriets andet lager ligger i halvørken området Renmark i Barossa-dalen. Her efterlades denne rom til at lagre i 5 år på ex-Bourbon first fill-fade. Angel''s Share> 43%. Tappet ved fadstyrke ved 59%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Neisson Reserve Speciale Rhum Vieux Agricole, Martinique 42%', 'https://www.uhrskov-vine.dk/neisson-reserve-special-rom-42', 449, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/n/e/neisson.jpg', 'Neisson Reserve Special er en rhum agricole fra ét af Martiniques mindste destillerier. Denne aftapning er sammensat af rom fra flere årgange, lagret op til 10 år på fade af henholdsvis amerikansk eg og fransk eg. Den er tappet ved 42% alkohol, og er ikke tilsat sukker. En tør og elegant rom med krydrede noter fra den franske eg og masser af friske sukkerrørsaromaer.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Guatemala Gran Reserva Rum 40%', 'https://www.uhrskov-vine.dk/rum-nation-guatemala-gran-reserva-rum-40', 359, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guatemala.jpg', 'Rum Nation - en verdensomspændende romserie, udelukkende bestående af udvalgte fade fra et destilleri. Et udvalg af ”single rom”, tro mod spiritussens hjerte, unik og uforglemmelig. Rum Nation Guatemala Gran Reserva  er en melassebaseret rom, som er gæret og destilleret på destilleriet S.A. TULULA. Når rommen er færdigdestilleret på kolonne-destilationsapparater, transporteres den til den nord-østlige del af Guatemala 185 meter over havets overflade. Der lagres rommen på hvide egetræsfade, som tidligere har indeholdt amerikansk bourbon. Denne fyldige rom hviler nu i 4 år i regionen ved Hondo-floden, som giver et fugtigt lagringsklima og dermed giver rommen mulighed for at få accelereret modningen, fordi Rio Hondo næsten er et tropisk klimaområde i Guatemala. Rum Nation Guatemala Gran Reserva har klassiske romnoter fra den spanske romstil såsom ristede nødder, bihonning, mørk chokolade og overmoden banan. Dette er er af de ’lettere’ rom i Rum Nation serien, og har en behagelig sødme, som andre rom i den Spanske stil også er kendt for. Dog uden nogensinde at blive sikker-sød.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Unicorn Tasting Kit Vol. 2', 'https://www.uhrskov-vine.dk/wild-series-unicorn-tasting-kit-vol-2', 3599, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/u/n/unicornkitvol2.png', 'Her er der tale om et sæt med 3 rom fra Guyana, som er fra det samme destilleri, og næsten lige gamle, men som kommer fra 3 forskellige ikoniske destillationskedler, der alle har en lang histrie bag sig. Vi vil gerne vise hvor forskellige rom kan være baseret på kedeltypen. Der er tappet 195 sæt af disse tre single casks. De 3 rom er alle destilleret på Diamond destilleriet, og er som følger Rom nr 1 kommer fra Enmore EHP Coffey still kedlen, som er en gammel Kolonne kedel bygget i træ. Den har et marque som hedder MEE. Den er destilleret i Februar 2002. Abv på denne rom er 59,8%. Rom nr 2 kommer fra Savalle kedlen, som er en Kolonne kedel med 4 kolonner. Den har et marque som hedder SVL. Den er destilleret i December 2003. Abv på denne rom er 59,3%. Rom nr 3 kommer fra Versailles Pot still kedlen, som er den eneste tilbageværende enkelt Pot Still kedel bygget i træ. Den har et marque som hedder MDXC. Den er destilleret i Juli 2004. Abv på denne rom er 54,9%.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distillery Edition 2023 Old Pure Single Jamaican Rum, 57%', 'https://www.uhrskov-vine.dk/hampden-great-house-distillery-edition-2022-55', 1199, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden-great-house-distillery-edition-2023.jpg', 'Hampden Great House 2023 er den femte udgivelse af den eksklusive destilleri-udgave. udgave. Denne aftapning er en hyldest til destilleriets Great House, som stadig står i sin oprindelige form. Huset blev bygget i 1779 af Stirling-familien, og førstesalen blev brugt til romopbevaring (tønder, der ventede på at blive overført til portvin) indtil det 20. århundrede. I dag er det blevet til et repræsentationshus, hvor man tager imod gæster og besøgende.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 25 Barbados 14 års Single Cask 62,3%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-no-25-barbados-14-single-cask-62-3', 1249, TRUE, NULL, 62.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbados25.png', 'Denne rom kommer fra Barbados, hvor det ikoniske destilleri Foursquare har sin beliggenhed. Hos Foursquare laver de naturlige rom baseret på de gamle traditioner på Barbados. Denne rom er ingen undtagelse fra det. Her har vi en rom med masser af smagsnoter, kokos, vanilje og chokolade, som vi kender så godt fra barbadiske rom lavet af Foursquare. Vi har en masse kærlighed og respekt for arbejdet udført af Richard Seale og hans team hos Foursquare. Derfor valgte vi at have denne fantastiske rom i Wild Series of rom. Fakta: Barbados Single cask Distilled Dec. 2007 At Foursquare distillery Bottled 03/2022 Tropical and Continental aged Aged in Ex- Bourbon cask Cask no. 9 1 of 219 bottles Cask Strength at 62,3% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Sealander, Very Special Aged Rum, 40%', 'https://www.uhrskov-vine.dk/plantation-sealander-very-special-aged-rum-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationsealander.png', 'Endelig er Plantation Sealander kommet sikkert i havn! Hele 3 markante rom-øer har lagt kedler til denne unikke rom: Mauritius, Fiji og Barbados. Dermed spænder rommen også over 3 verdenshave: Atlanterhavet (Barbados), Stillehavet ( Fiji ) og Det Indiske Ocean (Mauritius) – der er altså tale om lidt af et world blend, som på trods af vidt forskellige ophav har nået en vidunderlig harmoni. Komponenten fra Mauritius er lavet på frisk sukkerrørssaft, mens de to andre er lavet på melasse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario, Kyutchi Rum 40%', 'https://www.uhrskov-vine.dk/ron-millonario-kyutchi-rum-40', 325, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom05724.jpg', 'På tur fra Ron Millonario destillerii Chiclayo til Titicaca-søendistrikt stødte vi på en vidunderlig og målløs natur: Vinikunka Mountain or Montaña de 7 Colores. Da vi var tilbage på destilleriet, ville vi på en eller anden måde formidle denne opdagelse i en ny udgivelse. Det blev Millonario Kuytchi, som nu er blevet testet i løbet af de sidste to år - og det afspejler følelserne i det bjergbillede, vi stadig har i øjnene. Millonario Kuytchi er en ny Rom Spirit Drink baseret på en blanding af peruvianske og caribiske rom, beriget med infusioner af naturlige smage, såsom toffee vanilje, karamel og et magisk strejf af krydderier for at give en perfekt afbalanceret smag. Den kan nydes ren, med is eller blandes i en cocktail, det er nemt at drikke og henvender sig bredt til alle aldre.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('London Dock X.O. Jamaica P.X. Cask Finish Rum 42%', 'https://www.uhrskov-vine.dk/london-dock-xo-jamaica-px-cask-42', 379, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/o/londondockxo.png', 'This rum is a blend of distillates from the worthy park and hampden distilleries in Jamaica. After the principal ageing in old bourbon casks the rum has received a further cask finished refinement in old P.X sherry butt. This gives a rum with a dark amber color and a taste with delicate notes and hints of raisins, brown sugar, figs and vanilla added to the powerful body of the medium ester level classic Jamaica rum.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom Reserva Especial 40%', 'https://www.uhrskov-vine.dk/ron-patridom-reserva-especial-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomreservaespecial2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate LROK 2010 Pure Single Jamaican Rum 47%', 'https://www.uhrskov-vine.dk/hampden-estate-2010-pure-single-jamaican-rum', 1099, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden_1.png', 'Lagret: 11 år på Jamaica - Estermark: LROK (mellem 200-400 gr/hLAA) og denne er målt til 334,7 gr/hLAA', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Communal 43%', 'https://www.uhrskov-vine.dk/clairin-communal-43', 339, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairincommunal.png', 'Clairin Communal er en nyere tilføjelse til serien af haitiansk agricole-rom fra den italienske aftapper, Velier. I modsætning til de andre i serien, er  Communal  en blanding af rom fra fire forskellige destillerier i Barraderes, Cavaillon, Pignon og St. Michel de l’Attalaye, alle lavet med økologisk dyrkede sukkerrør, fermenteret med naturligt forekommende gær og destilleret på traditionelle pot stills eller små kolonner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cashcane Saloon Cask Rum 6 år 55%', 'https://www.uhrskov-vine.dk/cashcane-saloon-cask-55', 399, TRUE, NULL, 55, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/cashcane-saloon-cask-55_2.jpg', 'Cashcane Rum er sammensat af romdestillater fra Barbados, Trinidad og Panama. Rommen er lagret mellem 6-8 år på brugte Bourbon fade og til sidst stukket sammen. I denne version har de valgt at give rommen mere power ved at aftappe ved 55%. Flasken er designet med inspiration fra boubon verdenen og smagen har også mange ligheder med bourbon', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cashcane Extra Old Rum 40%', 'https://www.uhrskov-vine.dk/cashcane-extra-old-40', 329, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/cashcane-extra-old-40.jpg', 'Cashcane Rum er sammensat af romdestillater fra Barbados, Trinidad og Panama. Rommen er lagret mellem 6-8 år på brugte Bourbon fade og til sidst stukket sammen. Flasken er designet med inspiration fra boubon verdenen og smagen har også mange ligheder med bourbon. Næsen: er præget af vanilje fra fadet ligesom man også finder nuancer af tørret frugt. smag: er præget af vanilje og kaffe, som bliver pakket i en let sødme.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Silver Seal 2004 Haitian Rom 13 år 46%', 'https://www.uhrskov-vine.dk/silver-seal-13yo-hitian-46pct', 1599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/silver-seal-13yo-hitian_2.jpg', 'Silver Seal rom fra Haiti 13 år på fad, fra 2004 til 2017. Endnu en unik aftapning med et begrænset antal, kun 355 aftapninger. Rommen byder på smagsnoter af stegt banan og karamel yum.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 41 Belize 17 års Single Cask 65,40%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-no-41-belize-17-single-cask-65-40-rom-deluxe', 1349, TRUE, NULL, 65.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws41belize_1.jpg', 'Wild Series Rum no. 41 kommer fra det berømte Travellers destilleri på Belize. Travellers laver nogle meget smagfulde rom, og har gennem årene være repræsenteret i vores wild serie flere gange. I dette tilfælde er der tale om en 17 år gammmel aftapning som er molasse baseret og kolonne destilleret. Den har lagret 5 år tropisk, inden den er flyttet til europa for yderligere lagring i 12 år. Alle årene i ex. bourbon casks. Den er tappet uden filtrering, for at bevare den gode smag. Smagsnoterne i denne rom er vanilje, toffee, chokolade, appelsinskal og tørrede tropiske frugter. Fakta Belize Single cask                                                                                              Distilled Feb. 2006 At Travellers Distillery Bottled Feb. 2023 Marque MBT12 Aged in Ex. Bourbon cask Tropical and Continentally aged Barrel No. 5 269 bottles Cask Strength at 65,4% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Richland Rum Single Barrel Single Estate Georgia Rum 43% (#95)', 'https://www.uhrskov-vine.dk/richland-rum-43pct-barrel-95', 599, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/i/richland-rum-43pct.jpg', 'Rom fra Georgia? Ja lidt specielt, men bestemt godt! Rommen har en robust struktur og en dyb gylden farve, har aromaer af karamel, vanilje og expresso. Til ganen, sukkerrør, tobak og blomster. Har en lang eftersmag med hints af mørk chokolade, figener og egetræ.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Silver Seal Panama 2000 Don José 15 år Rom 46%', 'https://www.uhrskov-vine.dk/silver-seal-panama-2000-don-jose-15-ar-rom-46', 1299, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/silver-seal-panama-donjose-15yo_2.jpg', 'Denne 15 års Silver Seal Panama Rom blev destilleret i 2000 på Don Jose destilleri i Panama. Dette fad er aftappet i Skotland af Silver Seal den italienske uafhængige aftapper. Dette er en Single Cask rom på 46%.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Elements Eight, Small Batch Exotic Spices Rom 40%', 'https://www.uhrskov-vine.dk/elements-eight-exotic-spices', 249, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/elements-eight-exotic-spices.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Jaguar, Edicion Cordillera, Extra Añejo Rom 43%', 'https://www.uhrskov-vine.dk/ron-jaguar-edicion-cordillera', 379, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ronjaguar.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Vintage 2007 Limited Edition 48,7%', 'https://www.uhrskov-vine.dk/plantation-barbados-vintage-2007-limited-edition-48-7', 649, TRUE, NULL, 48.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbados2007.png', 'Så er der nyt i Vintage-serien fra Plantation Rum! Denne gang stifter vi bekendtskab med en Barbados-rom, hvor tingene er vendt en smule på hovedet. Som regel lagrer Plantation rommen længst tid i troperne, hvorefter den får en kortere ”finish” i Frankrig. Men her har rommen tilbragt ”blot” to år i bourbonfade på Barbados og hele 14(!) år på cognacfade hos  Ferrand  i Cognac! Der er altså tale om en 16 år gammel rom!  Den korte tropiske lagring på giver en dejlig, blød og frisk karakter med masser af kokos, citrus, flamberede bananer, vanilje og marcipan. Herefter 14 år på franske egefade som tidligere har indeholdt Ferrands Grande Champagne-cognac. Den europæiske eg rammer ganen med alt det vi, godt kan lide, nemlig de mørke, varme krydderier som kanel, muskatnød, peber, blomsterpollen, crême brûlée og saftige stenfrugt. Alt i alt en skøn Barbados-rom, destilleret både på pot still og kolonne. Rommen har en stor elegance og lag på lag af duft og smag fra de mange års fadlagring. En overlegen kvalitet til en meget attraktiv pris.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malecon 17 Års Rareproof Rum Panama 51,2%', 'https://www.uhrskov-vine.dk/malecon-rum-rareproof-17-51-2', 649, TRUE, NULL, 51.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malecon17.jpg', 'Ron Malecon 17 år 51,2% Rare Proof, er den nye midterste udgave af Malecons Rare-proof-serie vi har i Danmark. Den er ligesom mange af de andre Malecon rom intens i både duft og smag, det er en flot videreudvikling fra den tidligere 18 års rareproof rom, som der desværre ikke var mere af. Den ekstra alkohol giver en ekstra intens og lækker smag. Der er noter af saltkaramel, butterscotch og et hint af røg, samt vanilje. Der er en meget velintegreret alkohol og der er masser af dejlige fadnoter, egetræet kommer flot igennem, og rommen har det klassiske cubanske tørre præg, uden at være ude af balance. Der er en dejlig sødmefuldhed, som balanceres ud af alkoholen og generelt er det bare et flot glas rom til pengene. Denne rom har masser af kant og kan med fordel bruges til cocktails hvor der skal lidt nedvanding til, eks. old fashioned. Pynt gerne med appelsinskal.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Centenario ÁMBAR 12 Sistema Solera Reserva 40% 100cl', 'https://www.uhrskov-vine.dk/ron-zacapa-centenario-ambar-12-solera-reserva-40pct-100cl', 579, TRUE, 100, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-zacapa-centenario-ambar-12yo-100cl.jpg', 'Denne Zacapa-rom er designet med øje for cocktails, men kan selvfølgelig også nydes for sig selv. Den er lavet under konsultation med bartendere og er et blend af 4-12 år gammel rom. Smagsnoterne inkluderer hint af vanilje og karameliserede tropiske frugter. Det er opskriften på den perfekte Mojito eller Cuba Libre. 1 liters, 40%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chalong Bay Fine Spirit 40%', 'https://www.uhrskov-vine.dk/chalong-bay-fine-spirit-40', 375, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/h/chalong-bay-fine-spirit.jpg', 'Lavet med 100% sukkerrør juice, Chalong Bay Fin Spirit er en sød, frugtagtig, subtilt blomster ånd fra Phuket, Thailand. Tilføj en eksotisk twist til klassiske Rom cocktails med denne spændende flaske.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa ROYAL Solera Gran Reserva Especial, Rum 45%', 'https://www.uhrskov-vine.dk/ron-zacapa-royal-rom-45', 2250, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-zacapa-royal_2.jpg', 'Ron Zacapa Centenario Royal 45% er modsat de seneste "Limitada" skud på stammen fra Zacapa kommet for at blive. Udgivelsen er sket ifm. Ron Zacapas 40 års jubilæum som rommærke, og Royal er kreeret af Master Blender Lorena Vásquez. Ron Zacapa Centenario Royal er lagret efter Solera metoden og afslutttet i franske egetræsfade, som kommer fra 4 forskellige skove, der har været beskyttede siden det 13. århundrede, da kongen indsatte strenge restriktioner vedr. skovhøst. Og deraf navnet Royal. Duft: udtryksfuld og kompleks med noter af tørrede figner, chokolade, tørrede frugter og eksotiske krydderier. Smag: Tung og ikke for sød med noter af flødekaramel, appelsinskal, brændt egetræ og med en krydret samt røget eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Silver Seal Jamaica 16 år Long Pond Distillery 51%', 'https://www.uhrskov-vine.dk/silver-seal-jamaica-16-ar-rom-long-pond-distillery-51', 2299, TRUE, NULL, 51, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/silver-seal-jamaica-16yo_2_1_1.jpg', 'Denne fine Silver Seal Jamaica Rom kommer sjovt nok fra Jamaica, en caribisk ø der er direkte associeret med produktionen af rom. Jamaica er kendt for deres destillerier såsom Appleton og Hampden, men bestemt også for Long Pond Distillery som denne rom kommer fra. Den har lagret på ege tønder i 16 år. Du får en yderst aromatisk og smagsfyldt rom med frugtige noter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairmans Reserve 1931 St. Lucia Rum 46%', 'https://www.uhrskov-vine.dk/st-lucia-1931-3rd-edition-rum', 799, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/z/ezgif-5-be26715838.jpg', 'Chairman’s Reserve Limited Edition 1931 er en gylden rom, der er fadlagret op til 11 år på bourbon- og portvinsfade. Rommen er mere kompleks, og opleves først sød efterfulgt af tørre smagsnoter. Rommen modtog desuden double guld og prisen som ”Spirit of the Year” i 2018 ved World Spirit Awards.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Panama Vintage 2010, Limited Edition 51,4%', 'https://www.uhrskov-vine.dk/plantation-panama-vintage-2010-limited-edition-51-4', 649, TRUE, NULL, 51.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation_panama2010_70cl_eu_mockup-giftbox_002_.png', 'Så er der ny Plantation Vintage i Terravera serien. Denne gang er det en 13 år gammel Panama rom tappet i fuld fadstyrke – ingen sukker eller karamelfarve tilsat!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Distillery Series No. 1 Long Pond 85,3%, RomDeluxe', 'https://www.uhrskov-vine.dk/distillery-series-1-long-pond-85-3-romdeluxe', 899, TRUE, NULL, 85.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaica_2.png', 'Vi har glædet os til endelig at kunne præsentere den første rom i vores Distillery Series of rum. I denne serie går vi lidt tættere på de enkelte destillerier, og viser hvordan deres forskellige tilgang til romproduktionen har indvirkning på de enkeltes rom og de aftapninger der efterfølgende laves. Det er sikkert ikke overraskende for nogen at vi starter på Jamaica. Nærmere bestemt i det øverste hjørne af Trelawny Parish. Her ligger destilleriet LongPond, som blev etableret helt tilbage i 1753, og som de næste par hundrede år har levet en omskiftelig tilværelse med forskellige ejere. I starten havde de deres egen sukkerrørs plantage, men det er en svunden æra. I 1977 overtog den Jamakanske regering destilleriet, og indlemmede det i 1980 i The National Rums of Jamaicas portefølje af destillerier. National Rums of Jamaica ejer stadig en del af destilleriet, og det samme gør Alexander Gabriel fra Plantation. Destilleriet producerer meget smagfulde højester rom, baseret på molasse og destilleret på gamle Pot Still kedler. Der har dog været en periode uden produktion på destilleriet. I perioden 2012 til 2017 byggede man Dunder tankene om og opdaterede hele håndteringen af dette rommens DNA. Desværre skete der en større katastrofe kort efter destilleriet var begyndt at producere igen. En brand i en sukkermark spredte sig til destilleriets Fermenterings hal hvor de store Vats gik tabt i flammerne.  Det betød at man først i 2019 kunne begynde så småt at producere rom igen. Og kun i begrænset omfang indtil alle tanke var på plads igen. Denne rom er destilleret i 2023, og har lagret 7 mdr. på american virgin oak, i det kolde fugtige klima i Danmark. Den er Molasse baseret, og fermenteret i tæt på 30 dage, inden den bliver destilleret på en Potstill kedel. Den lange fermentering er med til at skabe et højt ester count, som i dette tilfælde er 1600 g/hL AA, hvilket er det maksimale antal Estere der må udføres fra Jamaica. Det har givet en rom som har en masse smag, hvor egetræ', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Grenada 2011 Ping 17 Grenada Distillery, 58,3%', 'https://www.uhrskov-vine.dk/planteray-grendda-2011-ping-17-grenada-distillery-58-3', 1509, TRUE, NULL, 58.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/e/renada.png', 'Som mange af jer nok ved, er Ping-prædikatet garanti for en særligt god kvalitet. Serien startede i 2005 og indtil videre har 16 aftapninger vist sig værdige til at bære navnet. Her er den 17. Fadet er valgt vores kyndige romeksperter, Max Scott og Jakob Bunch, i januar 2025. Der er tale om en sjælden rom fra Grenada Distillers, melassebaseret og destilleret på kolonne før 13 års lagring på bourbonfade i Grenada og 1 år på cognacfade i Frankrig. Det er måske den bedste Grenada-rom, vi har smagt! Tappet uden tilsat sukker eller farvestof og ved 58,3% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cueva 1501 Sistema 8 Solera Panama Rum 40%', 'https://www.uhrskov-vine.dk/ron-cueva-1501-sistema-8-solera-panama-rum-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/u/cueva8.png', 'Lagret i op til 8 år i et solera systemet. Den er energisk, frisk og fuld af smag. En strid strøm af chokolade, tropisk frugt og krydderier.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s British Navy Rum 15 år Charred Oak Barrels 40%', 'https://www.uhrskov-vine.dk/pusser-s-british-navy-rum-15yo-oak', 599, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04595.jpg', 'Pusser’s British Navy Rum 15 år, er en rom, der er inspireret af den rom som alle flådeansatte fik i deres dagsration op til 31 Juli 1970 (kendt som Black Tot Day).', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin 2017 Ansyen Single Cask Sarah Dietmayer 49,3%', 'https://www.uhrskov-vine.dk/clairin-2017-ansyen-single-cask-sarah-dietmayer-49-3', 599, TRUE, NULL, 49.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairinsarahdietmeyer.png', 'Denne Clairin Ansyen er et sjældent eksempel på en fadlagret udgave af den haitianske landbrugsrom,  Clairin.  Den er destilleret af Fritz Vaval på Arrawaks-destilleriet i Cavaillon og er lagret 23 måneder på et fad, der tidligere har indeholdt kult-rommen Caroni! Lige netop denne Clairin er udvalgt af bartenderen Sarah Dietmayer fra The Barking Dog i København, som, efter vores mening, er én af landets allerskønneste barer. Rommen er tappet ved fadstyrke (49,3%) og selvfølgelig uden tilsat farve eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Brugal 1888 Gran Reserva Rom 40%', 'https://www.uhrskov-vine.dk/brugal-1888-gran-reserva-rom-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/r/brugal-1888.jpg', 'Brugal 1888 Ron Gran Reserva rom fra den Dominikanske Republik er en super velsmagende rom, som først er lagret på ex-bourbon fade af amerikansk hvideg i otte år, dernæst first fill ex-sherryfade af europæisk eg i op til seks år. Den dobbelte lagring giver 1888 en blød og velafbalanceret profil med en række komplekse smagsnoter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Trois Rivières, Cuvée de L''Océan 42%', 'https://www.uhrskov-vine.dk/trois-rivieres-cuvee-de-l-ocean-42', 255, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom03874.jpg', 'Fransk rom-stil, her fra Martinique kaldes for Rhum Agricole - landbrugsrom. Rom på Martinique er måske den mest ”ærlige rom” i verden. De franske regler (AOC) forbyder at tilsætte sukker og farvekaramel. Der må heller ikke ”fifles” med alderen. Det er den yngste rom i blandingen, der sætter alderen på flasken. Sukkerrørene presses lige efter de er høstet og sukkerrørssaften gæres. Metoden kom i slutningen af 1800-tallet i Martinique. Sukkerpriserne på verdensmarkedet var så lave, så Homère Clement kom med idéen, at lave rom af den friske sukkerrørs juice. Ikke en kvalitetsbeslutning, mere ud fra realitet. Trois Rivières Cuvée de l’Océan er et produkt af saften fra sukkerrør der har groet ved vandfronten, på en solskinsplet i det ekstrem sydlige Martinique, ved Anse Trabaud. Dette gør rommen til et helt unikt produkt, hvor havets kraft tydeligt har haft indflydelse', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Arcane Delicatessime Rum, 41% 70cl', 'https://www.uhrskov-vine.dk/arcane-delicatessime-rum-41-70', 349, TRUE, 70, 41, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/r/arcanedelicat.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 30 Trinidad 30 års Single Cask Rum 59,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-no-30-trinidad-single-cask-59-9', 2699, TRUE, NULL, 59.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/trinidad30.png', 'Denne rom er blevet destilleret hos Trinidad Distillers Limited. Den er destilleret i en kontinuerlig destillation med flere kolonner. Trinidad Distillers Limited blev grundlagt tilbage i 1949, og de bruger sukkerrørsmelasse som kilde til deres gæring. Desuden dyrker de deres egen gærstamme, som tilfører rommen de karakteristiske smagsnoter. Året 1991 er kendt som en af de bedste årgange af Trinidad rom. Fakta: Distilled Dec. 1991 Column Still Distilled At Trinidad Distillers Limited Bottled June 2022 Marque TMAL Aged in Ex Bourbon Cask Tropical and Continentally aged 161 bottles Cask Strength at 59,9% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 3 HJC 22 år Long Pond, Jamaica, 56,2%', 'https://www.uhrskov-vine.dk/plantation-extreme-no-3-hjc-22yo-long-pond-jamaica', 2999, TRUE, NULL, 56.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-ext-no3-hjc-22yo_2.jpg', '22 års rom fra Plantations eksklusive Extreme serie. Denne rom er fra Long Pond Distillery. Smagen er frugtrig med noter af æble, abrikos og pærer. Efterfølgende kommer en dvælende honning og vaniljesmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 3, ITP 22 år Long Pond, Jamaica 54,8%', 'https://www.uhrskov-vine.dk/plantation-ext-no3-itp-22yo-long-pond-jamaica', 2999, TRUE, NULL, 54.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-ext-no3-itp-22yo_2.jpg', 'Plantation Extreme er en serie af ekstraordinære rom, som kældermesteren hos Plantation udpeger til at være for unikke til at blende med andre fade. Det kan både skyldes særegne karakteristika eller exceptionel kvalitet. Denne jamaicanske rom fra det sagnomspundne destilleri, Long Pond, har fået anmærkningen ”ITP”, et såkaldt ”marque / mark” som angiver indholdet af estere i destillatet. ITP menes at stå for Ive Trelawny Pot, og angiver et esterindhold mellem 90 og 120 gram per hektoliter ren alkohol. Men efter 22 års lagring er esterniveauet i denne rom steget til 386 gram per hektoliter ren alkohol! En kæmpe romoplevelse for både nørder og nybegyndere.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes 11 år Fiji 66,8%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-11yo-fiji-rom-66pct', 950, TRUE, NULL, 66.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-fiji-11yo-66pct_2.jpg', 'Rum Compagnie des Indes Fiji er en single cask aftapning (enkelt fad) fra “South Pacific Destillerie” fra Sydhavet. Først får rommen en indledende modning i Fiji, hvor efter den bliver transporteret til Frankrig for at blive modnet. Kun 234 flasker af denne "bottled for Denmark" aftapning. En meget eksotisk rom!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Caroni 1991 24 år, Trinidad 56,3%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-caroni-1991-24-ar-trinidad-56-3', 3995, TRUE, NULL, 56.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-indes-caroni-1991-24_2_1.jpg', 'Fra det nu lukkede Caroni Destilleri på Trinidad. Aftappet af den unge Rom komet Florent Beuchet - manden bag Rhum Compagnie des Indes. Denne Cask Strength enkeltfads aftapning er aftappet ved fadstyrke på 56,3%. Destilleret 1991, og aftappet 2015. Rommen er modnet i 24 år på gamle bourbon fade og både lagret i Caribien samt en årrække i Europa efterfølgende.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray PX XO 20th Anniversary Rum 40%', 'https://www.uhrskov-vine.dk/planteray-px-xo-20th-anniversary-rum-40', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteraypxxo.png', 'Med over 60 priser for sin ekstraordinære kvalitet og håndværk, fremhæver Planteray PXXO den dobbelte lagring, der er kendetegnende for Planteray Rum. Som en hyldest til de fine Pedro Ximenez-huse i Andalusien, Spanien, bliver rommen nu lagret for tredje gang i elegante ex-Pedro Ximenez-fade, hvilket tilføjer en nøddet, tørret rosin-agtig finish til denne udsøgte sipping rom. Denne hyldest til traditionelle teknikker skaber en ny dimension for vores mest prisbelønnede udtryk og begejstrer både nye og loyale fans. I tråd med Planteray Rums traditionelle stil, modnes Planteray PXXO først i ex-bourbon-fade i Barbados'' tropiske klima, før det bliver transporteret til søs i disse fade til det sydvestlige Frankrig for en anden modning i ex-Ferrand-fade. En tredje modning finder sted i ex-Pedro Ximenez-fade i nogle måneder for at løfte blandingen. Planteray PXXO er en rig og fløjlsagtig sipping rom med rige noter af kokos og vanilje, der ledsages af delikate aromaer af tropiske frugter, krydderier og kaffe.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Cut & Dry Artisanal Coconut Rom 40%', 'https://www.uhrskov-vine.dk/planteray-cut-dry-artisanal-coconut-rom-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteraycoconut.png', 'Glem alt om Malibu – det her er kokosrom, som du aldrig har smagt det før! Mega-succesen Stiggin’s Fancy Pineapple Rum beviste, at  Planteray  kan noget helt særligt med tropisk frugt og rom – og efter at have arbejdet med opskriften i bogstaveligt talt årevis, er Cut & Dry Artisanal Coconut Rum endelig at finde på hylden. Hemmeligheden er naturligvis ægte kokosnød dyrket på Barbados. Det hvide frugtkød infuseres i god barbadosrom - der bruges 1 kokosnød til hver liter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('River Antoine Rivers Royale Grenadian Rum Blanc, 69%', 'https://www.uhrskov-vine.dk/rivers-antoine-blanc-rom-69', 695, TRUE, NULL, 69, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/i/rivers-a.png', 'River Antoine Distillery er et historisk monument i romens verden. Grundlagt i 1785 er det ganske enkelt den ældste romfabrik på øen Grenada, men også i Vestindien. Gennem hele sin historie har det holdt den samme håndværksmæssige fremstilling af rom af ren sukkerrørsaft, der opretholder traditionen med at knuse røret ved hjælp af en hydraulisk mølle, spontan gæring uden tilsætning af gær. Rivers er en intens rom med fokus på citrusfrugter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Trinidad, Single Barrel Selection 1993 Caroni The Beast #2, 49,6%', 'https://www.uhrskov-vine.dk/sbs-trinidad-single-barrel-selection-1993-caroni-the-beast-2', 3295, TRUE, NULL, 49.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-trinidad-1993-1-e1555320571861.png', 'A controverse gem from the now-closed Caroni distillery. The almost black color gives a good indication on the barrels influence on this rum. It’s no coincident this rum is called “The Beast”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Arcane Flamboyance Single Cask Rum, 40% 70cl', 'https://www.uhrskov-vine.dk/arcane-flamboyance-single-cask-rum-40-70', 599, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/l/flamboy.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rumbullion, XO 15 Years Spiced Rum, 46,2%', 'https://www.uhrskov-vine.dk/rumbullion-xo-15-years-spiced-rum-46-2', 699, TRUE, NULL, 46.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/1/5/15yo.jpg', 'Rumbullion! XO – den ældre og klogere spiced rum i sortimentet. Rombasen af denne lækre rom er mindst lagret i 15 år, og hvorefter der tilsættes madagaskansk vanilje, appelsinskal, kanel, nelliker og kardemomme, som vi bruger i resten af Rumbullion! serien. Den er forførende med en intens dybde, der måske lyder som starten på en fremragende datingprofil. Men i stedet for lange gåture på stranden nyder vores XO at blive drukket og nydt – hvilket vi håber du vil. Ligesom resten af serien fra Rumbullion! viser XO også sin sørfartsinspiration med det rå look fra det krøllede brune papir, der er viklet med garn og forseglet med sort voks.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Silver Seal Tasting Collection 6 x 5cl', 'https://www.uhrskov-vine.dk/silver-seal-tasting-collection', 1899, TRUE, 5, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/i/silver-seal-collection_4_2.jpg', 'Her har du muligheden for at få en unik smagsoplevelse. 6 forskellige eksklusive rom, fra den fantastiske Silver Seal serie.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus Rom Gaveæske 6x2cl', 'https://www.uhrskov-vine.dk/opthimus-rom-gaveaeske-6-2-cl', 249, TRUE, 2, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/a/gave5513.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 12, Guyana 16 års Rum, 53%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-12-guyana-16-53-romdeluxe', 1199, TRUE, NULL, 53, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guyana12_boks.jpg', 'Her kommer en rigtig lækker rom fra Guyana. Den er destilleret på den gamle Ikoniske PotStill Kedel som heder Varsailles. Her er tale om en virkelig lækker rom, som har lagret 8 år i troperne inden den er transporteret til europa, hvor den har lagret yderligere 8 år i det milde kontinentale klima. I denne rom finder man masser af smag. der er lakrids, læder, tobak, vanilje, tørret tropisk frugt, og ikke mindst smagen af fad, som på en balanceret måde runder det hele af på en fantastisk måde. Fakta: Guyana Single cask Marque REV Molasse based / Versailles Pot Still Distilled June 2006 Bottled Sept. 2022 Tropical and Continental aged Aged in Ex. Bourbon cask Cask no. 5 249 bottles Cask Strength at 53,0% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('English Harbour Sherry Cask Rum 46%', 'https://www.uhrskov-vine.dk/english-harbour-sherry-cask-rom-46', 349, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/harbour.png', 'Fin Antigua-rom lagret i minimum 5 år i Bourbon-tønder og afsluttet på nøje udvalgte Oloroso-sherryfade, hvilket giver bemærkelsesværdigt dybe og rige komplekse noter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Venezuela Vintage 2010, Limited Edition 52%', 'https://www.uhrskov-vine.dk/plantation-venezuela-vintage-2010-limited-edt-52', 799, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/e/venezuela.png', 'Så er tiden kommet til den sidste rom i Plantations populære serie,  Under the Sea . Denne gang skal vi til Venezuela, hvor Alexandre Gabriel har opsnust en fantastisk melasse-baseret rom. Den er destilleret i 2010, hvorefter den er lagret 8 tropiske år i ex-bourbonfade i Venezuela. Plantation valgte i alt 22 fade, som så har taget turen over Atlanten for at lagre videre i fade af fransk eg i Ferrands egne kældre. Rommen er tappet ved 52% og der er hverken tilsat farvestof eller sukker. På etiketten ses en Plettet Ørnerokke – et af Venezuelas symboler.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Jamaica 5 Years 43%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-jamaica-rom-5-ar-43', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/o/com-jamaica-5yo-43pct_2.jpg', 'Compagne Des Indes Rom. Denne 5 års rom er en blend af rom udvalgt fra de bedste jamerikanske destillerier. Rommen er lagret på bourbon fad, og aftappet ved 43% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sugar Estates Jamaica 1949 Rum 11 år Moon Import 45%', 'https://www.uhrskov-vine.dk/sugar-estates-jamaica-1949-rum-11-ar-moon-import-45', 999, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/u/sugar-estates-jamaica-1949-45pct_2.jpg', 'Jamaica 11 års Rom, Sugar Estates 1949 fra Monymusk destilleriet i Jamaica. Rommen er destilleret i 2003 og aftappet i 2015. Destillation udføres med små stills af dobbelt destillation i kobber pot stills, som er en jamaicanske tradition. Den jamaicanske rom er produceret af en særegnet blanding af melasse og sukkerrørs saft. Du får her unik og aromatisk rom. Den modnet i Skotland og aftappet i Storbritannien. Rommen har en god sødme af honning.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Jamaica Rum Monymusk 2003 Moon Import 45%', 'https://www.uhrskov-vine.dk/jamaica-rum-monymusk-2003-moon-import-45-70cl', 999, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-jamaica-agricole-monymusk-moon-import-45pct_2.jpg', 'Destilleret i 2003, aftappet i 2016. Denne rom er produceret af Monymusk destilleriet som er et jamaicansk destilleri. Aftappet i United kingdom og rommen er specialudvalgt af Pepi Mongiardino fra Moon Import.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Elements Eight, Small Batch Distillation Gold Rum 40%', 'https://www.uhrskov-vine.dk/elements-eight-gold-rom', 249, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/elements-eight-gold-rom.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo 12 år Añejo + Abuelo Two Oaks 20 cl Giftbox', 'https://www.uhrskov-vine.dk/abuelo-12-anejo-abuelo-two-oaks-20-giftbox', 449, TRUE, 20, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/b/abuelogift.png', 'En duft af Rørsukker, let krydret, nougat, mokka, lys chokolade, vanilje. Smager af frisk og syrlig med en fyldig sødme. En lang eftersmag af sødme som fylder hele munden. Produceres i Panama af Varela Hermanos, som oprindeligt har lært romhåndværket i Cuba. Mere rund end den 7 årige og blød, lidt til den søde side. Indbegrebet af imødekommende Caribisk rom. Fra Panama er "bedstefar rommen" nu kommet til Danmark.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Distillery Collection Batch No. 1 Kettle Rum 47%', 'https://www.uhrskov-vine.dk/diplomatico-distillery-collection-no-1-batch-kettle', 495, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplo1.png', 'Denne limited edition- rom fra Venezuela er den første i Diplomáticos eksklusive Distillery Collection, som hylder forskellige destillationsmetoder og deres indflydelse på smagsprofilen. Batch No. 1 er destilleret på det sjældne batch kettle -apparat, oprindeligt fra Canada og installeret på Diplomáticos La Miel-destilleri i 1959. Rommen er lavet på sukkerrørshonning og lagret i seks år på amerikanske egetræsfade, der tidligere har indeholdt bourbon og maltwhisky. Dette giver en dyb og kompleks karakter. Næse: Fyldig aroma af vanilje, skovfrugter, træ, æble og pære. Smag: Blød og balanceret med noter af lakrids, karamel og modne skovfrugter. Eftersmag: Lang og varm med tydelige toner af egetræ og krydderi. Begrænset oplag: Kun 5.000 flasker produceret Diplomático er et prisvindende romhus fra Venezuela, kendt for sin håndværksmæssige tilgang til romproduktion og sin karakteristiske, fyldige stil. Destilleriet blev grundlagt i 1959 ved foden af Andesbjergene og har siden været anerkendt for sin dygtighed i både destillation og lagring. Diplomático kombinerer tre forskellige destillationsmetoder – kobber pot stills, column stills og batch kettle stills – for at skabe komplekse og nuancerede romtyper. Denne alsidighed gør det muligt at fremstille både lette og kraftige rom, som senere blendes til unikke udtryk.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wagemut PX Cask Barbados Rom 40,3%', 'https://www.uhrskov-vine.dk/wagemut-px-cask-barb-rom-40-3', 349, TRUE, NULL, 40.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/a/wagemut.png', 'Wagemut’s PX-Cask er en hyldest til autenticitet og kvalitet. Denne lækre spiritus fra Barbados lagres i 10 år, før den udvikler sin karakter og kompleksitet yderligere i deres tyske fadlager. Den tilbringer sine sidste 3 måneder i friske Pedro Ximénez-sherryfade fra Wagemut, hvilket tilfører ekstra dybde og fylde. Med fokus på gennemsigtighed og autenticitet præsenteres hvert trin i rommens produktion ærligt og åbent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Antigua 2015 Bourbon & Marsala Cask Rom 55%', 'https://www.uhrskov-vine.dk/sbs-antigua-2015-bourbon-marsala-cask-rom-55', 849, TRUE, NULL, 55, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbsantigua2015.png', 'Single Barrel Selection Antigua 2015 er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne still i 2015. Rommen har lagret på et tidligere Bourbon og Marsala fade og er tappet ved 55% alkoholstyrke i august 2024. Antigua bliver sjældent set flasket af uafhængige flaskere, så vi håber, du vil nyde den. Rommen er ikke koldfiltreret. S.B.S Antigua 2015 er begrænset til kun 369 flasker', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rum 25 år Reserva Panama 40% 20cl', 'https://www.uhrskov-vine.dk/malteco-rum-25-40-20', 249, TRUE, 20, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco20.png', 'Malteco rum er i stilen en Guatemala rom på trods at oprindelseslandet er Panama. Destilleriet Varela Hermanos der laver Malteco rum ligger i byen Pesé i den sydlige del af det centrale Panama. I 1908 etablerede den daværende ejer, Don José Varela Blanco, den første sukkerfabrik. Senere, i 1936, åbnede romfabrikken, som lige siden har produceret rom af høj kvalitet. Varela Hermanos er den største leverandør af rom til hjemmemarkedet i Panama, og leverer mere end 90% af al rom til de lokale. Rommen er destilleret på kolonne-kedler og er derfor i den elegante, lette stil, hvilket også er kendetegnede for rom fra Guatemala. Rommen bliver lagret på 220 liters brugte bourbonfade af hvid, amerikansk eg. Tønderne giver rommen en passende kontakt med fadet, hvor mindre tønder ville give for meget kontakt og større tønder for lidt. Malteco 25 rum er en helt igennem udsøgt rom, hvor melasse, farin, svesker, tørrede rosiner og en lækker cremethed går igen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Carribean Añejo 5+3 & 5+5 Gaveæske, 2x20cl', 'https://www.uhrskov-vine.dk/dos-maderas-carribean-anejo-5-3-5-5-gaveaeske', 245, TRUE, 20, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmade20c.png', 'To delikate blandinger fra Barbados og Guyana. To lande med deres egen romstil. Begge lande laver nemlig rom på pot stills og kolonneapparat. Den kraftige og aromatiske rom laves på pot stills og den mere blide og afrundede på mere moderne kolonneanlæg. Dos Maderas 5+3 og 5+5 er født på ens. Håndlavet og lagret i Caribien som det første. Herefter sendes rommen til Williams & Humbert Bodega i Jerez, hvor den får en tur i et system, der ligner en solera. ”Dos Maderas” er spansk og betyder netop to slags træ, hvilket henviser til måden den lagres og modnes på. Forskellen på Dos Maderas 5+3 og 5+5 er lagringstiden. 5+3-udgaven er 8 år undervejs. Først 5 år i Caribien i ex-bourbon fade og derefter 3 år i Spanien i ex Dos Cartados Oloroso sherry fade (meget tør sherry) – derfor 5+3 … derav navnet Double Aged Rum! 5+5-udgaven for ud over de 5+3 også + 2 år i ex Don Guido Pedro Ximenez sherry fade (meget sød sherry) - derfor 5+3+2 = 5+5 .... deraf navnet Tripple Aged! Produktet heder ikke rom, da dukkeret overstiger 20 gr/l - det kaldes for spirit drink.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Blackadder Raw Cask 2009 Finest Panama Rum FC-Whisky 20th Anniverssary, 63,2%', 'https://www.uhrskov-vine.dk/blackadder-2009-panama-fc-whisky-anniversary-63-2', 849, TRUE, NULL, 63.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/blackadder11.png', 'Denne fantastiske mørke rom er ikke "Chill-filtered" og ikke tilsat nogen form for farve.  Panama 2009 RUM fra et enkelt fad har givet 266 flasker og har spor af honning, karamel, brun sukker og vanilje med den subtile tilføjelse af eksotiske krydderier.   Den brune sukker og karamellen fortsætter i eftersmagen sammen med en mild tannin og en "prikken" på tungen. En fremragende dram, der let kan drikkes ren på trods af de 63,2% alkohol, men der kan også tilsættes lidt vand, som får rommen til at åbne sig yderligere .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Guyana 1990 Port Mourant Rom 53,1%', 'https://www.uhrskov-vine.dk/sbs-guyana-1990', 3399, TRUE, NULL, 53.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_guyana_1990.jpg', 'S.B.S Guyana 1990 er et ”single cask” med kun 192 flasker. Den er lavet på det berømte Double Wooden Pot Still fra Port Morant Distillery, som også er verdens ældste træ pot still. Pot stillet stod på Uitvlugt Distillery, da rommen blev destilleret, hvorfor det er det destilleri, som er angivet på flaskens label. Uitvlugt lukkede tilbage i 2000 og blev flyttet til Diamond Distillery.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Equiano Light Rum, 70cl 43%', 'https://www.uhrskov-vine.dk/equiano-light-rum-70-43', 339, TRUE, 70, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/q/equianolight.png', 'Equiano er et nyt brand som allerede har vundet adskillige internationale priser for deres rom.   Nu kommer det seneste skud på stammen.   Equiano light er ikke light i alkoholen. den holder 43% ABV, ligesom dens storebror.   Den er blevet til i et samarbejde mellem to unikke destillerier på to forskellige kontinenter, der forener det bedste fra både den østlige og vestlige halvkugle, for at bringe noget helt nyt til et århundreder gammelt håndværk. Forfriskende unik, Equiano Light er en enestående blanding af let ældet melasse rom fra Caribien, fusioneret med frisk sukkerrør juice fra Afrika.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Hechicera Serie EXPERIMENTAL NO. 1 Ron Extra Anejo, Columbia, 43%', 'https://www.uhrskov-vine.dk/la-hechicera-experimental-no1-columbia', 599, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/lahechicera_experimental_rum_1_720x.jpg', 'Fantastisk Rom fra det sidste familieejede destilleri i Colombia. blandet og lagret mellem 12 og 21 år i hvid eg. Navnet udtales "etch-ee-SEH-Rah« og navnet betyder "Enchantress" på spansk.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Samaroli Demerara Vertical (03-04) Blended Rom, 45%', 'https://www.uhrskov-vine.dk/samaroli-demerara-vertical-blended-rom-45', 1385, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/samarolidemerara.png', 'Samaroli Demerara Vertical 03-04 Rum er produceret af italienske Samaroli, der har tappet destilleret rom fra Guyana på flaske efter endt lagring i Skotland i september 2017. Der er tale om en begrænset udgivelse af kun 520 flasker. Duft:  Friske blomster, sødt korn, honning, vanilje Smag:  Gummi, lakrids, kraftig krydret: paprika og ingefær', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Royal Oak St. Lucia Rum, 40%', 'https://www.uhrskov-vine.dk/admiral-rodney-royal-oak-rum-40', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/royaloak_1.png', 'RUM BLEND:  Admiral Rodney Royal Oak, the original Admiral Rodney blend, contains 7-12 year old Coffey still rum that has been aged exclusively in previously used Bourbon casks and blended to perfection. TASTING NOTES : Bright amber color with a nose of prunes, raisin fruit, toasty oak and tropical spiced. Intense mouth-feel of sweet sultana fruit, tobacco, and chocolate, with vanilla from the oak. Complex finish with sweet fruit, caramel, and spice.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin 2020 Le Rocher Haiti 47,2%', 'https://www.uhrskov-vine.dk/clairin-2020-le-rocher-haiti-47-2', 449, TRUE, NULL, 47.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairinlerocher.png', 'Le Rocher er en hvid rom fra Haiti. I modsætning til de fleste af de andre  clairins  i Veliers serie, er Le Rocher ikke lavet på frisk sukkerrørssaft, men på en indkogt sukkerrørssirup. Master distilleren Bethel Romulus er en religiøs mand, og han har kaldt rommen  Le Rocher  (Klippen) efter en passage i Matthæusevangeliet, som forkynder, at en klog mand bygger sit hus på en klippe, mens en tåbe bygger på sand. Bethel Romulus har naturligvis bygget sit destilleri på en klippe.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin 2020 SonSon Haiti 53,2%', 'https://www.uhrskov-vine.dk/clairin-2020-sonson-haiti-53-2', 449, TRUE, NULL, 53.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/o/sonson.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Nicaragua 21 års Rum, 61%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-nicaragua-2000-21-aars-rom-de-luxe-61', 1299, TRUE, NULL, 61, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/n/i/nicaragua.png', 'Denne gang er det lykkedes at finde et virkeligt spændende fad fra Nicaragua. Rommen er destilleret på Licorera de Nicaragua destilleriet. Den er hele 21 år gammel. men har stadig den frugtede friskhed da den er lagret kontinentalt i alle årene.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna 2008 Rhum Traditionnel Vieux 10 Års Rom, 43%', 'https://www.uhrskov-vine.dk/savanna-traditionnel-10-ars-rom-43', 699, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/savanna10.jpg', 'En kompleks og velafbalanceret rom fra Réunion lagret i 10 år. Den byder på noter af modne frugter, vanilje og milde krydderier med en tør, elegant afslutning.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 8, Dominican Republic 15 års Rum, 65%, RomDeluxe', 'https://www.uhrskov-vine.dk/dominican-republic-15-collectors-series-rum-romdeluxe-65', 1119, TRUE, NULL, 65, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/domrep.png', 'Tilbage i 2016 udgav vi den første aftapning under mærket Romdeluxe. Det var en rom fra Den Dominikanske Republik. Frigivet ved en fadstyrke på 65%. Den var meget populært blandt vores kunder. Og lige siden da har vi ønsket at finde noget endnu bedre fra dette område. Nu har vi fundet endnu en rom herfra. Det er en 15 år gammel dominikansk rom, som har denne helt unikke fede og bløde fornemmelse i munden som dominikansk rom skal have. Efterfølgende har vi blendet den med en anden helt speciel rom. En 1 år gammel højester rom kaldet Aroma Grande. Denne rom blev vi opmærksomme på for nogle måneder siden, og det er en helt vidunderlig og smagfuld rom. Den har et estertal på 474 gr./HLAA Det er efter vores oplysninger den første gang der er produceret højester rom i Den Dominikanske Republik, hvilket vi naturligvis ikke kunne stå for.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Jamaica 7 års Rum, 63,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-jamaica-7-rom-romdeluxe-63-9', 649, TRUE, NULL, 63.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/i/limitedbatch.png', 'Her kommer en 7 år gammel rom fra Jamaica. Den har lagret 5 år tropisk hvorefter den har efterlagret i et Islay Whiskyfad kontinentalt i 2 år. Den er baseret på Molasse, og destilleret på en forsyth Potstill. I denne rom får man en lækker potent jamaica rom med nogle fine røgede noter, som komplementerer rommen rigtig godt.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 2021 The Younger, Pure Single Jamaican Rum, 47% 300cl', 'https://www.uhrskov-vine.dk/hampden-estate-2021-the-younger-pure-single-jamaican-rum-47-300', 3169, TRUE, 300, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdenestateyounger.png', 'Hampden Estate The Younger LROK er en 5 år gammel rom fra Jamaica. Som navnet antyder, er rommen ung – kun 5 år – men lagringen er foregået i troperne, så den føles imponerende moden allerede. Og hvad den ikke har i alder, har den så sandelig i kvantitet: det her er nemlig hele 3 liter jamaicansk herlighed! Rommen er en såkaldt LROK, hvilket står for Light Rum Owen Kelly, og betegner et ester-indhold på mellem 200 og 400 gram per hektoliter ren alkohol. Den er tappet ved 47% alkohol. Farve : Gylden.  Duft : Delikat duft af mango, banan, peber og lak. Smagsnoter : Ananas, appelsinskal og nellike. Serveringsforslag : Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Tres Hombres 2017 Edition 18, 26 år Republica Dominicana 64,8% 100cl', 'https://www.uhrskov-vine.dk/tres-hombres-26yo-republica-dominicana', 1995, TRUE, 100, 64.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/tres-hombres-26yo-republica-dominicana_1.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 13, Barbados 15 års Rum, 60,7%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-13-barbados-15-60-7-rom-deluxe', 1079, TRUE, NULL, 60.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbados13_boks.jpg', 'Her er der tale om en rom fra Foursquare hvor Richard Seale og hans Crew udøver deres magi. Det er en rom som har lagret ganske få år i troperne inden den er transporteret til Europa, hvor den er lagret på et ex. Malt whisky fad. Dette fad har medvirket til at denne rom er meget blød og behagelig at drikke.  Her får man noter af blød saftig kokos, vanilje, toffee, mørk chokolade og en lang behagelig finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Australia 2009 12 års Single Cask Rum, Bottled for Uhrskov 45%', 'https://www.uhrskov-vine.dk/plantation-australia-vintage-2009-uhrskov-45', 699, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/u/australia2009.jpg', 'Nose : Fruity on pear, mandarin jam, grapefruit zest and dried apricot. Spicy notes of pepper, cloves, cinnamon, anis and pistachio with oxidative and vinous touches of the palo cortado. Palate : Well balanced between the rum, oak and the sherry on chocolate, almond, cherry, blueberry, banana, bitter orange and some elegant rose notes.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana 17 YO Denmark Single Cask Rum 56,3%', 'https://www.uhrskov-vine.dk/plantation-guyana-17-aar-denmark-single-cask-rum-56-3', 1999, TRUE, NULL, 56.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50641272-plantation-guyana-17-years-old-denmark-cask.jpg', 'Et kanonslag af en rom. Plantation Guyana 17 Year Old, tappet eksklusivt til det danske marked, er en tour de force udi superpotent Guyana-rom, med stor kompleksitet og en uendelig finish. En rom som beviser, at Plantation sagtens kan være med på beatet når det gælder nørdet fadstyrke-rom. Ja, faktisk kunne dette være noget af det bedste rom, Plantation har udgivet! Farve:  Mahogni Duft:  Orangeskal, nelliker og kakaonibs. Smagsnoter:  Stor smag af engelsk lakrids, brændt karamel, hasselnødder og Kongen af Danmark-bolcher. En eftersmag længere end en Peter Jackson-film! Serveringsforslag:  Det eneste rigtige er at drikke denne rom rent, evt. med enkelte dråber køligt vand.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Papalin 4 Years Old Haiti 53,1%', 'https://www.uhrskov-vine.dk/papalin-4-years-old-haiti-531', 749, TRUE, NULL, 53.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50625249-papalin-4-years-old-haiti.jpg', 'Den nyeste rom i Papalin-serien er fra Haiti: en blanding af destillater fra Clairins Vaval, Sajous, Casimir og Le Rocher, lagret på bourbonfade, cognacfade og romfade (bl.a. fra Caroni). Den er tappet ved 53,1%. Farve : Let gylden. Duft : Både frugtig og krydret, med noter af vanilje, blomme og kamfer.  Smagsnoter : Mediumfyldig, tør og koncentreret. Her er bl.a. tobaksnoter, stenfrugt ingefær og vanilje. Serveringsforslag : Nyd den rent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Rum Darklice 43%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-rum-darklice-43', 359, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-darklice-43pct_2.jpg', 'Compagnie Des Indes Darklice er en blend af forskellige rom fra Caribien, sammensat med lakridsvand, "CDI" har selv kreeret denne lakrids-væske. Lakrids-væsken bliver fortyndet i varmt vand og bagefter sammensat med den delikate Rom. Denne Rom er designet specielt til det danske marked, hvor lakridsen generelt er meget populær.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Long Pond 1977 Single Bourbon Cask 35 YO Ping 9, Jamaica 61%', 'https://www.uhrskov-vine.dk/ping-9-35-ar-jamaica-rom-1977', 25000, TRUE, NULL, 61, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/i/ping-9-35yo-jamaica-1977_2.jpg', 'Ping No. 9 er en unik 35 års rom der er aftappet på fadstyrke af 61%. Faddet er et amerikansk oak bourbon barrel. Rommen har lagret siden 1977 og det er kun blevet til 221 flasker af Ping No. 9, hvilket også gør denne udgivelse mere enestående.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Foursquare Plenipotenziario Single Blended Rum 60%', 'https://www.uhrskov-vine.dk/foursquare-plenipotenziario-single-blended-rum', 2199, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/foursquare-plenipotenziario-single-blended-rum_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Touchstone 14 Års Exceptional Cask Single Blended Rum 61%', 'https://www.uhrskov-vine.dk/foursquare-touchstone-14-exceptional-cask-blended-rum-61', 1399, TRUE, NULL, 61, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/o/touchstone.png', 'Foursquare Touchstone er smmensat af to forskellige rom, begge 14 år gamle. En 5 år gammel rom, først modnet i Ex-Bourbon-fade, blev derefter overført til Ex-Cognac-fade i yderligere 9 år. Den anden rom der indgår i Touchstone blev lagret 12 år i Ex-Bourbon-fade og derefter overført til Ex-Camus Cognac-fade i yderligere 2 år.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate HLCF Overproof Rum i Gaveæske m. 2 glas, 60%', 'https://www.uhrskov-vine.dk/hampden-estate-hlcf-overproof-giftbox-2-glas', 849, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdenestatehlcf.png', 'Hampden Estate HLCF er klassisk Jamaica-rom, når det er bedst! Ung (men tropisk lagret), potent og rimelig høj på esters.  Her får du 2 smukke tumbler-glas fra Riedel med i købet - og "bogen", de er pakket i, indeholder både facts, historie og cocktail-opskrifter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin Jamaica WPH White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-jamaica-wph-white-rum-57', 419, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaicawph.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. This bottling contains a wonderful white rum distilled in traditional pot stills making great Daiquiris. Tasting notes: Nose:  Fresh cut grass and lots and lots of tropical fruits. This is a very powerful rum that keeps developing in the glass. Palate:  Lots of banana, fresh cane juice and exotic fruits. Jamaican funkiness at its best.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum, Limited Edition Port Cask Finish 46%', 'https://www.uhrskov-vine.dk/rammstein-rum-limited-edt-port-cask-finish-46', 599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/rammsteinport.png', 'Founded in East Berlin in 1994, today Rammstein is regarded as one of the most successful international bands, achieving 7-digit album and DVD sales. In the course of their 20-year career, the musicians were nominated twice for the Grammy, headlined all major music festivals and sold out arenas all over the world. Still with all its original members, Rammstein’s status as an unrivaled live band is due to its unique (trying to copy it is not recommended) stage show: a fierce rock opera – dramatic, spectacular, epic in scale and touching all senses; a dark fairy tale pervaded with controversy and the all-consuming smell of benzine. This Rammstein rum is a balanced blend of Jamaican and Guyanese pot still rum and coloumn still rum from Trinidad. Guyanese and Jamaican rums are valued by masterblenders and experts alike for their heavy bodies and deep aromas. The strong characters of both pot still rums are tamed by the elegant nature og their Trinidadian counterpart. This limited edition has matured in ex-Bourbon barrels for up to 12 years, and received a finish in ex-Port wine barrels. Tasting Notes Nose : Delicate aromas of ripe red fruits such as cherries, plums and blackberries with a nice touch of oak. Palate : Fruity and mild with complex notes of dark chocolate, dried tobacco and oak.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Jamaica 1999 Arran Whisky Cask Rum, 46,7%', 'https://www.uhrskov-vine.dk/plantation-jamaica-1999-arran-whisky-cask-rum-46-7', 1549, TRUE, NULL, 46.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation1999.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron 1914 Ediciòn Gatún, Panama 41,3%', 'https://www.uhrskov-vine.dk/ron-1914-edicion-gatun-panama-41-3', 499, TRUE, NULL, 41.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50632100-ron-1914-edici_n-gat_n.jpg', 'Ron 1914 Edición Gatún er en klassisk Panama-rom med både fylde, dybde og sødme. Navnet henviser til det år, Panamakanalen åbnede, og denne særlige udgave er sammensat af flere komponenter med en alder på mellem 15 og 22 år. De er alle lavet på melasse, og 80% er destilleret på kolonnekedel. De sidste 20% kommer fra en kobber-pot still, som giver en lidt tungere rom med en mere kraftig smag, og blandingen af de to typer ender i perfekt balance. Lagringen foregår på brugte bourbonfade hvorfra der kommer noter af karamel og brun farin, vanilje og ristet kokos. Farve : Mørkt rav. Duft : Masser af karamel og tørret frugt, strejf af ingefær, læder og appelsin.  Smagsnoter : Ligger blødt og varmende på tungen med noter af brun farin, kokos og kakao, som fører ind i en krydret finish med hints af ingefær og tobak. Serveringsforslag : Bør nydes rent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Takamaka Dark Spiced Rum 38%', 'https://www.uhrskov-vine.dk/takamaka-dark-spiced-rum-38', 225, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/a/takamaka.png', 'Takamaka Dark Spiced er flagship sukkerrørsspiritus, og alles favorit på Seychellerne. Den har bløde noter af lokale krydderier, papaya og karamel med toner af græd og tør eg som undertone. De blander deres hvide rom med deres særlige blanding af naturlige essenser, der inkludere vanilje, papaya og tropiske krydderier.  Selvom du er mere end velkommen til at nyde rommen på den klassiske måde - eller med cole - er den bedst, når du ligger end i en hængekøje.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate Pagos Batch 3, Pure Single Jamaican Rum 52%', 'https://www.uhrskov-vine.dk/hampden-estate-pagos-batch-3-jamaican-rum-52', 799, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdenpagos_2.png', 'Hampden Estate er en af Jamaicas mest ikoniske romproducenter, kendt for sine kraftige, esterrige og aromatiske rom. Pagos Batch 3 er en unik aftapning, der kombinerer Hampdens traditionelle produktionsteknikker med en særlig lagring på sherryfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Distillery Collection No. 2, Barbet Rum 47%', 'https://www.uhrskov-vine.dk/diplomatico-distillery-collection-no-2-barbet-rum', 495, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplo2.png', 'Denne limited edition-rom fra Venezuela rom er den anden udgivelse i Diplomáticos eksklusive Distillery Collection og er destilleret på et sjældent Barbet-kolonnestill, som giver en let, frisk og frugtig karakter. Lagret i 4 år på amerikanske egetræsfade, tidligere brugt til bourbon og whisky.. Næse: Mango, passionsfrugt og citrus Smag: Let tør med noter af vanilje, karamel og eg Eftersmag: Lang, varm og elegant med subtile krydderier   Begrænset oplag: Kun 5.000 flasker produceret Diplomático er et prisvindende romhus fra Venezuela, kendt for sin håndværksmæssige tilgang til romproduktion og sin karakteristiske, fyldige stil. Destilleriet blev grundlagt i 1959 ved foden af Andesbjergene og har siden været anerkendt for sin dygtighed i både destillation og lagring. Diplomático kombinerer tre forskellige destillationsmetoder – kobber pot stills, column stills og batch kettle stills – for at skabe komplekse og nuancerede romtyper. Denne alsidighed gør det muligt at fremstille både lette og kraftige rom, som senere blendes til unikke udtryk.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ocean''s Rum Mellow 7 år Finest Blended Rum 40%', 'https://www.uhrskov-vine.dk/oceans-rum-mellow-7-blended-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/e/mellow.png', 'Erfaringen fortæller os, at efter syv års aldring, er rommen optimalt til opnåelse af velafbalancerede rom, det ideelle udgangspunkt i Oceans perfekt balance serie. I serien finder man 3 forskellige 7 års rom: Mellow, Tasty og Deep. Mellow kan oversættes "blød", denne rom har lys karakter og fyldig afslutning.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum, Limited Edition Sauternes Cask Finish Rum 46%', 'https://www.uhrskov-vine.dk/rammstein-rum-limited-edition-sauternes', 629, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/rammsteinsaut.png', 'Denne Rammstein rom er en unik blanding af tropiske rom lagret op til 12 år. Denne begrænsede udgave blev lagret i 39 måneder på ex-Sauternesfade. Resultatet er en perfekt afbalanceret rom med delikate noter af tropiske frugt, vanilje og karamel fra fadene Denne udgave er begrænset til 5.800 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 6 år Mauritius Triple Cask Rum, 43%', 'https://www.uhrskov-vine.dk/rum-nation-6-aar-mauritius-triple-cask-rum', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/mauritius.png', 'Denne rom er lagret på tre forskellige fade, under den varme mauritiske sol. Den er fremstillet med præcision, balance og kompleksitet. Destilleret i Mauritius, færdiggjort i Danmark, og lagret i seks år på tre forskellige fadtyper: Virgin Oak fra 2016, ex-Bourbon fra 2017 og Sherry fra 2019. Hvert fad bidrager med sin egen karakter - jordnær dybde fra egtræet, fyldig sødme fra bourbonfadet og et lag af elegant frugtighed fra sherryfadet. Denne begrænsede udgivelse, i ét parti, er en dristig, men raffineret rom, der tilbyder et levende samspil mellem tropisk lethed, cremet tekstur og varme krydderier. Rum Nation blev grundlagt af italieneren Fabio Rossi i 1999. Ideen bag var at finde frem til hvert enkelte lands særlige romstil. Det førte til et mangeårigt eventyr der ledte Rossi fra små peruvianske destillerier til rom- og insektmuseer i Guadelope. I kataloget finder man blandt andet kendte romnationer som Jamaica og Barbados, men man finder også lande, der hidtil har været totalt ukendte på det internationale marked - som eksempelvis Peru og Bougainville. Den færdiglagrede rom købes fra udvalgte destillerier verden over, og bringes dernæst her til Danmark, hvor den aftappes og blendes. Hovedfokus er ophavslandets udtryk og stil, og derfor oplyses det heller ikke nødvendigvis, hvilket destilleri, aftapningen kommer fra. Et gennemløbende motiv er, at flaskerne markeres med et frimærke fra ophavslandet. Mange års erfaring og forskning - samt en streng udvælgelsesproces - har skabt et stort udvalg af ”single rom”, der, tro mod rommens hjerte, er unik og uforglemmelig! Duft Røde bær og bløde vinnoter med et strejf af ahornsirup, frisk egetræ og sherry-løftet citrus. Smag Fløjlsblød og fyldig, blandet med læder, eg, bourbonvarme, tropiske frugter og ristet appelsinskal. Eftersmag Blød og let tropisk, med en pikant-sød eftersmag, der inviterer til endnu en slurk.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Rum Latino Venezuela 4 års Bourbon Cask 40%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-latino-venezuela-4-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50640556-cdi-latino---rum-from-molasses---venezuela.jpg', 'Compagnie des Indes Latino Venezuela 4 Year Old Rum er en venezuelansk molasse-rom fra det franske mærke Compagnie des Indes. Den er kolonnedestilleret og har modnet i omkring fire år på amerikanske ex-bourbon-fade under tropiske forhold, hvilket giver den en blød og velafbalanceret profil. Rommen har en gylden nuance, og duften byder på delikate noter af vanilje, praliné og let træ, mens smagen er rund og silkeagtig med hints af kokos, mandel, saltet karamel og vaniljetræ. Den kan nydes både ren og i cocktails.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Rum Jamaica Navy Strength 4 års 57%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-rum-jamaica-navy-strength-4', 399, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaicans.png', 'Compagnie Des Indes Jamaica Navy Strength 4 Year Old Rum er en intens jamaicansk rom i klassisk Navy Strength-udgave fra det franske hus Compagnie des Indes. Den består af et blend af jamaicansk rom destilleret både på pot still og kolonneapparat og har modnet i omkring fire år på amerikanske ex-bourbonfade, hvilket giver en dyb og karakterfuld smagsprofil. Rommen er tappet ved 57 % alkohol, som følger den traditionelle Navy Strength-standard og sikrer en kraftig og fyldig oplevelse. Duften rummer tydelige noter af moden banan, frisk sukkerrør og kandiseret frugt med et strejf af praline. Smagen er rig og afrundet med nuancer af flambéeret banan, ananas og et diskret præg af chokolade. Den kan nydes rent for fuld intensitet eller bruges i cocktails, hvor dens markante aroma virkelig træder frem.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s Night Watch Black Strap Rum 40%', 'https://www.uhrskov-vine.dk/pussers-night-watch-black-strap-rum-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/blackstrap.png', 'Pusser’s Night Watch Black Strap Rum er en dyb og karakterfuld rom med rødder i den britiske flådes historiske romtradition. Den er lavet på mørk Louisiana blackstrap-melasse og blended med lagret rom fra Guyanas ikoniske træ-pot stills, hvilket giver en kraftig og kompleks stil. Duften byder på mørk melasse, karamel og tørrede frugter, mens smagen folder sig ud med noter af toffee, kaffe, lakrids og varme krydderier. Eftersmagen er lang, fyldig og let sødmefuld fra melassen. En intens rom, der fungerer lige godt rent, over is eller som base i fyldige romcocktails.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Dominicana 8 års Rom 40%', 'https://www.uhrskov-vine.dk/rum-nation-dominicana-8-rom-40', 369, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dominicana.png', 'En sprudlende 8-årig rom fra den Dominikanske Republik, lavet på frisk sukkerrørssaft. Rommen kommer fra et moderne og økobevidst destilleri øst for Santo Domingo. Selvom rommen teknisk set er i den Spanske stilart, er den mere kompleks og mørk end de fleste andre spanske rom, hvilket skyldes at den er lavet direkte på sukkerrørssaften, hvor spansk rom typisk laves på sukkerrørsmelasse. En kompleks og dog letdrikkelig rom med en underspillet sødme som er velegnet til desserten eller som en aftendram!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barceló IMPERIAL Premium Blend Rum 38%', 'https://www.uhrskov-vine.dk/ron-barcelo-imperial-premium-38', 269, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barceloimperial1_2.png', 'En særlig blanding af Barceló Imperial''s tidligere reserver, modnet i udvalgte stykker af amerikansk og fransk egetræsfade, begge med forskellige grader af ristning; efterfølgende hvilende i europæiske tanke. Fyrre år dedikeret til at bevare kvalitetstraditionen af Barceló-rom. En gave til dem, der virkelig sætter pris på smagen af en fin kvalitetsrom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum, Limited Edition Limoux Cask Finish Rum 46%', 'https://www.uhrskov-vine.dk/rammstein-rum-lmt-edt-limoux-rum-46', 629, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/i/limoux.png', 'Denne Rammstein rom er en unik blanding af tropiske rom lagret op til 12 år. Denne begrænsede udgave blev lagret i 28 måneder på ex-Limouxfade. Resultatet er en frugtagtig rom med elegante noter af sprøde æbler, druer og vanilje fra fadene. Denne udgave er begrænset til 6.100 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rum 15 år Panama 40%', 'https://www.uhrskov-vine.dk/malteco-rum-15-panama-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco15.png', 'Malteco Ron Anejo 15 Años – Reserva Maya 41,5%, er en 15 år gammel rom, Rommen er i en let krydret, elegant stil, og den har en flot balance og sødme samt hints af krydderier. Malteco 15 år er destilleret på fermenteret sukkerrørsjuice og er således ikke lavet på melasse, som rom ofte produceres på. Dette gør, at Malteco 15 års basisprodukt ikke har de typiske noter af krydret anis og brun farin, men er mere let i stilen og mere påvirkelig af fadlagring.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Privateer 2017, Villa Paradisetto 54,2% (Velier)', 'https://www.uhrskov-vine.dk/privateer-2017-villa-paradisetto-velier', 1499, TRUE, NULL, 54.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/privateer_1.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Sassafras Single Blended Rum, Velier 61%', 'https://www.uhrskov-vine.dk/velier-foursquare-sassafras-70-61', 3495, TRUE, NULL, 61, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/9/0/90601066.jpg', 'Ny limited edition fra Foursquare - Velier. Kun 6000 flasker er tilgængelige over hele verden. Sassafras er den syvende udgivelse, gennem partnerskabet mellem Luca Gargano og Richard Seale, der startede i 2016. Destilleret i 2006 og derefter lagret i 14 år under den caribiske sol - Tre år i ex-bourbon tønder og 11 år i ex-cognac tønder. Sassafras er aftappet med fadstyrke og er en værdig repræsentant for Foursquares metoder og principper.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Samaroli 1998 Cask No 56 Demerara 2016 Edition Rom 45%', 'https://www.uhrskov-vine.dk/samaroli-1998-cask-no-56-demerara-2016-edition-45', 1495, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/samaroli.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin 2017 Ansyen Single Cask Daniel Seehuusen 48,5%', 'https://www.uhrskov-vine.dk/clairin-2017-ansyen-single-cask-daniel-seehussen-48-5', 599, TRUE, NULL, 48.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairindanielseehuusen.png', 'Denne Clairin Ansyen er et sjældent eksempel på en fadlagret udgave af den haitianske landbrugsrom,  Clairin.  Den er destilleret af Fritz Vaval på Arrawaks-destilleriet i Cavaillon og er lagret 16 måneder på et fad, der tidligere har indeholdt kult-rommen Caroni! Lige netop denne Clairin er udvalgt af bartenderen Daniel Seehuusen. Rommen er tappet ved fadstyrke (48,5%) og selvfølgelig uden tilsat farve eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Providence 2021 Dunder & Syrup Haitian White Rum, 56%', 'https://www.uhrskov-vine.dk/providence-dunder-syrup-haitin-white-rum-56', 499, TRUE, NULL, 56, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/providence.png', 'Nose : both refined and concentrated. The first nose is characterized by notes of red fruits (cherry and wild strawberry) and also gently peppery and lemony. Allowed to breathe, it reveals fragrances of an especially floral cane juice (purple lilac, bougainvillea). The deliciously honeyed aroma palette (lavender, geranium) gradually becomes finely liquorice and mineral (basalt, schist). Palate : full-bodied, dynamic. The divinely apricot attack is also creamy and rich (vanilla flan, raspberry cream cake). On the mid-palate, strong spices (nutmeg, clove), artichoke heart and crisp cherry create an extremely flavourful sequence of flavours. The hues found on the end of the palate rest for a long time on the cherries’ bright-red colour. Overall : long, fresh. At the start of the finish, a delicious cane syrup releases its sweet and floral flavours on the palate. The end of the finish is characterized by notes of cinnamon, fresh coriander and macadamia. The deliciously vanilla retro-nasal olfaction returns to the floral tones (carnation, phlox, hyacinth) of a rich yet subtle spirit. The empty glass is mentholated as well as floral (vine flower, lily of the valley) and fruity (peach, apricot, cherry)', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Takamaka 2021 Seychelles White Pure Single Rum 56%', 'https://www.uhrskov-vine.dk/habitation-velier-takamaka-2021-seychelles-white-rum-56', 799, TRUE, NULL, 56, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/a/takamaka.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Beach House, Pink Spiced 70cl 40%', 'https://www.uhrskov-vine.dk/beach-house-pink-spiced-70cl-40', 299, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/i/pinkspiced.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Arcane Extraroma Rum, 40% 70cl', 'https://www.uhrskov-vine.dk/arcane-extraroma-rum-40-70', 399, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/x/extraoma.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 10, Barbados 19 års Rum, 50,7%, RomDeluxe', 'https://www.uhrskov-vine.dk/barbados-19-collectors-series-rum-no-10-romdeluxe-50-7', 1399, TRUE, NULL, 50.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barba19.png', 'Her kommer den 10.ende aftapning i Collectors serien, som jo er et lille jubilæum. Derfor besluttede vi at det skulle være noget ekstra spændende. Vi har fundet noget virkelig gammel Foursquare. Hele 19 år gammel, men samtidig med den mest vidunderlige lyse gyldne farve, hvilket er lidt specielt, da forusquare plejer at være mørkere. Det skyldes at den har lagret størstedelen af sit liv i det kontinentale klima. Hvilket har givet rommen et lidt blødere og mildere udtryk. Noget vi var helt vilde med da vi smagte den. Der er noter af Kokos, vanilje, lidt chokolade, krydderier og på bagkanten nogle fine trænoter. Når man møder rom fra Foursquare, ved man på forhånd at det er rom f meget høj kvalitet, uden tilsætning af sukker eller farvestoffer. Så her får man præcis den rom som Richard Seale og hans team har tiltænkt den skulle være.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Isautier 15 Year Old 2022 Small Batch Rum, 57%', 'https://www.uhrskov-vine.dk/isautier-15-2022-small-batch-rum-57', 1349, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/s/isautier.png', 'Rommen fra det lille destilleri Isautier er ikke en man støder på så tit herhjemme, men nu har Velier hevet en gammel og spændende sag op fra de fugtige kældre i La Reunion. Denne 15 år gamle rom er lavet på melasse (Isautier laver også agricole) og lagret på 3 forskellige slags fade: virgin oak fra 2007 til 2009, ex-cognacfade fra 2009-2019 og fra 2019 til 2021 på ex-romfade. Den er tappet ved 57%, og det findes kun 991 eksemplarer på verdensplan! Farve : Rav. Duft : Dybe, frugtige noter af abrikos, fersken og karamelliseret rørsukker. Smagsnoter : Karamel, blodappelsin, grape, kaffe og urter. Serveringsforslag : Bør nydes rent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Sovereignty 14 Års Exceptional Cask Single Blended Rum 62%', 'https://www.uhrskov-vine.dk/foursquare-sovereignty-14-aars-single-blended-rum-62', 1495, TRUE, NULL, 62, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/o/sove.png', 'En blanding af rum destilleret i kobber dobbelt retort pot stills og den kontinuerlige kolonne distillat på Foursquare på Barbados, som har været lagret i i alt 14 år på ex-bourbon- og ex-sherryfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 5 2007 Barbados Rum, 58%', 'https://www.uhrskov-vine.dk/plantation-extreme-5-2007-barbados-rum-58', 2395, TRUE, NULL, 58, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/x/extremeseriesv_barbados2007_70cl_eu_box.png', 'West Indies Rum Distillery', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Transcontinental Rum Line 4 år Guadeloupe 2014 43%', 'https://www.uhrskov-vine.dk/transcontinental-4yo-guadeloupe-2014', 649, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/transcontinental-3yo-guadeloupe-2014_2_2.jpg', 'Guadeloupe fra Transcontinental Rum Line er den tiende. Rommen er reduceret til 43% alkohol, det er den styrke man mener denne rom udtrykker sig bedst. Rommen er lavet fra melasse, og er destilleret og lagret næsten 3 år i det franske øhavs-område. Denne udgivelse har lagret yderligere nogle måneder i europa.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Tres Hombres 2017 Edition 19, 23 år La Isla Bonita, Canarias 58% 100cl', 'https://www.uhrskov-vine.dk/tres-hombres-23yo-la-isla-bonita', 1995, TRUE, 100, 58, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/tres-hombres-23yo-la-isla-bonita_1.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 14, Barbados 17 års Rum, 57,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-14-barbados-17-57-9-rom-deluxe', 1169, TRUE, NULL, 57.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbados14_boks.jpg', 'Foursquare 2005.  Denne rom er en enkeltfadsaftapning som har lagret hele 17 år i et gammel frønnet Ex Bourbon fad. den har lagret nogle få år i troperne og resten af tiden kontinentalt. Det er en rom fra det navnkundige Foursquare destilleri på Barbados, hvor Richard Seale kreerer nogle ret fantastiske rom i en meget høj kvalitet. I denne aftapning får man en rom med karakter og masser af smag af peber, chokolade, karamel, vanilje, nødder og en smooth finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Jamaica 1998 Denmark Single Cask Rum 45,2%', 'https://www.uhrskov-vine.dk/plantation-jamaica-1998-denmark-single-cask-rum-45-2', 1749, TRUE, NULL, 45.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50641277-plantation-jamaica-1998-denmark.jpg', 'Fadlagring: Bourbon cask Fadlagring: Ferrand cask Fadlagring: Sauternes cask Produkttype: Rom Alkohol %: 45,2 Årgang: 1998', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Master Blender''s Reserve 2022 Edition Rum, 54,5%', 'https://www.uhrskov-vine.dk/black-tot-master-blender-reserve-2022-rum-54-5', 1495, TRUE, NULL, 54.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/black-tot-master-blender_s-reserve--2022_1.jpg', 'Næse Smeltede chokoladenibs, ristede hasselnødder står over for varme appelsin- og kanelstænger med en baggrund af blandet tropisk juice og cassis. Solbær og hindbærblade begynder at træde i forgrunden med tiden i glasset. Mund Indledende smag af mælkechokolade og rosiner suppleres af café latte og moden banan. Et strejf af anis balancerer mod et let strejf af tropiske frugter og en vidunderlig fyldig bagt demerarasukker på toppen af en creme karamel. Finish Kanel og muskatnød krydderier sammen med chili og kakao hænger ved i en rum tid.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('English Harbour Reserve 10 Year Old Rum, 40%', 'https://www.uhrskov-vine.dk/english-harbour-10-rom-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/harbour10.png', 'English Harbour Reserve 10 Year Old Rum er en blanding af moden rom, hvoraf den yngste er 10 år gammel. En blanding af 10 år gammel rom, hvor den yngste rom er lagret på 1.fill Kentucky bourbonfade i minimum 10 år.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Providence 2019 Haitian Pure Single Rum 52%', 'https://www.uhrskov-vine.dk/providence-2019-haitian-pure-single-rum-52', 999, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/providence19.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 40 Australia 15 års Single Cask 67%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-40-australia-15-single-cask-67', 1169, TRUE, NULL, 67, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws40australia.jpg', 'Så er den her endelig. Rommen fra Australske BeenLeigh, som har gjort sig fortjent til at blive medlem af vores Wild Series. BeenLeigh er et af Australiens største destillerier, og har gennem de seneste år fået stor opmærksomhed og anerkendelse for deres rom. Denne aftapning er baseret på molasse, og har lagret 10 år i australien, inden den blev flyttet til Europa, for yderligere 5 års lagring. Den er lagret i ex. bourbon fade i hele dens lagringstid. Den er tappet uden filtrering for at sikre den bedste smag. Smagsnoterne i denne lækre aftapning er noter af krydderier, egetræ, molasse, karamel og et strejf af citrus.   Fakta Australia Single cask                                                                                              Distilled Aug. 2007 At Beenleigh  Distillery Bottled Jan. 2023 Marque MAIC10 Aged in Ex. Bourbon cask Tropical and Continentally aged Barrel No. 25 259 bottles Cask Strength at 67% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Old Jamaica Rum 26 år 1982 Vintage Rum Robert Watsons Ltd. 48%', 'https://www.uhrskov-vine.dk/old-jamaica-rum-26-years-old-1982-vintage-rum-robert-watsons-ltd-48', 4985, TRUE, NULL, 48, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaica-rum-26yo-1982_2_1.jpg', 'Old Jamaica Rum 26 Years Old 1982 Vintage Rum Robert Watsons Ltd. 48% Meget få romfade får lov at modne og udvikle sig så længe, som de fade hvorfra denne rom er aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau 10 År Rhum Vieux Agricole 42%', 'https://www.uhrskov-vine.dk/damoiseau-rhum-vieux-10-ar-42', 650, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/damoiseau-vieux-10_2.jpg', 'Damoiseau familien, ejere af Bellevue destilleriet i Moule, Guadeloupe, er udviklet i traditionen tro fra landbrugets høje rom kvalitet. Damoiseau er den ubestridte leder i Guadeloupe rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Long Pond 1982 Juuls Flight No.11 Flying Jamaica Rum 61,6%', 'https://www.uhrskov-vine.dk/jamaica-1982-flying-no-11-rom-61-6', 12500, TRUE, NULL, 61.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/l/flying-jamaica-1982_2.jpg', 'Denne 30 års Flying Jamaica single cask er aftappet i 2013 udvalgt af Juuls Vin & Spritis. Aftappet fra en bourbon tønde, med kun 186 flasker af dette fad. Duft: Intens krydret og varm duft af stjerneanis, kryddernellike, banan, sirup, vanilje, egetræ og teblade. Smag: Fantastisk fed og olieretmundfuld, med perfekt afstemt karakter af rørsukkersødme, engelsk lakrids, mentol, eksotiske røde bær og frugter. Helt sikkert en ekstrem rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Monymusk MMW Wedderburn Continental Aging 11 år, Jamaica 63,9% (Velier)', 'https://www.uhrskov-vine.dk/momymusk-continental-aging-11-jamaica-63', 999, TRUE, NULL, 63.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/1/1/11ans-mmw-continental-aging-wedderburn.jpg', '100 Pot Still Continental Aging. A blend of 2 casks of MMV 2008, and 10 casks of MMV 2007, totally aged in Jamaica. Jamaica Vatted Single Rum. A joint bottling between E&A Scheer Amsterdam and Velier, Genoa. Esters: 243,5gr/hlpa Det er et velkendt fænomen i spiritusverdenen, at det klima, hvor spiritussen lagres, har stor indflydelse på smagen. Nu får vi, for første gang nogensinde, en release hvor der sættes fokus på netop dette!  Eksperimentet er opstået i et yderst sjældent samarbejde mellem italienske Velier og E&A Scheer i Amsterdam, og de har sammen tappet fire forskellige rom i to ”sæt”. Rommene kommer alle fra samme destilleri, Monymusk, men er lagret henholdsvis ”kontinentalt” og ”tropisk” – og der er store forskelle!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Seleccion 1982 Rum, 40%', 'https://www.uhrskov-vine.dk/malteco-rom-seleccion-1982-40', 1695, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco1982.png', 'Selvom Malteco Ron er en Guatemala-stilet rom, er det egentlig en panamansk rom, som produceres af Varela Hermanos Bodegas de America SA. Opskriften er lavet i Guatemala, hvor Malteco Ron originalt blev produceret. Opskriften er fra Guatemala, og rommen bliver løbende kvalitetskontrolleret af ‘Asociacion Maestros Roneros de Guatemala’.Varela Hermanos ligger i byen Pesé i den sydlige del af det centrale Panama. I 1908 etablerede den daværende ejer, Don José Varela Blanco, den første sukkerfabrik. Senere, i 1936, åbnede romfabrikken, som lige siden har produceret rom af høj kvalitet.Varela Hermanos er den største leverandør af rom til hjemmemarkedet i Panama, og leverer mere end 90% af al rom til de lokale. Rommen er destilleret på kolonne-kedler og er derfor i den elegante, lette stil, hvilket også er kendetegnede for rom fra Guatemala. Rommen bliver lagret på 220 liters brugte bourbonfade af hvid, amerikansk eg. Tønderne giver rommen en passende kontakt med fadet, hvor mindre tønder ville give for meget kontakt og større tønder for lidt.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton 2002 Hearts Collection Single Estate Rum, Jamaica 63%', 'https://www.uhrskov-vine.dk/appleton-2002-hearts-single-estate-rum-63', 1995, TRUE, NULL, 63, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/p/appleton2002_1.png', 'Appleton Estate 2002 Hearts Collection er en del af en samling af rom, skabt af Appleton Estate''s anerkendte master blender Joy Spence og Veliers Luca Gargano. Hearts Collection blev skabt for at fremvise enkelt-marque rom destilleret med en Forsyth pot still i hjertet af Jamaica. Denne 2002-årgang blev blandet fra 20 fade, der blev udvalgt blandt de 200.000 i destilleriets kældre og lagret i mindst 20 år, for at skabe 5.700 flasker. Resultatet er en rom, som byder på rig melasse og appelsinskal med delikat varm vanilje, mediumristet kaffe og karamel med en lækker honning-blød afslutning.  Bemærk: Max. 1 flaske pr. kunde, da Appleton Estate 2002 Hearts Collection er en meget begrænset udgivelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin Jamaica TECC White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-jamaica-tecc-white-rum-57', 499, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbsjamaicatecc.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. This bottling contains a wonderful white rum distilled in traditional column stills making great Daiquiris. Tasting Notes: Nose:  Very intense and funky notes of tropical fruits and sugar cane juice. Palate:  Funky tropical and spicy flavors with a long rummy sweet finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin Dominican Republic Aroma Grande White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-dominican-republic-aroma-grande-57', 379, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/r/aromagrande.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. This bottling contains a wonderful white rum distilled in traditional column stills making great Daiquiris. Tasting Notes Nose : Acetone, hints of white pepper and dried flowers. Lots of citrus peel with heavy notes of grapefruit. Palate : Again citrus forward – lots of lemon peel. Marzipan and somewhat floral with hints of lavender. Oily and smooth mouthfeel with long dry finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin French Antilles Grand Arome White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-french-antilles-grand-arome-57', 499, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/n/antillesgrandarome.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. Tasting Notes Nose : Fruity and grassy with notes of ripe oranges, fresh sugar cane, eucalyptus and a hint of tart citrus fruits. Palate : Spicy and dry with notes of ground pepper and fermented stone fruits.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin Guyana PM White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-guyana-pm-57', 409, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guyamapm.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. This bottling contains a fantastic white rum produced in double wooden pot stills. Tasting Notes Nose : Interesting spicy and salty notes with a touch of dried dates and roasted corn. Palate : Surprisingly mild, sweet and chewy with notes of flambéed marshmellows, cotton candy and fine bitterness in the finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Origin Jamaica TECA White Rum, 57%', 'https://www.uhrskov-vine.dk/sbs-origin-jamaica-teca-white-rum-57', 479, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaicateca.png', 'The 1423 S.B.S Origin Selection is a series of handpicked unaged rum specifically chosen for their powerful profile and flavor. The chosen rum and marks are well known from our aged 1423 Single Barrel Selection and we now offer the opportunity to taste the origin of our products in our 1423 S.B.S Origin Selection. Enjoy them neat, on the rocks or to elevate your cocktails. This bottling contains a splendid heavy pot still white rum from Jamaica with an ester level of 1200-1300 gr/hL, hence marked TECA. Tasting Notes Nose : Punchy at first, developing into notes of tropical fruits and flowers with a hint of burnt sugar. Palate : Peppery with lush aromas of tropical fruits like papaya. A sweet touch of honey and slightly burnt notes in the finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana 2007 Teeling Whisky Cask Finish Rum, 53,7%', 'https://www.uhrskov-vine.dk/plantation-guyana-2007-teeling-whisky-cask-rum-53-7', 799, TRUE, NULL, 53.7, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', '13 år på bourbonfade i troperne, 1 år på cognac-fade i Frankrig og 7 måneder på et irsk whiskey-fad. Det er opskriften på denne fantastiske limited edition-aftapning fra Plantation Rum. Udgangspunktet er en stovt og kraftig rom fra Guyana, destilleret på pot still i 2007. Vi er glade for, at vi fik lov at tappe denne rom udelukkende til Juuls, for den smager simpelthen fantastisk! 53,6% alkohol og nul tilsat sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Adelphi Diamond 2010 13 år, Single Estate Guyana Rum 61,3%', 'https://www.uhrskov-vine.dk/adelphi-diamond-13-aar-guyana-rum-61-3', 899, TRUE, NULL, 61.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/d/adelphidiamond.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Alegre, Seleccion de Familia XO 40%', 'https://www.uhrskov-vine.dk/ron-alegre-xo-40', 485, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ronaelgrexo.png', 'Ron Alegre XO er en rom fra Den Dominikanske Republik. Den har tilbragt intet mindre end 10 år på fade af amerikansk eg, der inden da har indeholdt vores yndlingshedvin, sherry. Fra sherryen får Alegre de lækre noter af tørret frugt og mørk karamel. Det er en rom med den perfekte blanding af modenhed, sødme og friskhed, hvilket hurtigt har gjort den til en favorit hos os.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Caroni 1997 25 års Single Cask Trinidad Rum, Adelphi 58,8%', 'https://www.uhrskov-vine.dk/caroni-1997-25-single-cask-trinidad-rum-adelphi-58-8', 4995, TRUE, 70, 58.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/d/adelphicaroni.png', 'Caroni 1997/2023 Adelphi Limited 25 år Single Cask Trinidad Rom 70 cl 56,8% Caroni 25 års rom i serien Adelphi Limited. Denne rom er en Single Cask Trinidad Rom som er aftappet ved 56,8% og har lagret på et brugt Hogshead fad #25 med kun 204 flasker til hele verden.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom Elixir de Ron 32%, 50cl', 'https://www.uhrskov-vine.dk/ron-patridom-elixir-de-ron-32-50', 195, TRUE, 50, 32, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/elixirderon.png', 'Patridom Elixir de Ron er en premium romlikør lavet af frisk sukkerrørsjuice, som modnes i det tropiske klima i Den Dominikanske Republik. Basen for denne romlikør er en fem år gammel rom lagret på både amerikanske og franske egetræsfade, inden den blandes og tilsættes naturlige smagsnuancer af kokos, appelsin, chokolade og citron samt rørsukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum, Limited Edition Cognac Cask Finish Rum 46%', 'https://www.uhrskov-vine.dk/rammstein-rum-lmt-edt-cognac-46', 629, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/rammsteincognac.png', 'Denne Rammstein rom er en unik blanding af tropiske rom lagret op til 12 år. Denne begrænsede udgave blev lagret i tolv måneder på ex-Cognacfade. Resultatet er en perfekt afbalanceret rom med delikate noter af tropiske frugt, vanilje og karamel fra fadene Denne udgave er begrænset til 5.800 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Islay Cask Finish 44%', 'https://www.uhrskov-vine.dk/ron-patridom-islay-cask-finish-44', 595, TRUE, NULL, 44, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomislay.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium rom fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave med Islay Cask Finish har derudover gennemgået en ekstra lagring i ex-Islay whiskyfade, hvilket tilføjer rommen en røget note. Patridom XO Islay Cask Finish er blevet aftappet i august 2022 med et resultat på 1886 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Limoux Cask Finish 43%', 'https://www.uhrskov-vine.dk/patridom-xo-limoux-cask-finish-43', 595, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomlimoux.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium rom fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave med Limoux Cask Finish har derudover gennemgået en ekstra lagring i ex-Limouxade, hvilket tilføjer rommen en frugtagtig note. Patridom XO Cognac Cask Finish er blevet aftappet i juli 2023 med et resultat på 1949 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Origen Thailand 12 år 47%', 'https://www.uhrskov-vine.dk/dos-maderas-origen-thailand-12-yo-47', 599, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmaderasorigen.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Panamonte 12 års Single Estate Panama Rum 40%', 'https://www.uhrskov-vine.dk/panamonte-12-single-estate-40', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/panamonte.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Terra Verde Twin Cask Rum 40%', 'https://www.uhrskov-vine.dk/terra-verde-twin-cask-rum-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/w/twincask.png', 'Terra Verde Twin Cask er fortællingen om en rom fra Den Dominikanske Republik, lagret i minimum fire år på bourbonfade og efterfølgende finish’et på oloroso sherryfade. Denne lagring giver rommen en smuk dybde, elegant kompleksitet og en flot, naturlig farve. En rund og tilgængelig rom, der gør sig særligt godt i cocktails og drinks, hvor der ønskes en mørkere romprofil. Rommen er let sødet med 15 g sukker pr. liter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Pacifico Panama & Thailand 6 års 42,5%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-pacifico-panama-thailand-6-425', 399, TRUE, NULL, 42.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/pacifico.png', 'Compagnie des Indes Pacifico Panama & Thailand 6 Year Old Rum er en melassebaseret rom, destilleret på kolonneapparat og skabt som et harmonisk blend af lagret rom fra Panama og Thailand. De to oprindelser deler en blød og aromatisk stil med et strejf af krydderi, og rommene i blendet har modnet i cirka 6 til 12 år, hvilket giver kompleksitet og en flot balance i det færdige udtryk. Aromaen er fyldig og indbydende med noter af karamel, praliné, kandiseret appelsin og fine blomsteragtige nuancer. I munden fremstår den rund og smagsintens med toner af lakrids, eukalyptus og chokolade, afrundet af et diskret krydret præg af muskat. Afslutningen er lang og elegant, hvilket gør rommen velegnet både til at nyde rent og som et eksklusivt element i cocktails.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Indomitas 15 års Single Blended Rum, Foursquare / Velier 62%', 'https://www.uhrskov-vine.dk/foursquare-indomitas-15-sbr-62', 1795, TRUE, NULL, 62, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/n/indomitas.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairmans Reserve 2011 Finest St. Lucia Rum 46,80%', 'https://www.uhrskov-vine.dk/chairman-reserve-2011-finest-rum-46-80', 649, TRUE, NULL, 46.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/h/chairman2011.png', 'Top-aftapningen hos Chairman''s Reserve er en vintage rom, der frigives løbende. Den nuværende årgang hedder 2011, og rommen repræsenterer alt det, vi godt kan lide ved St. Lucia: power, kompleksitet, dybde og typicitet. De laver bare ikke rom, som det her, andre steder... Rommen er lagret på bourbonfade ved destilleriet og er tappet ved 46,8% uden tilsat sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Guyana 2004 Small Batch Old Guyana Rum 50%', 'https://www.uhrskov-vine.dk/velier-guyana-2004-small-batch-50', 3785, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guyana20024.png', 'Der findes næppe mere sagnomspunden rom, end de gamle Guyana-aftapninger fra Velier, som blev frigivet med jævne mellemrum fra 2005. Der har dog været decideret tørke på Guyana-fronten fra Velier i en længere periode, så stemningen var nærmest euforisk blandt romsamlere da Velier endnu engang frigav en tropisk lagret Guyana-rom i starten af 2026, og nu er den danske allokation landet! Rommen er en blanding af 3 forskellige rom (derfor navnet Small Batch), hvoraf den yngste bestanddel er fra 2004. Der er frigivet 2.907 flasker på verdensplan.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s British Navy Rum 40%', 'https://www.uhrskov-vine.dk/pusser-british-navy-rum-40', 319, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/pusser1.png', 'Pusser’s British Navy Rum Blue Label, er en rom, der er inspireret af den rom som alle flådeansatte fik i deres dagsration op til 31 Juli 1970 (kendt som Black Tot Day). Denne version af rommen er på 40% modsat det original navy rom, der var markant stærkere med dens flådestyrke på omkring de 57%. Denne version er vandet ned, da lovkrav gjorde at hvis den skulle distribueres til flådebaser, måtte den maksimum være 40%. Rommen har en klar, men mørk farve, og er nok noget af det tætteste, kommercielle rom, man kommer på det som de fik på skibene. (Udover storebroderen på 54,5%)', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s Select Aged 151 Navy Strength Rum 75,5%', 'https://www.uhrskov-vine.dk/pusser-select-151-ns-rum-75-5', 465, TRUE, NULL, 75.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/pusser151.png', 'Pusser’s British Navy Rum Selected Aged 151 på 75,5%, er en rom, der er inspireret af den rom som alle sømænd i ”The British Navy” fik i deres dagsration fra midt 1600, helt op til 31 Juli 1970 (kendt som Black Tot Day).  En fremragende rom fra Demerara Distillery i British Guyana, der er ”magen” til den rom, der leveredes i de gode gamle dage - den gang leveredes den i fadstyrke til Royal Navy værfterne i Deptford, Gosport og Devonport. Der blev den fortyndet, via gennemførsel af ”%-beviset! Rommen må ikke have lavere alkoholhalt end at krudt stadig antænder, selvom en flaske rom blev hældt ud over det. Selected Aged 151 lagres i minimum tre år på 1st fill bourbon fade og produceres i overensstemmelse med det den gang gældende Admirality Regulations for rom. Indholdet er kølefiltreret for yderligere at forbedre dets smag og udtryk. På grund af sin høje styrke er Pusser''s 151 meget potent og anbefales ofte til at blande i cocktails (især dem, der kræver en højstyrke-rom, som en stærk Mai Tai eller en Flaming Volcano) eller fortyndet med vand eller en mixer. Den betragtes som en autentisk smag af flådens historie og har vundet adskillige priser for sin kvalitet. Pusser''s Rum er mere end blot en serie af rom; det er et mærke bygget på autentisk flådehistorie, der følger den præcise opskrift, som den britiske Royal Navy brugte til deres romrationer.  Pusser''s sortiment er relativt fokuseret, men tilbyder forskellige styrker og udtryk, der alle deler den samme rige, fyldige karakter fra de traditionelle træ-destillationsapparater i Guyana.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Volbeat XXV Limited Edition Rum 43%', 'https://www.uhrskov-vine.dk/volbeat-xxv-limited-edition-rum', 1349, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/o/volbeatxxv.png', 'Volbeat XXV Rum Limited Edition er skabt i anledning af Volbeats 25-års jubilæum – en mørk, gylden og kompromisløs rom, der samler bandets energi, attitude og historie i én eksklusiv flaske.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barceló Imperial Onyx Premium Blend Rum 38%', 'https://www.uhrskov-vine.dk/ron-barcelo-imperial-onyx-premium-38', 349, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barceloonyx.png', 'En særlig blanding af Barceló Imperial''s tidligere reserver, modnet i udvalgte stykker af amerikansk og fransk egetræsfade, begge med forskellige grader af ristning; efterfølgende hvilende i europæiske tanke. Fyrre år dedikeret til at bevare kvalitetstraditionen af Barceló-rom. En gave til dem, der virkelig sætter pris på smagen af en fin kvalitetsrom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Fanø Skibsrom, Søhesten 41,5% 70cl', 'https://www.uhrskov-vine.dk/fano-skibsrom-sohesten-41-5-70', 400, TRUE, 70, 41.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/a/fanosohesten.png', 'Destilleret på Jamaica og efterfølgende forædlet på Fanø. Forædlingen består af en to-trins-lagring. Lagres først med naturlige smagsgivere (bl.a. Fanø Lynghonning, havtorn og Madagaskar vanilje), hvorefter den efterlagres på portvinsfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Fanø Skibsrom, Havfruen 41,5% 70cl', 'https://www.uhrskov-vine.dk/fano-skibsrom-havfruen-41-5-70', 400, TRUE, 70, 41.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/havfruen.png', 'Destilleret på Jamica og efterfølgende forædlet på Fanø. Forædlingen består af en to-trins-lagring. Lagres først med naturlige smagsgivere (bl.a. Fanø Lynghonning, havtorn og Madagaskar vanilje), hvorefter den efterlagres på portvinsfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Fanø Skibsrom, Havmanden 41,5% 70cl', 'https://www.uhrskov-vine.dk/fano-skibsrom-havmanden-41-5-70', 400, TRUE, 70, 41.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/havmanden.png', 'Destilleret på Jamaica og efterfølgende forædlet på Fanø. Forædlingen består af en to-trins-lagring. Lagres først med naturlige smagsgivere (bl.a. Fanø Lynghonning, havtorn og Madagaskar vanilje), hvorefter den efterlagres på portvinsfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Fanø Skibsrom, Kaptajnen 43% 70cl', 'https://www.uhrskov-vine.dk/fano-skibsrom-kaptajnen-43-70', 750, TRUE, 70, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/a/kaptajnen.png', 'I anledning af Fanø Spirits grundlægger Lars J. Schous 80 års fødselsdag har vi som en hyldest lavet Fanø Skibsrom® Kaptajnen, som er krydret og lagret lige som han ville ønske det. Den har en alkoholprocent på 43% og smagsnoterne er kompleks og fyldig med noter af træ, tobak og lidt sødme .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2013 Foursquare Pure Single Rum 60%', 'https://www.uhrskov-vine.dk/habitation-velier-2013-foursquare-pure-single-rum-60', 1695, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/foursquare132.png', 'Foursquare Distillery blev grundlagt i 1996 af Richard Seale på Barbados og er kendt for at kombinere destillater fra både kolonne- og pot stills. Denne rom er dog en sjælden undtagelse: Destilleret udelukkende på pot still og uden nogen form for blending, hvilket giver et ekstraordinært koncentreret og komplekst udtryk med maksimal dybde og aromatisk intensitet. Allerede i 2015 viste en første udgave, lagret blot to år, potentialet i denne særlige stil. Denne aftapning er kulminationen på projektet med yderligere ti års tropisk lagring på tidligere 370-liters Cognac-fade. Fadenes cognacmættede træ har bidraget med en elegant kombination af frugtige og krydrede nuancer samt en raffineret fadkarakter. Smagsprofil: Elegant og silkeblød med noter af kandiseret abrikos, kakao og eksotiske krydderier.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2024 Rainforest Pure Single Rum 58%', 'https://www.uhrskov-vine.dk/habitation-velier-2024-rainforest-pure-single-rum-58', 795, TRUE, NULL, 58, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/rainforest242.png', 'Rainforest Distillers holder til i Bukidnon på øen Mindanao i det sydlige Filippinerne. Destilleriet blev grundlagt i 2015 af Master Distiller Marc Schulze, som også står bag Kasa Kaña Rum Agrikultura – en håndlavet agricole-rom fremstillet på traditionelle filippinske sukkerrørssorter. Rommen er produceret på den lokale Manpu-sukkerrørssort og gæret i 9-12 dage med tilsætning af dunder og muck, som udvikles og modnes i Bukidnons tropiske klima. Herefter destilleres rommen på pot still og lagres i 20 måneder på tidligere Chardonnay-fade midt i regnskoven. Resultatet er en karakterfuld rum med tydeligt ophav, stor aromatisk intensitet og masser af landlig autenticitet. Smagsnoter: Frisk - med noter af sukkerrørsjuice, tropiske frugter og grøn urteagtig friskhed.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica Long Pond STCE Vintage 1995 Juuls 100th Anniversary 52%', 'https://www.uhrskov-vine.dk/planteray-jamaica-long-pond-1995-juuls-100th-anni-52', 2579, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planterayprestige.png', 'Planteray Jamaica Long Pond STCE Vintage 1995 er en eksklusiv og kraftfuld jamaicansk pot still-rom, aftappet til 52 % som en særlig hyldest til Juuls Vin & Spiritus'' 100-års jubilæum. Rommen er destilleret på legendariske Long Pond Distillery på Jamaica og har gennemgået hele 31 års fadmodning – 23 år tropisk på bourbonfade efterfulgt af 8 år i Europa på Ferrand-fade. STCE-marken er kendt for sin høje esterintensitet og karakteristiske jamaicanske funk med noter af moden tropisk frugt, ananas, banan, krydderier, lakrids, kaffe og fad. En tør, intens og særdeles kompleks rom for den erfarne romentusiast.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cartavio X.O. 18 års Premium Rom 40%', 'https://www.uhrskov-vine.dk/cartavio-xo-18-premium-rom-40', 699, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/cartavio18.png', 'Verdens Bedste Rom" i både 2015 og 2016 ved San Francisco World Spirits Competition. I den frugtbare Chicama Valley på Perus nordkyst ligger Cartavio-destilleriet. Den geografiske placering er perfekt for høsten af sukkerørene, som man bruger i produktionen, samt det krystalklare og rene vand, der kommer rindende fra Andesbjergene. Men det er ikke blot dette, der gør Cartavio til én af verdens allerbedste rom. Peruvianerne udvælger også meget nøje de helt rigtige egetræsfade til de forskellige romblends. Her bruges både fransk, amerikansk og slovensk eg, inden man afslutter lagring og blending via Solera/Criaderas-metoden. Cartavio X.O. 18 y.o., 40%, 70 cls.: Vinder af Miami Rum Festival 2015 i kategorien Premium Aged Rums i konkurrence med verdens bedste lagrede rom. Cartavio X.O. har lagret på fade mellem 10 og 30 år, og gennemsnitsalderen er 18 år, når man foretager blended via Solera/Criadera-metoden. Rommen har også vundet talrige andre udmærkelser, herunder højeste udmærkelse, 2-guld i Fifty Best Aged Rums, med kommentaren ''Outstanding, perfect''.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s Founder''s Reserve Rum 47,5%', 'https://www.uhrskov-vine.dk/pusser-founder-reserve-47-5', 745, TRUE, NULL, 47.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/pusserfoundersreserve.png', 'En eksklusiv rom, der hylder Pusser''s stolte traditioner og den legendariske britiske flåderom. Denne limited edition byder på en fyldig og karakterfuld romoplevelse med en kompleks smagsprofil og en varm, langvarig finish. En spændende rom for både entusiaster og samlere, der sætter pris på autentisk Navy Rum, historisk håndværk og særlige romudgivelser. Perfekt til at nyde rent eller som en eksklusiv gave til romelskeren.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Fiji Islands Vintage Collection 2012 Oceana Limited Edition 45%', 'https://www.uhrskov-vine.dk/planteray-fiji-islands-2012-oceana-45', 599, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/i/fijiisl.png', 'Planteray Fiji Islands Vintage Collection 2012 Oceana Limited Edition 45% er en eksklusiv vintage rom fra Fiji, der byder på en spændende kombination af tropisk frugt, varme krydderier og elegante fadnoter. Denne limited edition rom fra Planteray er en del af den eftertragtede Vintage Collection og byder på en fyldig og kompleks smagsoplevelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mauritius Vintage Collection 2014 Oceana Limited Edition 50%', 'https://www.uhrskov-vine.dk/planteray-mauritius-vintage-collection-2014-oceana-50', 649, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/mauri.png', 'Planteray Mauritius Vintage Collection 2014 Oceana Limited Edition 50% er en eksklusiv vintage rom fra Mauritius i Det Indiske Ocean. Denne særlige limited edition rom byder på en fyldig og kompleks smagsoplevelse med nuancer af tropiske frugter, varme krydderier, vanilje og elegante fadnoter. Med en alkoholstyrke på 50% får du en intens og karakterfuld premium rom, der er ideel til både romkendere og entusiaster, som søger en unik romoplevelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Australia Vintage Collection 2016 Oceana Limited Edition 52%', 'https://www.uhrskov-vine.dk/planteray-australia-vintage-collection-2016-oceana-52', 679, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/u/austra.png', 'Planteray Australia Vintage Collection 2016 Oceana Limited Edition 52% er en eksklusiv årgangsrom fra Australien, der kombinerer intensitet, kompleksitet og masser af karakter. Denne limited edition rom fra Planterays Vintage Collection byder på en kraftfuld smagsoplevelse med nuancer af tropiske frugter, varme krydderier, vanilje og egetræ. Med en alkoholstyrke på 52% er Planteray Australia 2016 Oceana et spændende valg for romelskere, der søger en fyldig premium rom med en unik australsk oprindelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 12 år Trinidad Cask Strength Rum, 53,40%', 'https://www.uhrskov-vine.dk/rum-nation-12-trinidad-cask-str-rum-53-40', 599, TRUE, NULL, 53.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/s/csrumnationtrinidad.png', 'Født under den bagende Trinidad sol, blev denne rom efter få år transporteret til Europa, hvor den har modnet det meste af sit liv på bourbon tønder. Afslutningsvist har vi hos Rum Nation givet rommen en 12 måneders finish på brugte Oloroso sherryfade, hvilket så at sige har "tæmmet bæstet"... En kraftig rom, afrundet af et kulturkick fra Andalusien. En oplevelse udgivet i blot 1.469 flakser på verdensmarkedet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica ITP 2000 Ping 16 Long Pond Distillery, 58,40%', 'https://www.uhrskov-vine.dk/planteray-jamaica-itp-2000-long-pond-distillery-58-40', 2009, TRUE, NULL, 58.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planterayitp.png', 'Ping-familien får et nyt medlem! Gammel Jamaica-rom står vores hjerte meget nært, og da Planteray tilbød os dette ekstraordinære fad fra Long Pond anno 2000, var vi ret hurtige til at sige  merci beaucoup . Rommen er en såkaldt ITP, hvilket er en betegnelse, Long Pond giver rom der produceres med et esterindhold mellem 90-120 gram estere per hektoliter ren alkohol. Det tal kan dog godt stige under fadlagringen, og denne rom ligger på 219 g/hLAA og 1120 g/hLAA volatile compounds. Den har tilbragt 17 år på bourbonfad og 7 år på et Ferrand-fad. Tappet ved fadstyrke: 58,4%. Alle flasker er nummererede.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dos Maderas Atlantic Double Aged Rum 37,50%', 'https://www.uhrskov-vine.dk/dos-maderas-atlantic-double-aged-rum-37-50', 299, TRUE, NULL, 37.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dosmadatlantic.png', 'Dos Maderas Atlantic  er et blend af 5 årig rom fra Barbados og 5 årig rom fra Guyana. Efter sammenblanding er rommen blevet fragtet til William & Humberts bodega i Jerez i det sydlige Spanien, hvor den er lagret yderligere et år på gamle fade som tidligere har indeholdt sødmefuldt Pedro Ximenez sherry.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Centenario Solera 23 Gran Reserva 40%', 'https://www.uhrskov-vine.dk/ron-zacapa-centenario-23-sistema-solera-40', 429, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/z/a/zacapa1234.png', 'Verdens bedste Rom!? For sjette år i træk er Ron Zacapa Centenario huset kåret som verdens bedste rom, i kategorien Premium Category. Kåringen er sket ved Caribbian Week "Rumfest"/Rumfestival i 1998, 1999, 2000, 200, 2002 og 2003. Igen lykkedes det altså for Ron Zacapa Centenario at indtage de 40 smagsdommeres smag. Dommerne, samt de mange internationale gæster ved "RumFest" på Barbados deltog i den årlige kåring og vurdering af alverdens rom, som afholdes hvert år i januar.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Quorhum 30 Aniversario Solera Den Dominikanske Republik 40%', 'https://www.uhrskov-vine.dk/ron-quorhum-30-aniversario-solera-den-dominikanske-republik-40', 699, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-quorhum-30yo_2_1.jpg', 'Ron Quorhum 30 Aniversario Solera, lagret i bourbon fade. Denne luksuriøse spiritus fra den Dominikanske Republik har en fuld og afrundet smag af bourbon krydderi, mandler, sukkersødt eg og sød toffy fedme.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation 2019 Black Cask, Barbados & Jamaica Rom 40%', 'https://www.uhrskov-vine.dk/plantation-black-cask-rom-2019', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-black-cask-2019_1.jpg', 'Plantation Rum har lavet et nyt og meget spændende blend bestående af fyldig Pot Still rom fra Jamaica og blød sødmefuld rom fra Barbados. Rommen fra Jamaica er fyldig med frugtnoter, som ananas, banan og mango. Den blender perfekt sammen med den lettere Barbados rom, som kommer med noter af konfekt, kokos og orange.Det hele tilsat masser af kærlighed og lidt sødme, hvilket giver en hel unik Plantation Black Cask 2019 Edition.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Volbeat No. III Vol. 3 Super Premium Caribbean Rum 43%', 'https://www.uhrskov-vine.dk/volbeat-rom-vol-3', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/o/volbeat3.jpg', '”Da Volbeat tilbage i 2016 lancerede deres første rom ville det berømte band tilbyde deres dedikerede fans noget ud over det sædvanlige. Noget særligt - noget der stimulerede bandets egen påskønnelse af alle de elementer, der hører med til at producere alkohol. Det gav dem dermed også mulighed for at henvende sig til en helt ny gruppe mennesker, som ikke allerede var Volbeat-fans.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Détente Exceptional Cask 10 Års Single Blended Rum 51%', 'https://www.uhrskov-vine.dk/foursquare-10-aar-rum-detente-51', 995, TRUE, NULL, 51, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/foursquare_detente_rom_single_blended_rum_exceptional_cask_selection.jpg', 'Foursquare Détente Single Blended Rum  er en i serien exceptionelle Cask Selection-udgivelser fra Richard Seale og Foursquare Distillery - Tappet i 2020. Foursquare Rum er produceret af R.L. Seale, et af Barbados ældste handelshuse, en familieejet virksomhed, hvis engagement i rom strækker sig fra far til søn siden 1820. Den nuværende Master destiller, Richard Seale, er en af ​​regionens mest innovative blendere og har en passion for at fremstille perfekt rom med god smag. Foursquare Distillery er, som et af ​​de mest moderne romdestillerier i verden, designet til at være ekstremt bæredygtigt. Foursquare rom er lavet på melassen fra lokale sukkerrør. Den gæres langsomt i 44 timer med gær fra Sydafrika og bliver derefter destilleret. Rommen er en blanding af pot- og kolonne destileret rom. Pot still destilatet giver kompleksitet og smag, mens kolonnen tilføjer balance og aroma. Blandingen gør at Foursquare Détente er en Single Blended Rom, præcis som med Single Malt Whisky. Foursquare Détente Single Blended Rum er modnet i en kombination af ex Bourbon og ex-Portvins fade i 10 år. Aftappet i 2020 ved 51%. Duft Træagtige noter fra Burbonfadet og vinøse fra portvinsfadet. Vanilje, læder, mørk chokolade - næsten som Brownie. Smag Fabelagtig balance mellem alkohol og rom. Brownien er der, sammen med træet og de bløde vinøse noter. Eftersmag Den tøre smag af træ bliver hængende i lang tid, mod slutningen blander sig portvinsfadet i en meget flot afslutning. Kommentar En værdig arvetager til den tidligere Port Cask Finish. Balancen er så god, at enhver romnyder, uanset favoritstil, vil blive begejstret.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Rum Glas x 6 stk.', 'https://www.uhrskov-vine.dk/planteray-glas-6', 300, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-glas-6_2.jpg', 'Boks med 6 stk Plantation Destillat glas. Med Plantations loge indgraveret på glasset. Glassene er 16,5 cm høje, og er rigtig velegnede til Rom og Whisky.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('FC Midtjylland 25 års Jubilæum Single Estate Panama Rom 40%', 'https://www.uhrskov-vine.dk/fcm-25-aars-jubilaeum-single-estate-rom-40', 599, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/c/fcmrom.png', 'I 1999 blev FC Midtjylland skabt. Ikke mange uden for Herning og Ikast troede på idéen om en storklub fra heden. Men i 2024, 25 års jubilæumsår, kan fans og følgere af klubben se tilbage på et kvart århundrede med store oplevelser. Fire danske mesterskaber, to pokaltitler og deltagelse i europæiske turneringer, bl.a. UEFA Champions League. Fodbolden har samlet regionen og givet store oplevelser på stadion - og uden for banen med FCM Klubsamarbejdet og FCM Samfund. Alt dette er kun muligt med hjælp fra en masse frivillige fra foreningssporten, en loyal og dedikeret gruppe af sponsorer og partnere, og sidst men ikke mindst alle klubbens engagerede fans og tilskuere. På vegne af alle i FC Midtjylland - Tak for støtten. Smagsnoter: En duft af brændt sukker, som giver behagelige noter af karamel og vanilje, sammen med hint af grønne modner druer og citrusfrugt. Smagen er blød og cremet med noter af creme brulée, mørk sirup, kaffe og vanilje.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('ISH Spirits, Alkoholfri Rom Caribbean Spiced Spirit 50cl', 'https://www.uhrskov-vine.dk/rumish-alkolfri-gin-50-cl', 119, TRUE, 50, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/s/ishrum.png', 'Rumish er lavet på naturlige planter som muskatnød og vanilje fra Madagaskar. De samme noter du finder i en typisk rom. Den gyldne farve kommer fra bagte æbler.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Quorhum 23 Anos Solera Den Dominikanske Republik 40%', 'https://www.uhrskov-vine.dk/ron-quorhum-23-anos-solera-den-dominikanske-republik', 479, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-quorhum-23yo_2_1.jpg', 'Denne Ron Quorhum 23 års fra Den Dominikanske Republik er produceret på den klassiske pot still metode. Modnet i tidligere bourbon tønder, af amerikansk eg, på Solera metoden. Smagen er smukt afbalanceret med en fed sødme. Den slutter af med stærke noter af eg, citrus og karamel.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Papas Pilar Dark Rum 43%', 'https://www.uhrskov-vine.dk/papas-pilar-dark-rum', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/papas-pilar-dark-rum.jpg', 'Papa’s Pilar Dark Rum er en fyldig og sødmefuld rom blandet af destillater fra Caribien og Nord-, Syd- og Mellemamerika. Rommen er skabt for at ære mindet om Ernest Hemingway; USAs stordrikkende, litterære nationalhelt. Under lagringen ligger rommen både på bourbonfade, portvinsfade og sherryfade, og resultatet er en rom med enormt meget smag og masser af sødme!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Experience Rom Gavesæt med 6 forskellige Rom', 'https://www.uhrskov-vine.dk/plantation-rom-gavesaet-med-6-forskellige-rom', 499, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-6pcs-box_1.jpg', 'Plantation er et godt køb hvis du sætter pris på god Rom, og her får du 6 forskellige Plantation Rom i en flot cigar æske. Dette flotte gavesæt indeholder følgende Rum fra Plantation: 1 : 3 Stars White Rum   2 : Original Dark Rum…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation 2020 Black Cask Barbados & Peru Edition 40%', 'https://www.uhrskov-vine.dk/plantation-black-cask-barbados-peru-2020', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-black-cask-2020-barbados-peru.png', 'Plantation Rum har lavet et nyt og meget spændende blend bestående af fyldig Pot Still- & Kolonnedestilleret rom fra Peru og blød sødmefuld rom fra Barbados. Rommen fra Peru er krydret, varm og fyldig med noter af tørrede frugter, kakao og chokolade. Den blender perfekt sammen med den lettere rom fra Barbados, som kommer med noter af konfekt, kokos og orange. Det hele tilsat masser af kærlighed og lidt sødme, hvilket giver en hel unik Plantation Black Cask 2020 Edition. I år tappede vi igen rommen på den lille buttede Plantation flaske. Vi ændrede selvfølgelig en smule på forrige års design, så varen fremstår frisk og højaktuel.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve Legacy Finest Saint Lucia Rum 43%', 'https://www.uhrskov-vine.dk/chairmans-reserve-legacy-43', 399, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/h/chairman_reserve.jpg', 'Chairman’s Reserve Legacy er en hyldest til St. Lucia Distillers formand, Laurie Bernard, som var pioner inden for blending af rom fra forskellige destillationstyper. Passende for Laurie Bernards vision er Legacy rommen derfor et fantastisk blend af rom fra hhv. pot still, batch still og column still, hvilket giver rommen en vidunderlig intensitet og kompleksitet. Rommen har dejlige noter af rosin og karamel, som harmonerer skønt med tobak, vanilje og banan.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Ambassador Selection Rom, Venezuela 47%', 'https://www.uhrskov-vine.dk/diplomatico-ambassador-selection-rom-venezuela-47', 1795, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diploamba.png', 'Denne premium rom fra Diplomatico er lavet i et stærkt begrænset antal. Rommen har lagret på bourbon samt de fineste sherry px fade fra Spanien. Diplomatico Ambassador er tappet ved fadstyrke som er 47%.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('FC Midtjylland Caribbean Rom 40%', 'https://www.uhrskov-vine.dk/fcm-rom-caribbean', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/c/fcm-rom-caribbean.jpg', 'Den sidste FC Midtjylland rom vi lavede i samarbejde med FCM blev taget rigtig godt imod, så selvfølgelig skulle vi lave endnu en. Denne gang er rommen fra Caribbien og er et blend af rom fra de klassiske romproducerende lande i Caribien. Men stadig produceret under sloganet " Sammen skriver vi flere kapitler & sammen dyrker vi drømmen." Dejlig kompleks duft af vanilje, karamel og svagt hint af kanel. God fyldig smag rammer munden, efterfulgt af en lang og sødmefuld eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden 2016 LROK The Younger Pure Single Jamaican Rum, 47%', 'https://www.uhrskov-vine.dk/hampden-2016-lrok-the-younger-jamaica-47', 549, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/o/bonde.png', 'HAMPDEN 2016 LROK The Younger , limited edition, der fuldender sortimentet af Hampden for 2021: Hampden Estate er kendt for at producere et stort udvalg af destillater. LROK står for Light Rum Owen Kelly, et af flere mærker lavet på Hampden Estate og henviser til en rom med en høj ester koncentration, der spænder fra 200 til 400 g / hLPA. Dette mærke skabt i 1952 tilhører wedderburn kategori, dvs den tunge rom. I dette tilfælde er esterindholdet på 314,8 gr/hLPA. Hampden Estate Den yngre har været i alderen i 5 år i det tropiske jamaicanske klima. Det kombinerer aromatisk intensitet på grund af sin tropiske aldring og friskheden af en ung rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Uhrskov Fars Rom 40%', 'https://www.uhrskov-vine.dk/uhrskov-fars-rom-15yo', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/a/fars.png', 'Uhrskov Vine er klar til at hylde alle fædre. Det gør vi med denne udgivelse "Fars Rom". Så har du en far der sætter pris på god rom, så har vi den perfekte gave til ham. Det er en super lækker caribisk rom som har en dejlig kompleks duft af vanilje og et svagt hint af karamel. En god fløjlsblød smag af karamelsødme rammer munden, kombineret med noter af mørk chokolade og vanilje. En sjov og lækker rom, som far vil sætte pris på. En god og sjov ide til en fars dag gave.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Single Vintage 2004 Rom, Venezuela 43%', 'https://www.uhrskov-vine.dk/diplomatico-vintage-2004-rom', 749, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diploaeske_1.png', 'Diplomatico Single Vintage 2004 er en rom, der er destilleret på gamle Pot Stills af kobber og Kettle Batch Stills. Efterfølgende er rommen lagret på de bedste bourbon-fade og single malt whisky fade, som Tito Cordero (Master Blender hos Diplomatico) kunne finde. Som afslutning har Diplomatico Single Vintage Rum fået en efterlagring på spanske sherryfade. Noter: egetræ balanceret med tørret frugt, vanille, chokolade og "toastet" karakter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus 21 år Den Dominikanske Republik 38%', 'https://www.uhrskov-vine.dk/opthimus-21-ar-den-dominikanske-republik-38', 579, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/p/opthimus-21yo-dominikanske_2_1.jpg', 'En spændende spiritus fra det dominikansk baserede Opthimus brand, lagret 21 år på amerikanske egetræsfade. Duft Vanilje, rosenblad, hybenblomster og lette kokosnoter. Smag Fyldig og syrlig – med hybenmarmelade. Eftersmag Langvarig – med hyben, kokos og kirsebær.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 7 Års Overproof Pure Single Jamaican Rum 60%', 'https://www.uhrskov-vine.dk/hampden-7aar-60-overproof', 699, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden-7yo-60-overproof.jpg', 'Hampden Estate er en af de ældste sukkerplantager og destillerier på Jamaica. Hampden Estate har altid været kendt for sine meget intense og smagsrige pot still rommer. Sådan har det været siden midten af det 1700ende århundrede og sådan vil det også være fremover – heldigvis. Rommen produceres på traditionel vis med brug af egen gær og tilsætning af Dunder, som bedst beskrives som en gammel vildgær der giver tunge ”funkye” noter i rommen. Alt afhængigt af hvilken intensitet rommen skal have gæres der fra en til flere uger. Den længste gæring resulterer i et estertal på 1500, hvilket kun anvendes meget forsigtigt i blends eller i aromaindustrien, da duften og smagen i denne romtype er overvældende. Romen er utroligt spændende og på ingen måde skræmmende. Æbler, ananas, frugtvoks, the og lidt ingefær fornemmes lystigt i duft og smag. Flot stor finish med vanilje, ingefær og sødlige fadtanniner.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 16 Martinique 13 års Single Cask Rum Batch 1 60,7%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-16-martinique-13-single-cask-batch-1-60-7', 995, TRUE, NULL, 60.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/martiniquebatch1.png', 'Der er tappet to fade af Wild series rum no.16. da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2 Denne helt særlige aftapning kommer fra Destillerie du Simon, som er kendt for at producere rom til flere store brands. Her er Clement nok det mest kendte af disse, men også A1710 får deres rom derfra. Den er basereret på frisk sukkerrørs juice og er dermed den første rom af agricole typen vi lancerer i Wild series rum. Her er tale om en rom med alle de tyspiske friske noter som er så fascinerende ved agricole rom. I næsen er der noter af friske sukkerrør, grønt græs og hø. I munden får man hint af grønne æbler, peber, vanilje, sukkerrør, milde frugtige noter og en smule træ.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('FC Midtjylland 2020 Guld Limited Edition Caribbean Rom 60%', 'https://www.uhrskov-vine.dk/fcm-rom-guld-60', 599, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/c/fcm-rom-guld-60.jpg', 'Denne Rom er aftappet ekstraordinært som en hyldest til FC Midtjylland’s 3. mesterskab. Der er kun tappet 60 unikke flasker i 60% fuld fadstyrke. Blandet af rom fra de klassiske romproducerende lande Barbados, Jamaica og Guyana. Dejlig kompleks duft af vanilje, karamel og svagt hint af kanel. Med de 60% får du fuld smæk på fylde og kompleksitet, efterfulgt af en lang og sødmefuld eftersmag. Ver Limited Edition - Only 60 Bottles', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico 2007 Single Vintage Rum, Venezuela 43%', 'https://www.uhrskov-vine.dk/diplomatico-single-vintage-2007-rom-venezuela-43', 999, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplo2007.png', 'Diplomático Single Vintage er fremstillet ud fra et blend af nøje udvalgte og specielle romreserver, som har udviklet sig på en exceptionel måde. Diplomáticos Maestros Roneros udvælger selv hver eneste fad, så rommens karakteristiske smag og personlighed lever op til hans tårnhøje forventning.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Vizcaya VXOP Cask 21 Cuban Formula Rum 40%', 'https://www.uhrskov-vine.dk/vizcaya-vxop-cask-21-cuban-formula-rum-40', 499, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/i/vizcaya-vxop-cuban-21yo.jpg', 'Vizcaya VXOP er destilleret fra sukkerrørs saft og lagret på bourbon og whisky tønder. Dette er en intens krydret rom, som har aroma af muskatnød, kanel og ingefær. Ganen er ligeledes rig på en krydret sødme og viser også noter af honning, vanille og karamel. Nyd denne Rom rent eller tilsæt is.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Reserva Limitada 2019, Guatemala 45%', 'https://www.uhrskov-vine.dk/ron-zacapa-reserva-limitada-2019-guatemala', 649, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-zacapa-limitada-2019_2.jpg', 'Ron Zacapa Reserva Limitada 2019 er et blend af rom som er mellem 6-24 år gammel, udvalgt af Master blender Lorena Vazquez, Limitada har lagret på spanske og amerikanske hvide egetræsfade. Rommen har de klassiske Zacapa smagsnuancer af vanilje, karamel suppleret med noter af friske urter. Limitada 2019 Rommen bliver kun solgt i begrænset oplag. Zacapa Reserva Limitada 2019 har en dyb mahignifarve med en intens ravglød. Duften har noter af vanilje med hints af chokolade, abrikos, træ og karamelliserede frugter. Smagen er eksotisk og kompleks. Den har antydninger af chokolade og vanilje, og der er en udsøgt balance mellem noter af frugt og ristede mandler.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum Blended Rum 40%', 'https://www.uhrskov-vine.dk/ramstein-rum-blended-rum-40', 339, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/ramstein-12yo-rum.jpg', 'Rammstein Rum, som er et blend fra Jamaica, Guyana og Trinidad. Både Guyana og Jamaica rom er i cirkler af masterblender og eksperter højt værdsat for deres stærke krop og dybe aromaer. Den stærke karakter af begge pot still rom er tæmmet af den elegante modstander fra Trinidad. Resultatet er en afbalanceret rom med krydrede noter og bløde frugt noter. Rammstein Rum er modnet i op til 12 år i ex-Bourbon fade, hvilket giver rommen en antydning af røg og en varm gul farve.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk & Sweeney 23 år Den Dominikanske Republik 40%', 'https://www.uhrskov-vine.dk/kirk-sweeney-23-ar-den-dominikanske-republik-40', 650, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/i/kirk-and-sweeney-23yo.jpg', 'Opkaldt efter "skonnerten", som smuglede Rom fra Caribien til den nordøstlige del af USA i løbet af forbudstiden i det gamle Amerika. Kirk & Sweeneys 23 års er en rig og kompleks rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 15 Enmore 33 års Single Cask Rum Batch 1 50,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-15-enmore-33-single-cask-rom-de-luxe', 2795, TRUE, NULL, 50.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/wsr_enmore_b1-removebg-preview.png', 'Der er tappet to fade af Wild series no. 15. da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2 Denne helt særlige aftapning kommer fra Versailles kedlen som er den eneste tilbageværende enkelte potstills kedel der er lavet i træ, og som stadig fungerer. Rommen er destilleret i 1988, mens kedlen stadig stod på Enmore destilleriet. Destilleriet blev lukket i 1994 og kedlerne er senere endt på Demerara destilleriet. I denne rom får man en virkelig blød og varm rom Noterne er grundet den ekstreme alder, kraftige og intense. Her er noter af Blomme, brændt karamel, mørkt brunt sukker, tørret frugt, tobak og masser af træ.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Angostura 1919 Premium Gold Rom, Deluxe Aged Blend 40%', 'https://www.uhrskov-vine.dk/angostura-1919-premium-gold-rum', 249, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/n/angostura-1919-premium-gold-rum_2.jpg', 'Flot blød Trinidad & Tobago Rum der leverer en generøs og langvarig vifte af Toasty smagsvarianter som et resultat af lang ældning i forkullet tønder. Denne rom er en blend af lette og kraftige årgangs-rom, der er lagret i mindst 8 år, på egetræsfade, der før har været brugt til Bourbon. Faktisk ligesom man kender det fra produktionen af maltwhisky.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Jamaica White Rom 57%', 'https://www.uhrskov-vine.dk/rum-nation-jamaica-white-rom-57', 249, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-jamaica-white.jpg', 'Denne Rum Nation hvide rom fra jamaica er bestemt påvirket af den langsommelige gæring. Den får en aromatisk duft af grønne bananer, og en lidt syrlig note. Smagen er intensiv og eksplosiv, men ikke skarp. Den har smagsnoter af peber, grønne oliven, palmeblade og bananer. Den har en vedvarende finish, nærmest endeløs, hvor den bevarer noter af de grønne bananer, med en antydning af druer og tequila.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series New Yarmouth Tasting Kit Limited Edition 3 x 25cl.', 'https://www.uhrskov-vine.dk/wild-series-new-yarmouth-tasting-kit-limited-edition-3-25-cl', 1495, TRUE, 25, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/n/e/new-yarmouth-tasting-kit.png', 'Rommen som er i flaskerne er en unaged New Yarmouth, som har lagret 6 mdr. på små 40 l fade. de har tre forskellige finishes.  Der er Madeira, Malaga Wine og PX Sherry. ABV er mellem 72% og 74% på de tre aftapninger.  Der bliver kun tappet 160 sæt af denne aftapning-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 2 Batch 1, Diamond 25 års Rum, 49,2%, RomDeluxe', 'https://www.uhrskov-vine.dk/diamond-25-collectors-series-rum-batch-1', 1495, TRUE, NULL, 49.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diamondbatch1.png', 'Der er tappet to fade af Collectors series rum no. 2. da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2. Denne helt særlige aftapning kommer fra Diamond destilleriet. Den er melassebaseret og og kolonnedestilleret på en Diamond metal Coffey still. I denne rom får man et rigtigt spændende glas. Duften er fyldt med syltede blommer og tørret frugt. I munden får man mørk chokolade, jasmin blomster, tørret frugt, melasse, lakrids og brændt træ.  En intens og powerfull rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk & Sweeney Gran Reserva Den Dominikanske Republik 40%', 'https://www.uhrskov-vine.dk/kirk-sweeney-18-ar-den-dominikanske-republik-40', 429, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/w/sweeneygr.png', 'Kirk and Sweeney Reserva  Et premium blend af 3 til 18 årige rom fra Den Dominikanske Republik, modnet i både amerikanske og franske egetræsfade.  Både bourbon og sherry fade heriblandt. Duft Fyldig og rund. Intense vaniljenoter og klassiske sherry noter som rosin og sveske. Derudover en let ristet sukkerrørsnote Smag Dyp og krydret. Tørret frugt og vanilje.... Muskatnød, kanel og tydelig, men blød, egetræ Eftersmag Silkeblød og langvarende. Noter af egetræ, oloroso sherry og rosin.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Trinidad Vintage 2009, Limited Edition 51,8%', 'https://www.uhrskov-vine.dk/plantation-trinidad-vintage-2009', 599, TRUE, NULL, 51.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationtrinidad.png', 'Endelig er næste udgivelse i Plantations Vintage ”Birds of Paradise”-serie landet! Denne gang får de andre fugle selskab af en Scarlet Ibis, som er et symbol på Trinidad & Tobago og naturligvis pryder flaske og æske til en Trinidad-rom. Plantation Trinidad Vintage 2009 kommer fra Trinidad Distillers Limited. Den er tappet ved 51,8% alkohol (uden tilsat sukker) efter i alt 12 års lagring. De første 11 år har den tilbragt på 200-liters ex-bourbonfade i destilleriets egen kælder i Trinidad, hvorefter rommen tager turen over Atlanten for at ligge 1 år på Maison Ferrands fade af fransk eg. I alt indgår der 24 fade i aftapningen. Til nørderne kan oplyses, at det totale indhold af volatile substances er 525 g/hL AA og ester-indholdet 205 g/hL AA.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Solhverv Rav Rom 30% 50cl', 'https://www.uhrskov-vine.dk/solhverv-rav-rom-30-50', 250, TRUE, 50, 30, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/o/solhvervravrom.png', 'Solhverv RavRom med Hyben + Havtorn er sød og rund i smagen og passer helt perfekt til årets varmeste sæson … sommeren. Solhverv RAV ROM lagres på egetræsfade som giver en dyb og kraftig smag. Rom og de florale, let salte ravnoter tilføjes syrlighed fra havtorn og hybens blide, blomstrede og let søde toner. Resultatet er en fuldendt og unik smagskombination.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Flor de Cana 18 år, Legacy Edition I 40% Centenario', 'https://www.uhrskov-vine.dk/flor-de-cana-18yo-legacy-edition', 325, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/l/flor-de-cana-18yo-legacy-edition_2.jpg', 'Flor de cana 18-årige fra Nicaragua. Blev tildelt dobbelt guld medaljer på 2006 og 2008 San Francisco “World Spirits Competition”, faktisk så har Flor de Cana fået et væld af internationale priser siden 2000. “Slow Aged” betyder at Rommen har lagret på amerikanske egefade i alle 18 år, hvor mange andre brands blander forskellige årgange. Duften er sprød og krydret, smagen er fyldig med noter af karamel, nødder og allehånde.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden 2011 LFCH 7 år Jamaican Pure Single Rum 60,5%', 'https://www.uhrskov-vine.dk/hampden-2011-hlcf-7yo-jamaica', 699, TRUE, NULL, 60.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdenlfch.jpg', 'Hampden 2011 HLPF er den anden originalaftappet udgave i fuld fadstyrke fra Hampden destilleriet på Jamaica. Udgivet som en del af Habitation Collection, Hampden Estate.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Gaveæske med 2 Glas', 'https://www.uhrskov-vine.dk/plantation-gaveaeske-med-2-glas', 149, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-giftbox_3.jpg', 'Denne flotte gaveæske fra Plantation med 2 romglas er en rigtig flot og indbydende måde at præsenterer din Romgave på, en rigtig fin julegave. Brug denne giftbox som et tilkøb til din Plantation Rom, vi har æsker der passer begge str. på Plantations Rom flasker. Skriv evt. i "bemærkninger" om kassen skal passe til den høje tynde flaske eller den lille tykke flaske. Bemærk der følger ikke en Rom med i denne pakke, kun gaveæske og 2 glas .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series 5th Anniversary Edition Single Cask Rum, Rom de Luxe 86,2%', 'https://www.uhrskov-vine.dk/wild-series-5th-anniversary-edition-single-cask', 1495, TRUE, NULL, 86.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/romdeluxejamaica.png', 'Release on Saturday the 21th August at 10.00 ! !   Denne aftapning er dedikeret til RDL´s 5 års jubilæum som blev fejret i juli.    For 2 1/2 års siden blev den første Wild Series Rum lanceret - en nærmest sagnomspundet Tiger fra Trelawnyområdet på Jamaica. En ikonisk rom på mange måder. Lige siden lanceringen har vi tænkt på om man kunne lave en rom der var endnu vildere   Vi valgte derfor at fylde 200 ltr. unaged Jamaikansk DOK på et brugt Caronifad.Rommen har ligget og hygget sig på fadet i 15 mdr.    Den er om muligt endnu vildere end vores første DOK aftapning. Dette skyldes en kombination af at den indeholder 1600 estere, har fået noter fra Caroni fadet og at ABV er på hele 86,2%   Et rigtig spændende projekt som vi er glade for at præsentere for jer."', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cubaney Grand Reserva 12 år Magnifico, Den Dominikanske Republik 38%', 'https://www.uhrskov-vine.dk/cubaney-grand-reserva-magnifico-12-ar-den-dominikanske-republik-38', 269, TRUE, NULL, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/u/cubaney-magnifico-12yo_2.jpg', 'Ron Cubaney Magnifico er ​​den fineste kvalitet. Huset Oliver & Oliver har vundet masser af priser for deres Rom, og her endnu en perle. Duften er meget intensiv. På ganen frugt, karamel, vanilje og egetræ. Kroppen er kompleks og blød.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Jamaica Vintage 2003, Summer 2020 17 år 49,5%', 'https://www.uhrskov-vine.dk/plantation-jamaica-vintage-2003-summer-2020', 699, TRUE, NULL, 49.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-jamaica-vintage-2003-summer-2020.jpg', 'Denne længe ventede udgivelse i Plantations Vintage-serie kommer fra det jamaicanske destilleri, Clarendon. Rommen blev destilleret i 2003 og har et esterindhold på 422 gram per hektoliter ren alkohol – det er bestemt i den høje ende for Clarendon, og giver løfte om en rom med masser af smag! Efter 16 års lagring på bourbonfade i et tropisk klima, blev rommen flyttet til cognacfade i Frankrig, hvor den tilbragte godt 1 år, før den blev tappet ved yderst respektable 49,5% uden tilsætning af sukker…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot 50th Anniversary British Royal Navy Rum 54,4%', 'https://www.uhrskov-vine.dk/black-tot-50-anniversary-54-4', 999, TRUE, NULL, 54.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50642320.jpg', 'For at fejre 50-års jubilæet for den dag, hvor den britiske flåde stoppede traditionen med daglige udskænkninger af rom (du kan læse mere  her ), har Black Tot frigivet en helt særlig rom. Ovenikøbet er det med en hidtil næsten uset grad af gennemsigtighed, idet hele blendet er gengivet på bagetiketten. Du får simpelthen opskriften med! Der er for mange komponenter til at opremse her, men den indeholder naturligvis Hampden, Foursquare, Caroni, den originale navy rum – og en lille smule 42 år gammel Port Mourant! Du kan se hele opskriften  her .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Veritas White Blended Rum 47%', 'https://www.uhrskov-vine.dk/veritas-white-blended-rum', 249, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/e/veritas-white-blended-rum-47.jpg', 'Veritas er en blanding af hvid rum fra den traditionelle Foursquare Coffey-still på Barbados og Double Retort Pot-Still fra Hampden på Jamaica. Fremragende hvid rom perfekt destilleret og genial ledsager til dine fremtidige Daiquiries.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 9 Long Pond 19 års Single Cask Rum 59%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-9-long-pond-rom-de-luxe-59', 2500, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/o/long-pond.png', 'Wild Series 9 Long Pond 19 Års Single Cask er den 9. rom i Romdeluxe "Wild Series" serie. De gode folk fra Rom de Luxe har her fundet et 19 år gammelt Single Cask fra  Jamaica, hvorfra rommen er destilleret Long Pond Distillery og tropisk lagret i alle 19 år. Denne rom er Pot Still´s destilleret i 2001, og efterfølgende lagret på amerikanske bourbonfade- Tappet ved  fuld fadstyrke 59% i August 2020, og der er ikke tilsat hverken sukker eller farve. Kun 209 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Flor de Cana 12 år 40% 100cl', 'https://www.uhrskov-vine.dk/flor-de-cana-12yo-100cl', 329, TRUE, 100, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/l/flor-de-cana-12yo_2_1.jpg', 'Denne rødlig rav rom er prægtig, elegant og halvsød. Drik den rent, on-the-rocks eller med et stænk af vand. Bedømmelse 90-95 og stærkt anbefalet af Wine Enthusiast i 2004, vinder af 13 International Awards, Centenario 12 er en Rom du ikke bør snyde dig selv for.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Guyana 1994 Enmore Rom 48.5%', 'https://www.uhrskov-vine.dk/sbs-guyana-1994-enmore', 2299, TRUE, NULL, 48.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_guyana_1994.jpg', 'S.B.S Guyana 1994 er rom fra et enkelt fad, som kun resulterede i 124 flasker. Det er Pot still rom fra det nu lukkede Enmore Sugar Estate (1994), og destilleret på Versailles træ pot still. Et af de legendariske stills, der nu er placeret i det sidste resterende destilleri i Guyana, Demerara Distillers Limited, også kaldet DDL. Versailles træ pot still eller Vat er i dag et, af kun to træ pot stil, der stadig er tilbage i verden.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Depaz VSOP Vieux Agricole Réserve Spéciale, Martinique 45%', 'https://www.uhrskov-vine.dk/depaz-vsop-vieux-agricole-reserve-speciale-martinique-45', 575, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/e/depaz-vsop-speciale_2.jpg', 'Med 7 års fadlagring (svarer til 21 år i Skotland) fremstår denne gamle mørke rhum med en meget indbydende duft af chokolade, vanilje og karameliserede frugter. En virkelig oplevelse for en kender af rhum. I eftersmagen finder man toner fra kaffe og tobak - et helt igennem super glas til kaffen eller den store god cigar.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distllery Edition 2020 Old Pure Single Jamaican Rum, 59%', 'https://www.uhrskov-vine.dk/hampden-great-house-edition-2020-59', 1499, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden_2020_greathouse.jpg', 'Hampden Estate, der ligger i regionen Trelawny i det nordvestlige Jamaica, har været aktiv siden 1753. Her produceres en unik rom, kendetegnet ved deres langvarig gæring med vildgær og "dunder" hvorefter der udelukkende destilleres på Pot- still. Denne eksklusive Hampden Great House Destillery Edition er tappet ved 59% og tropisk lagret på Hampden Distillery. Denne aftapning er den første officielle destilleri aftapning fra Hampden..  2020-udgivelsen er limited edition af ​​Hampden Great House og er en frugtagtig rom med en let medicinsk kant. Aromaer af ananas, tjære, tobak og ferskner fylder næsen suppleret med smagsnoter af ananas samt vanilje, chokolade, lakrids, appelsinskal og gummi i munden. ” …fruity notes that are extremely lovely. Mangos, papayas and crushed ripe bananas. A bit tight, in fact, but the tongue sees no flaws.” Serge Valentin, whiskyfun.com 6. Dec. 2020', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Finest Caribbean Rum 46,2%', 'https://www.uhrskov-vine.dk/black-tot-finest-caribbean-rum', 459, TRUE, NULL, 46.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/black-tot-finest-caribbean-rum.jpg', 'Black Tot kombinerer de elegante og rige smage fra Barbados og Guyana med Jamaicas dristige karakter. Denne rom er usødet, ufilteret og aftappet på 46,2% for ekstra smag. Duft: Tropiske noter af ananas, mango og melon. Smag: Fyldig tekstur snørret med intense espressonoter, inden den udvikles til ingefær, nelliker, honninggmelon og kardemomme Finish: Langvarig, afrundet med tropiske frugter, chilisyltetøj, masala chai og vanilje.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Hogo Monsta High Ester Rum 56,6% 20cl', 'https://www.uhrskov-vine.dk/planteray-hogo-monsta-high-ester-rum-566-20cl', 299, TRUE, 20, 56.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/1/7/176166145842667617_1.png', 'De kalder den ”Blenderens hemmelige våben”. Og nej, vi snakker ikke om din Vitamix, men om master blenderen hos West Indies Rum Distillery. Du ved - ham, som sammensætter den rigtige blanding af fade, når der skal tappes rom. Det er nemlig sjældent, at man blot tapper ét fad, som det er – en romaftapning er næsten altid en blanding af flere fade - 2, 5 eller måske 25 forskellige – for at få den rigtige smag. Der er så mange ting, der påvirker en roms karakter: alderen, fadet, gæringen… Planteray Hogo Monsta er at betragte som et koncentrat: en rom, der er er presset til det ekstreme gennem en ekstra lang gæring. Den kan tilsættes i små mængder for at give kompleksitet, dybde og intensitet, men er som sådan ikke beregnet til at drikkes rent. Ha! Det har aldrig stoppet en ægte romnørd. For dem er ”hemmelige” aftapninger som disse utroligt spændende at smage. Men det er ikke en, man byder naboen når han kommer forbi til et glas. Så er du advaret.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ypioca Ouro Cachaca 38% 100cl', 'https://www.uhrskov-vine.dk/ypioca-ouro-cachaca-100cl', 245, TRUE, 100, 38, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/y/p/ypioca-ouro-cachaca_1.jpg', 'Cachaça er betegnelsen for brasiliansk brændevin fremstillet ved gæring af ren sukkerrørs saft. Etableret i 1846, Ypióca er den største producent af Cachaça i Brasilien. Cachaça er den vigtigste ingrediens i den legendariske caipirinha cocktail - en nationale drik i Brasilien. “Ouro Cachaça” er i en carnauba halm-vævede flaske, lavet helt i hånden. Ouro Cachaca er fadlagret i to år i Freiji-trætønder, en særligt træsort fra Brasilien.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Hechicera Extra Anejo Solera 21 Columbia, 43%', 'https://www.uhrskov-vine.dk/la-hechicera-extra-solera-21-columbia', 339, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-hechicera-solera-21.png', 'La Hechicera er produceret af Columbias eneste familie- og privatejede romvirksomhed, der i dag bliver drevet af tredje generation af familien Riascos. Rommen bliver sammenstukket fra et gammelt solerasystem, og er et mesterligt blend af fine rom, der alle er lagret mellem 12 og 21 år i gamle amerikanske hvide Bourbon egetræsfade, der yndefuldt fanger karakteren, frodigheden og diversiteten fra Columbia. La Hechicera en blød, dyb og rund smag. Smagsoplevelsen er helstøbt, med noter af brun farin, modne tropiske frugter, vanilje og let ristet eg trænger gennem i både smag og duft.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes TEN CANE Distillery 9, Trinidad Rum, 56,3%', 'https://www.uhrskov-vine.dk/cdi-ten-cane-distillery-9-56-3', 899, TRUE, NULL, 56.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cditencane.png', 'Den første Ten Cane-rom, vi fik fra Compagnie des Indes, blev udsolgt på et øjeblik. Derfor har vi ventet spændt på, hvornår det næste fad fra dette obskure, lukkede destilleri på Trinidad skulle dukke op. Hvis du ikke kan huske – eller aldrig har hørt om – Ten Cane, så er den korte udgave, at Ten Cane blev bygget af Louis Voutton Moët Hennessy i midten af ’00’erne med det formål at lave pot still-destilleret rom på frisk sukkerrørssaft i Trinidad. Desværre bukkede destilleriet under og måtte lukke inden rommen fandt sit publikum, og derfor er fade fra Ten Cane utroligt sjældne (og eftertragtede) i dag. Denne gang er det en rom fra 2012, som kom på flaske i april 2021 efter 9 års lagring. Der er tappet i alt 264 flasker ved fadstyrke (56,3%). Rommen er ikke tilsat sukker eller kølefiltreret.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 6, Ten Cane 13 års Rum, 62,3%, RomDeluxe', 'https://www.uhrskov-vine.dk/ten-cane-13-ars-collectors-series-rum-romdeluxe-62-3', 945, TRUE, NULL, 62.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/s/csr-tencane-box.png', 'Ten Cane, som var et førsteklasses trinidadisk let rom -mærke ejet af LVMH. Moët Hennessy, introducerede Ten Cane i 2005. Produktionen blev indstillet i 2015. Ten Cane rom blev opkaldt efter traditionen med håndhøst og bundtning af sukkerrørstilke i grupper på ti. Romene fra Ten Cane er lavet af frisk sukkerrørsaft. Den gæres i 5 dage og destilleres bagefter i en lille portion. Den er lagret på franske egetræsfade i en årrække. Denne er 13 år gammel, og der er ikke tilsat farve eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 8 New Yarmouth 25 års Single Cask Rum 68,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-8-new-yarmouth-25-rom-de-luxe-68-1', 3500, TRUE, NULL, 68.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/n/e/new-yarmouth.png', 'Wild Series 8 New Yarmouth 25 Års Single Cask er den 8. rom i Romdeluxe "Wild Series" serie. De gode folk fra Rom de Luxe har her fundet et 25 år gammelt Single Cask fra  Jamaica, hvorfra rommen er destilleret New Yarmouth Distillery og tropisk lagret i alle 25 år. Denne rom er Pot Still´s destilleret i 1994, og efterfølgende lagret på amerikanske bourbonfade- Tappet ved  fuld fadstyrke 68,1% i August 2020, og der er ikke tilsat hverken sukker eller farve. Kun 224 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Lamb''s Navy Rum 40%', 'https://www.uhrskov-vine.dk/lambs-navy-rum-70cl', 179, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/lambs.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 10 år Last Ward 2007 Barbados Pure Single Rum 59%', 'https://www.uhrskov-vine.dk/habitation-velier-last-ward-2007-barbados-pure-single-rum-59', 999, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/last-ward-2007-barbados-pure-single-rum_2.jpg', 'Frank Ward, medlem af familien der ejede Mount Gay Destilleri i over 100 år, begyndte i 2007 at producere Mount Gilboa, triple destilleret rom som efterfølgende blev lagret på gamle bourbonfade. Velier har opkøbt disse fade efter destilleriet blev solgt i 2014. Denne udgave "Last Ward" er resultatet af aftapningen af de 19 ældste fade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park Single Estate 2006, 12 år Jamaica Rum 56%', 'https://www.uhrskov-vine.dk/worthy-park-2006-12yo', 975, TRUE, NULL, 56, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/o/worthy-park-2006-12yo_2.jpg', 'Destilleret i en 100% kobber pot still. Worthy Park Single Estate 2006 er en 12 år gammel rom der har ligget på American white oak ex-Bourbon fade, i Jamaicas tropiske klima. Rommen er tappet ved fadstyrke, er ikke kold-filtreret og indeholder hverken sukker eller andre tilsætningsstoffer. Single Estate 2006 er den første vintage aftapning der kommer direkte fra Worthy Park Estate.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Holey Dollar Rum OVERPROOF Gold Coin 57,2% Fiji Rum', 'https://www.uhrskov-vine.dk/holey-dollar-rum-plat-coin-cask-strength-12123', 199, TRUE, NULL, 57.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/0/7/0770650_hdr_overproof.jpg', 'Overproof rom er højt værdsat på grund af den højere alkoholprocent og på grund af alkoholens indflydelse på smagen af rommen. Historisk set var testen for om rommen var overproof, at hælde lidt af rommen over en smule krudt på et tin-fad og sætte ild til det. Hvis blandingen brændte, havde væsken bevist at den var “Proof”. Hvis væsken var stærkere end ‘Proof’, så ville krudtet antændes og ‘eksplodere’, hvilket var bevis for at rommen var ‘Over-proof’. Vi ved nu at over-proof er når at alkoholen er på 57,2%. Overproof Gold Coin er fantastisk at nippe over is eller som base for premium cocktails.Overproof Gold Coin har en medium rav-agtig farve. Man finder eksotiske frugtnoter som i Silver Coin, men alt er i større overflod. Florale noter og krydderier blandes med mørke noter af melasse, som alle forstærkes i munden. Alle noter fremhæves af den rene og kraftige alkohol. Rommen har en fantastisk twist af røg, som med alle noterne sammenfattes til en sublim og kraftig finish. Den mest populære rom, af de tre, i Australien.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Gold of Mauritius, Dark Rum 70cl 40%', 'https://www.uhrskov-vine.dk/gold-of-mauritius-dark-rum-70-40', 325, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04067.jpg', 'Her er en rom der ikke kommer fra Caribien. Rommen kommer fra den lille ø Mauritius i det Indiske Ocean. Øen ligger lidt længere ude fra Afrika end Madagaskar, og har et areal på ca. 1.900 km². (Lolland og Falster 1.780km 2 ).', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Trinidad Single Cask 12 Years Old 64,7% RomDeLuxe', 'https://www.uhrskov-vine.dk/wild-series-trinidad-single-cask-12-yo', 995, TRUE, NULL, 64.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/wsr14-2_4266_.png', 'Det er en aftapning fra Trinidad distillers limited. den er 12 år gammel, har en ABV på 64,7%  Den er dobbeltlagret. Den har ligget 10 år på ex bourbon cask, i kældrene under destilleriet. Kældrene er opbygget af røde mursten, og leverer en kølighed som gør at rommen modnes langsommere og blidere end normalt under den caribiske sol. efterfølgende har den lagret i Europa indtil den er tappet i April 2021 Der er ikke tilsat sukker eller farve til denne rom Duft: Her fornemmer man noter af Vanilje, karamel, kaffebønner, kandiseret frugt og egetræ Smagsnoter:  Tæt og kompleks. noter af egetræ, kaffe, caramel, vanilje samt et behageligt strejf af benzin.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Ten Cane 13 års Rum, 64%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-ten-cane-13-rom-de-luxe-64', 1395, TRUE, NULL, 64, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/e/tencane_1.png', 'Her kommer endnu en aftapning fra det nu lukkede destilleri TenCane som var beliggende på Trinidad. På Tencane lavede man nogle virkelig spændende smagfulde rom, baseret på frisk sukkerrørsjuice.  Vi har en svaghed fordisse rom, og har endnog meget svært ved at sige nej, når vi får et fad som dette tilbudt. Da destilleriet er lukket, kan det være svært at få alle detaljer om rommen oplyst, hvilket også er tilfældet med dette fad.  Vi ved at det har haft lidt tropisk lagring inden det er flyttet til Europa, for den videre modning. Men da vi ikke kunne få oplyst hvorlænge har vi valgt ikke at skrive det på labelen. Når det er sagt, så er dette en helt fantastisk rom, der virkelig kan få englene til at synge.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Holey Dollar Rum, Plat Coin Cask Strength Rum, 75,9%', 'https://www.uhrskov-vine.dk/holey-dollar-rum-plat-coin-cask-strength', 449, TRUE, NULL, 75.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/o/holeydollar.jpg', 'Holey Dollar Cask Strength Platinum Coin har en smuk og vidunderlig mørk rav farve med aromaer af rosiner og chokolade, ristede mandler og et strejf af tørret banan. Det er en eksplosion af smag, der hvirvler rundt lag på lag. Der er gradvis tørrere og kraftigere egetræs smag og eftersmagen er lang og varm på ganen. Det er virkelig en fabelagtig rom, værdig til at blive drukket i en Cognac-snifter/ballon, enten ren eller med et strejf af is. Rommen er også perfekt med grapefrugt eller andre friske frugtjuicer, eks. bitter lemon. Man kan godt mærke den høje alkohol, men ikke at den er 75,9% og der er en fantastisk kombination af rom og frugt i finish’en, som varer overraskende længe.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Goslings 151 Proof Black Seal, Bermuda Black Rum 75,5%', 'https://www.uhrskov-vine.dk/goslings-151-proof-black-seal-bermuda-black-rum', 349, TRUE, NULL, 75.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/o/goslings-151-proof-black-seal-rum.jpg', 'Gosling´s BS 151 proof er i den ” helt tunge ” ende skal når vi taler Rom, med sine ikke mindre end 75,5% alkohol. Gosling 151 Proof Black Seal Rum er en meget kraftig rom på alle måde, hvor du får masser af duft, saft og kraft. Det tog mange år og mange eksperimenter før Gosling’s nåede frem til dette resultat – at fremstille en meget kraftig Rom som oplagt til de bedste Rom cocktails, og der er lykkedes.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Gold of Mauritius, 5 Solera Dark Rum 70cl 40%', 'https://www.uhrskov-vine.dk/gold-of-mauritius-5-solera-dark-rum', 349, TRUE, 70, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04068.jpg', 'Her er en rom der ikke kommer fra Caribien. Rommen kommer fra den lille ø Mauritius i det Indiske Ocean. Øen ligger lidt længere ude fra Afrika end Madagaskar, og har et areal på ca. 1.900 km². (Lolland og Falster 1.780km 2 ).', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Guyana 2003 Savalle Rom 53.7%', 'https://www.uhrskov-vine.dk/sbs-guyana-2003-savalle', 1099, TRUE, NULL, 53.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_guyana_2003.jpg', 'S.B.S Guyana 2003 er fra et enkelt fad med et resultat på kun 161 flasker. Rommen er baseret på melasse og destilleret på en fransk Savalle kolonne stills i 2003. I februar 2021 blev rommen tappet på vores lager i Danmark uden brug af koldfiltrering eller nogen form for tilsætningsstoffer', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Monymusk MMW Tasting Kit Limited Edition 3 x 25cl.', 'https://www.uhrskov-vine.dk/wild-series-monymusk-mmw-tasting-kit', 1295, TRUE, 25, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/o/monymuskmmw.png', 'D. 23 juli 20212 har Romdeluxe eksisteret i 5 år. Det skal fejres!! I denne anledninge releaser vi et Coffret set, som består af 3 x 25 cl. rum. Flaskerne indeholder alle rom fra Monymusk. Rommen er ulagret og har et estercount på 200 - 300 gr/hl AA Vi har givet rommen en finish på 7 mdr, i små 40L fade som tidligere har indeholdt forskellige typer af vin. Nogle vil sikkert sige at så er rommen jo lagret. Men vores filosofi er at hvis rommen ligger under 1 år på fad, så vil vi hellere kalde det en finish. Ligger rommen mere end et år vil der stå lagret på etiketten. Rommen er tappet d. 13 juli 2021 Dette er en meget limited aftapning, hvor der kun er tappet 150 sæt, til hele verden. ABV er fra 67,4% - 69,8% Herunder følger lidt fakta om de enkelte flasker. Fakta: Flaske nr. 1  Lagret på 40L  American white oak cask som tidligere har indeholdt Madeira Lagret 7 mdr. Tappet ved fadstyrke på 67,4%   Flaske nr. 2 Lagret på 40L  American white oak cask som tidligere har indeholdt Malaga wine Lagret 7 mdr. Tappet ved fadstyrke på 69,8%   Flaske nr. 3 Lagret på 40L  American white oak cask som tidligere har indeholdt Pedro Ximenez Sherry ( PX) Lagret 7 mdr. Tappet ved fadstyrke på 68,4% Der er ikke tilsat farve til disse aftapninger.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Australia Vintage 2007, Limited Edition 49,3%', 'https://www.uhrskov-vine.dk/plantation-australia-vintage-2007-limited-edition', 699, TRUE, NULL, 49.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationaustralia.png', 'Australia has been producing sugarcane eau-de-vie for nearly 150 years, earning its rightful place on the world rum map. Distilled in pot stills, Plantation Australia 2007’s great aromatic complexity owes its personality to the particular yeasts used during fermentation. The spirit is first fermented for 12 days with Schizosaccharomyces pombe, a very rare yeast in the world of rum, and dunders. It is then followed by a three-day fermentation with Saccharomyces cerevisiae. Distilled in 2007, Plantation Australia was first aged for 13 years in ex-bourbon barrels in the cellars of Beenleigh Artisan Distillery. The 21 barrels selected by Alexandre Gabriel then made the sea voyage to Javrezac, in the Charente region of France, where the rum was aged for an additional year in Maison Ferrand French oak casks. In the Plantation signature style, this double ageing technique highlights the very expressive and complex appeal of this 14-year-old Australian rum. Its assertive personality perfectly reflects the richness of the Australian terroir and the savoir-faire of the makers at Beenleigh Artisan Distillery. was then treated to an additional one-year ageing period in Javrezac, in France’s Charente region, in 400-liter French oak barrels from Maison Ferrand.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Puntacana Club Ron Muy Viejo 37,5%', 'https://www.uhrskov-vine.dk/puntacana-club-ron-muy-viejo-37-5pct', 249, TRUE, NULL, 37.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/u/puntacana-club-ron-muy-viejo.jpg', 'Puntacana Viejo er en blanding af rom i alderen 7, 8 og 12 år fra Oliver & Oliver. Modnet på Solera metoden, den har en intens gylden farve. Smuk aroma med noter af eg og en sød cremet finish. Rommen går gennem en afsluttende aldring i brugte egetræ Sherrys tønder fra tre til seks måneder. Oliver og Oliver producerer nogle vidunderligt sødt, fyldig rom i en traditionel cubansk stil, de får deres lagre af destilleret rom fra Trinidad og Tobago, og Panama.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Origins No. 3 Guyana DLR, 60%', 'https://www.uhrskov-vine.dk/wild-series-origins-no-3-guyana-dlr-60', 649, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/wsoriginguyana3.png', 'Må vi præsentere Wild Series Rum Origin No. 3 Guyana Vi har her at gøre med nogle helt specielle hvide rom som er udvalgt pga. deres fantastiske smagsprofil. I dette tilfælde er det en rom fra Guyana som altid har haft en stor plads i vores hjerter. Guyana DLR er en rom som er produceret på en MPRS Metal Kolonne kedel på Diamond destilleriet i Guyana. en meget lækker blød. Rommen er ulagret og destilleret ret kort tid inden den er tappet på flaske. Velegnet til at nyde ren, men er også helt fantastisk til cocktails   Fakta: Guyana Unaged 1. Batch Distilled 2022 At Diamond Distillery Marque DLR Strength at 60% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 42 Trinidad 20 års Single Cask 63,10%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-42-trinidad-20-single-cask-63-10-rom-deluxe', 1495, TRUE, NULL, 63.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws42trinidad.jpg', 'Wild Series rum no. 42 kommer fra Trinidad Distillers Limited. Denne gang er det en 20 år gammel rom, som er baseret på Melasse og lagret i Ex. Bourbon fade. Den har lagret både tropisk og kontinentalt. TDL er kendt for deres smagfulde rom som ofte nævnes som en ''mini Caroni'' på grund af de typiske tunge noter som en del af disse rom har. Smagsnoterne i denne rom er egetræ, grønne stikkelsbær, vanilje, fusel og en lang aromatisk eftersmag. En virkelig spændende rom som gør sig godt sammen med et stykke mørk chokolade.  Fakta: Trinidad Single cask                                                                                              Distilled May 2002 At Trinidad Distillers Ltd. Bottled Jan. 2023 Aged in Ex. Bourbon cask Tropical & Continentally aged Marque TML Barrel No. 21 246 bottles Cask Strength at 63,1% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Fiji Vintage 2004, Limited Edition 50,3%', 'https://www.uhrskov-vine.dk/plantation-fiji-vintage-2004-limited-edt-50-3', 749, TRUE, NULL, 50.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation2004fijibox.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Fidelitas 20 års Single Blended Rum, Foursquare / Velier 55%', 'https://www.uhrskov-vine.dk/foursquare-fidelitas-20-single-blended-velier', 2249, TRUE, NULL, 55, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/i/fidelitas.png', 'Fidelitas er det nyeste skud på stammen i serien af ultra-eftertragtet rom lavet i samarbejde mellem Foursquare Distillery og Velier. Dette års release er nummer 10 i serien, og den er den hidtil ældste med hele 20 års tropisk lagring: de første 19 år ligger den på bourbonfade, efterfulgt af 1 år på marsalafade. Den er tappet ved 55% i blot 2.160 eksemplarer.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes TEN CANE PING 15, Trinidad Rum, 61,7%', 'https://www.uhrskov-vine.dk/cdi-ten-cane-ping-15-trinidad-61-7', 1499, TRUE, NULL, 61.7, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Hvis du ikke har hørt om Ten Cane, så bebrejder vi dig ikke, for det er der ganske få, der har. Men mon ikke denne imponerende rom snart er på alles læber – bogstaveligt talt. Vi har fundet fadet (eller er det omvendt?) via den franske aftapper Compagnie des Indes, som skriver følgende om Ten Cane: “The Ten Cane distillery was created by LVMH [Louis Vuitton Moët Hennesy] to produce pure cane juice pot still rum for the US market. The brand never really found its audience, the multinational decided to tear down the distillery only a few years after its grand opening. You will have understood that the distillery is now closed and thus its rums are very rare pot still rums 100% pure cane juice (Agricole style).” Selvom rommen vandt hardcore fans i en lille skare af romnørder, var markedet overordnet set ikke klar til 10 Cane. Det skal vi love for, at det er i dag.Efter 10 år på bourbonfad er der sket noget meget smukt med denne Ten Cane, som selvfølgelig er tappet ved fadstyrke og uden tilsat sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Guyana 2001 Skeldon Rom 53.2%', 'https://www.uhrskov-vine.dk/sbs-guyana-2001-skeldon', 1199, TRUE, NULL, 53.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_guyana_2001.jpg', 'S.B.S Guyana 2001 er fra et enkelt fad med et udbytte på kun 178 flasker. Rommen er baseret på melasse og destilleret på et af DDL`s kolonne still i 2001. I februar 2021 blev rommen tappet på vores lager i Danmark uden brug af koldfiltrering eller nogen form for tilsætningsstoffer. SWR eller Skeldon William Ross er et rum mark, DDL har arvet fra det gamle Skeldon Sugar Estate. Skeldon er i dag et af de mest legendariske rum marks, og vi er meget stolte over at bringe jer denne aftapning.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Formidable St. Lucia Rum, 40%', 'https://www.uhrskov-vine.dk/admiral-rodney-formidable-rum-40', 695, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/formidable.png', 'RUM BLEND : Admiral Rodney Formidable contains rums pulled exclusively from the lowest portion of the Coffey still possible resulting in a much heavier and more flavorful rum. These rums are then aged from 10-15 years in previously used Bourbon casks and expertly blended.  TASTING NOTES:  Intense dark golden color with a nose of wonderful honeyed raisin fruit, spiced and vanilla. A complex palate of luscious sweet sultans fruit balanced with a toasty oak. Long finish to leave a lasting impression of the brilliance of great rum.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rum 10 år Gaveæske m. 2 glas', 'https://www.uhrskov-vine.dk/malteco-rum-10-aar-gaveaeske-m-2-glas', 269, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/maltecomglas.png', 'Denne rom er fra Panama og bliver produceret af de samme, som laver Ron Zacapa. Alene dét gør, at man sætter forventningerne rimelig højt, inden man trækker proppen op at den aflange, mørke flaske. De høje forventninger bliver dog heller ikke gjort til skamme, for dette er en yderst spændende og lækker rom. Den har en smuk farve med mørke ravgyldne refleksioner. Duften er med noter af vanilje, søde regnskovsblomster og ædle fadtoner. Smagen har en god fedme med hints af vanilje, rørsukkersirup, mælkechokolade, orange, rosin og fudge.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 22 Barbados 20 års Single Cask Rum Batch 1 56%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-22-barbados-20-single-cask-batch-1-56-553', 3495, TRUE, NULL, 56, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/batch1.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('National Rums of Jamaica Cambridge STCE 2010 12 års Jamaica Rum 57%', 'https://www.uhrskov-vine.dk/national-rums-jamaica-stce-2010-12-57', 1569, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/cambridge2010.jpg', 'Denne rom er en reproduktion af STC♥E-mark fra Cambridge-destilleriet, beliggende i Trelawny Parish og lukket i 1947. Denne blev destilleret ved Long Pond i 2010. Continental Flavored-stilen er en af de fire klassifikationer, der bruges i Jamaica, som identificerer rom med 550 - 1600 gr/hlpa estere på tidspunktet for destillation. STC♥E-mark er forkortelsen af Simon Thompson Cambridge Estate og refererer specifikt til rom med 550 - 700 gr/hlpa. Efter 12 års lagring, fuldt ud i det tropiske klima, er Angel''s Share > 55%. Kun 4900 flasker produceret og tappet ved 57% vol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Opthimus 25 år Solera Oporto Finish, Den Dominikanske Republik, 43%', 'https://www.uhrskov-vine.dk/opthimus-25-solera-oporto-43', 799, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/o/p/opthimus25.jpg', 'En spændende spiritus fra Oliver & Oliver, der med base i Den Dominikanske Republik, opkøber rom i Caribien, for at blande den på bedste vis. Det er en hemmelighed, hvilke romdestillater, der indgår i de forskellige blends. Det er dog ikke nogen hemmelighed, at en stor del af destillaterne stammer fra Cuba, hvor Oliver familien har sine rødder, og også havde et romdestilleri i slutningen af det 18. århundrede. Da de grundlagde firmaet, fik lov til at købe omkring 100.000 liter god cubansk rom. Den øvrige destillater er fra Panama, Trinidad, Colombia og Nicaragua, men en stor del kommer også fra deres egen ø, Den Dominikanske Republik. Denne 25 årige spirit drink er lagret på amerikanske egetræsfade, hvor den tilegner sig en god harmoni og stor kompleksitet og derefter afsluttes modningen i fade, hvor der tidligere været portvin i. Duft Tørrede frugter, kanel, honning/sødme Smag Sød, krydret. Balance Eftersmag Portvinens sødme, krydret fad - Harmonisk afslutning Kommentar Fantastisk “ægteskab” mellem spirit drink og portvin. Det bedste af to verdener.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2008 Trinidad & Tobago 50%', 'https://www.uhrskov-vine.dk/la-maison-rum-2008-trinidad', 549, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2008-trinidad.jpg', 'På den lille Caribiske ø Trinidad og Tobago, en af de oprindelige fødesteder for rom, stammer kulturen af sukkerrør tilbage fra1700-tallet. Selvom øen oprindeligt blev koloniseret af Spaniere og derefter Englanderne, forbliver nationen tro mod sin britiske arv ved at producere traditionel rom, der er destilleret på kolonne stills. Den fremragende sukkerrør “eaude-vie” har gjort Trinidad og Tobago til en af de mest ansete destillatører af fin rom…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kill Devil Trinidad 13 år, Single Cask Rum 46%', 'https://www.uhrskov-vine.dk/kill-devil-trinidad-13-ar-single-cask-rum-46', 599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/i/kill-devil-trinidad-13yo_2.jpg', '13 års lagret rom destilleriet i Trinidad. Denne udgivelse er tappet fra et enkelt fad og aftappet på 46% af Hunter Laing for deres “Kill Devil” serie. Kun 373 flasker blev produceret af denne hæsblæsende Trinidad rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Guyana 2003 Giftbox 4 bottles Rom 52,1%', 'https://www.uhrskov-vine.dk/sbs-guyana-2003-giftbox-rom', 2299, TRUE, NULL, 52.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_guyana_4_stk._dansk.jpg', 'Denne 4 stk. æske er den store finale i 2021 frigivelsen fra marts, hvor vi har samlet de 4 mest  populære hits fra Guyana i én smagsæske. Dette giver folk mulighed for at prøve de forskellige rom side om side, uden at skulle købe de store flasker. Sættet indeholder følgende varianter; 1990 Port Mourant (PM), 1994 Enmore (REV), 2001 Skeldon (SWR) og Savalle (SVL) fra 2003. Alle er farvet med karamel, fra det tidspunkt, de er lagt på fad og modnet i ex bourbon-fade. Disse 4 varianter er et glimt ind i de klassiske mørke demerara-rom, der er blevet værdsat over hele verden gennem generationer.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 15 Enmore 33 års Single Cask Rum Batch 2 48,2%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-15-enmore-33-single-cask-rom-de-luxe-batch-2', 2795, TRUE, NULL, 48.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/n/enmoreb2.png', 'Der er tappet to fade af Wild series no. 15. da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2 Denne helt særlige aftapning kommer fra Versailles kedlen som er den eneste tilbageværende enkelte potstills kedel der er lavet i træ, og som stadig fungerer. Rommen er destilleret i 1988, mens kedlen stadig stod på Enmore destilleriet. Destilleriet blev lukket i 1994 og kedlerne er senere endt på Demerara destilleriet. I denne rom får man en virkelig blød og varm rom. Noterne er grundet den ekstreme alder, kraftige og intense.  Her er noter af Blomme, brændt karamel, mørkt brunt sukker, tørret frugt, tobak og masser af træ.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 2 Batch 2, Diamond 25 års Rum, 50,8%, RomDeluxe', 'https://www.uhrskov-vine.dk/diamond-25-collectors-series-rum-no-2-batch-2', 1495, TRUE, NULL, 50.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diamondbatch2.png', 'Der er tappet to fade af Collectors series rum no. 2. Da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2. Denne helt særlige aftapning kommer fra Diamond destilleriet.  Den er melassebaseret og og kolonnedestilleret på en Diamond metal Coffey still.  I denne rom får man et rigtigt spændende glas. Duften er fyldt med syltede blommer og tørret frugt I munden får man mørk chokolade, jasmin blomster, tørret frugt, melasse, lakrids og brændt træ.  En intens og powerfull rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distillery Edition 2021 Old Pure Single Jamaican Rum, 55%', 'https://www.uhrskov-vine.dk/hampden-great-house-distillery-edition-2021-55', 1199, TRUE, NULL, 55, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampdengreathouse.png', 'Indtil begyndelsen af ​​det 20. århundrede opbevarede Hampden-destilleriet sine fade i "Great House", hvor de ventede, før de blev sendt til Europa eller Amerika. Udgivet hvert år og kun tilgængelig på selve destilleriet og på udvalgte markeder, Great House er en limited edition aftapning, der hylder dette legendariske palæ, som er en del af destilleriets historie og arv. Blendet har forskellige mærker og årgange, der udvikler sig med hver årlige udgave. Hver ny blanding har til formål at fremhæve et andet aspekt af den rige og mangfoldige Hampden-aromatiske profil. 2021-udgaven er en blanding af mellemstore og høje ester marks, der afslører en livlig og intens profil, der hænger ved, med noter af hvide frugter og blomsteraroma. Farve : Klar Gylden. Duft : Livlig og smooth. Kandiseret citrus, moden banan, lychee, kiwi, rabarber og vanilje. Smag : Intens og medicinsk. Noter af Tobak, ensianrod, saltkaramel, frysetørrede hindbær og kirsebær. Serveringsforslag : Bør nydes rent. Evt. med et par dråber vand.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate HLCF Classic Pure Single Jamaican Rum 60%', 'https://www.uhrskov-vine.dk/hampden-estate-hlcf-classic-pure-single-jamaican-rum-60', 699, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/l/hlcf.jpg', 'Hampden Estate HLCF er klassisk Jamaica-rom, når det er bedst! Ung (men tropisk lagret), potent og rimelig høj på esters.  Farve : Gylden. Duft : Mentol, grillede bananer, citrusskaller og acetone. Smagsnoter : Masser af power, tropisk frugt og kandiseret citron. Serveringsforslag : Nydes rent eller i cocktails.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2011 Mount Gay Barbados Pure Single Rum 52,3%', 'https://www.uhrskov-vine.dk/habitation-mount-gay-2011-barbados-52-3', 995, TRUE, NULL, 52.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/5/m57340.jpg', 'Efter udgaverne af Last Ward 2007 og 2009 kommer nu denne Habitation Velier i en ny vintage (2011) fra Mount Gay-destilleriet på Barbados. Denne aftapning giver blomster- og wienerbrødnoter fra rums bajans (Barbados), og dens 52,3% giver det en rig og kompleks profil.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Jamaica 7 år Cask Strength Rom 61,2% (2018)', 'https://www.uhrskov-vine.dk/rum-nation-jamaica-yo-cask-strength', 499, TRUE, NULL, 61.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum_nation_cask_strenght_7.jpg', 'Rum Nation Jamaica 7 års cask strenght er en sand ester bombe fra Jamaica. Aftapningen er tappet ved fadstyrke på hele 61,2% alkohol og viser klassisk Jamaica karakter med tunge esterholdige aromaer af gæret frugt, peber, kanel, nelliker samt medicinske urter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Fiji Vintage 2005, Spring 2020 15 år 50,2%', 'https://www.uhrskov-vine.dk/plantation-fiji-vintage-2005-spring-2020', 699, TRUE, NULL, 50.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-fiji-vintage-2005-spring-2020.jpg', 'Fiji har på få år fået nærmest stjernestatus blandt romnørder. Den aromatiske og intense stil er guf for fans af Jamaica, Guyana og Trinidad-rom, og det nyeste skud på stammen af Plantations Vintages er netop en forrygende Fiji fra 2005. Rommen er lagret 14 år på bourbonfade i Fiji, før 1 år på franske fade hos Ferrand i Cognac. Den er tappet ved 50,2% med en lille smule tilsat sukker – omtrent 4 gram per liter…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Jamaica 1994 New Yarmouth Rom 57%', 'https://www.uhrskov-vine.dk/sbs-jamaica-1994-new-yarmouth', 1899, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_jamaica_1994.jpg', 'S.B.S Jamaica 1994 er en enkelt fad aftapning med i alt kun 308 flasker. Rommen kommer fra destilleriet New Yarmouth på Jamaica og er baseret på melasse. I 1994 blev rommen destilleret i kolonne stills og tappet på vores lager i Danmark i februar 2021. Rommen har lagret i et ex-Bourbon fad. Som almindelig praksis for vores Single Barrel Selection rom, er det gjort uden brug af koldfiltrering.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 16 Martinique 13 års Single Cask Rum Batch 2 59%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-16-martinique-13-single-cask-batch-2-59', 995, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/martiniquebatch2.png', 'Der er tappet to fade af Wild series rum no.16. da disse ikke er helt ens, er de aftappet som Batch 1 og Batch 2 Denne helt særlige aftapning kommer fra Destillerie du Simon, som er kendt for at producere rom til flere store brands. Her er Clement nok det mest kendte af disse, men også A1710 får deres rom derfra. Den er basereret på frisk sukkerrørs juice og er dermed den første rom af agricole typen vi lancerer i Wild series rum. Her er tale om en rom med alle de tyspiske friske noter som er så fascinerende ved agricole rom. I næsen er der noter af friske sukkerrør, grønt græs og hø. I munden får man hint af grønne æbler, peber, vanilje, sukkerrør, milde frugtige noter og en smule træ.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 3 Batch 2, Bellevue 23 Års Rum, 56,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/bellevue-23-collectors-series-rum-3-1-romdeluxe-55-377', 1395, TRUE, NULL, 56.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/bellevuebatch2.png', 'Denne rum er destilleret på Bellevue destilleriet. Destilleriet ligger i hjertet af den største sukkerrørs plantage på øen Marie Galante i Guadeloupe. Godset Bellevue au Moule og deres destilleri blev etableret i slutningen af 1800 tallet. Deres berømte vindmølle er bygget tilbage i 1821. Bellevue er i øvrigt det første destilleri i Caribien som har forpligtet sig til at beskytte miljøet ved at have en 100% ikke forurenende produktionsproces. Rommen er en yderst sjælden gammel aftapning på hele 23 år Det er en single cask aftapning af ren kolonne destilleret rom, baseret på melasse. Den er lagret/modnet både tropisk og kontinentalt i bourbon fade, hvor der ikke er tilsat hverken farve eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 5 år Hampden 2016 Jamaica Pure Single Rum 62%', 'https://www.uhrskov-vine.dk/habitation-velier-5-hampden-2016', 1099, TRUE, NULL, 62, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 22 Barbados 20 års Single Cask Rum Batch 3 54,8%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-22-barbados-20-single-cask-batch-1-54-8-554', 3495, TRUE, NULL, 54.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/batch3.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pretty Maids 7 Deadly Sins, No. 1 Lust Rum 40%', 'https://www.uhrskov-vine.dk/pretty-maids-7-deadly-sins-rom', 599, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/pretty-maids-7-deadly-sins-rom.jpg', 'Pretty Maids første rom i serien "7 Deadly Sins" Nr. 1 "Lust" er ren rock & roll på flaske. Denne blend er bestående af rom mellem 5 og 15 år gammel. Utrolig flot og velsmagende rom. Et blend af de fineste og lækreste rom fra nogle af Caribiens dygtigste romproducenter fra bla. Trinidad, Jamaica, Barbados og Guyana. Smagen er dyb, fyldig og blød, fuldstændig som Ronnies stemme, men stadigvæk med en kant af en lang og karakterfuld eftersmag, nøjagtigt som Hammer''s guitarspil. Kompleks krydret duft af karamel, mørk chokolade og lakrids.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Vintage 2013, Limited Edition 50,2%', 'https://www.uhrskov-vine.dk/plantation-barbados-vintage-2013-limited-edition-50-2', 599, TRUE, NULL, 50.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationbarbados2013.png', 'Endnu en flot tilføjelse til Plantation-serien af limited editions med tilnavnet "Under the Sea". Glæd dig til at opleve den nye Plantation Barbados Vintage 2013 fra West Indies Rum Distillery. Fremstillet på melasse, fermenteret i 2-3 dage og derefter destilelret delvis på kolonne of Gregg pot still i 2013. Herefter 8 års lagring i tropisk klima på 200 L bourbon-fade, efterfulgt af 1 års finish i Europa på 400L Ferrand-fade. Dosage er 2 g/L og rommen er flasken ved 50,2 ABV uden tilsætning af karamelfarve eller E150a.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Depaz Vieux Agricole XO Grande Reserve Rhum, Martinique 45%', 'https://www.uhrskov-vine.dk/depaz-vieux-agricole-xo-grande-reserve-rhum-martinique-45', 975, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/e/depaz-vieux-xo_2.jpg', 'Med mere end 12 års fadlagring indeholder denne helt specielle rhum alle de aromaer, som en kræsen rhum-elsker søger. Den har en helt fantastisk balance mellem sødme, fadtoner og det meget bløde udtryk, som den lange fadlagring har bidraget med. Ganske enkelt et KANON glas rhum.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico "Suitcase" 12 år Rum Venezuela 40%', 'https://www.uhrskov-vine.dk/diplomatico-suitcase-12-ar-rum-venezuela', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diplomatico-suitcase_2.jpg', 'Guldmedalje - Ministry of Rum Tasting Competetion 2007 ★★★★★★, 93 Point & Bedste Rom - Ekstra Bladet Diplomatico Rom i "suitcase." Diplomatico 12 års er en en fabelagtig mørk gylden rom fra Venezuela. destilleret i kober potstills og derefter 12 års lagring. Diplomatico er en fyldig, sød go frugtig rom. Super kvalitet til pengene!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2011 Peru 48%', 'https://www.uhrskov-vine.dk/la-maison-rum-2011-perou', 549, TRUE, NULL, 48, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2011-perou.jpg', 'Det mere end hundrede år gamle destilleri Millonario, ligger i den nordlige Peru. De bruger melasse fra sukkerrør, dyrket i den vulkanrige jord, til at fremstille denne delikate rom. Som det ofte ses i Sydamerika, bliver rommen lagret efter Solera metoden. Denne aftapning blev valgt til samlingen af La Maison du Rhum, som igennem serien, genforener ekstraordinære produkter fra de mest anerkendte destillerier i deres respektive lande…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2011 Salvador 40%', 'https://www.uhrskov-vine.dk/la-maison-rum-2011-salvador', 549, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2011-salvador.jpg', 'Det lille land El Salvador, der ligger mellem Honduras og Guatemala, nyder et tropisk klima og en vulkansk jord, der gavner dyrkning af sukkerrør. Maja rom er lavet på melasse og bliver destilleret på en kolonne still. Når rommen hældes på fad, har den en alkoholprocent mellem 78% og 98%. Efter lagring på egetræsfade, bliver rommen vandet ned til 55% - 75%, inden den flaskes. Manden bag destilleriets blends er den cubanskfødte Don Pancho Fernadez, som er verdenskendt for sin erfaring og ekspertise…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 50 Anniversary Edition, Guyana Single Cask 56,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-50-guyana-single-cask-56-9-rom-deluxe', 1549, TRUE, NULL, 56.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws50.png', 'Denne rom er vores jubilæumsudgave i wild serien. Det er nr. 50 i rækken af wild Series-rom, som startede med den første, der blev frigivet på Nordic Rumfest i København den 1. juni 2019. At være nr. 50 i en serie af rom kræver noget særligt. Derfor har vi gemt denne tønde med Marque MDK, som er destilleret på det berømte træpotstill kaldet Versailles. Faktisk har denne rom et destillerimarque kaldet KFM, som ikke produceres på destilleriet længere. Det er en rom med en fantastisk karakter, som passer perfekt til at være vores jubilæumsrom. Smagsprofilen er fantastisk rund og blød, uden de megat markante brændte trænoter som er kendetegnet for de gamle KFM aftapninger. Den ultimative sipperom. Fakta: Based on Molasse Distilled may 2003 At Diamond distillery Bottled oktober 2023 Marque MDK Continental aged Aged in Recycled rum barrels Cask no. 31 254 bottles Cask Strength at 56,9% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Cueva 1501 Sistema 12 Solera Panama Rum 40%', 'https://www.uhrskov-vine.dk/ron-cueva-1501-sistema-12-solera-panama-rum-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/u/cueva12.png', 'I denne Panama Rum 12 Solera fra Ron Cueva 1501 finder du en perfekt afbalancerede rom. Lagret op til 12 år i solera system, forenes smagen af friske frugtige citrus noter, med fyldige noter af chokolade, kaffe og karamel. Masser af dybde og kompleksitet mellem sødme og alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden 2010 CH Jamaica Pure Single Rum Habitation Velier 68,5%', 'https://www.uhrskov-vine.dk/hampden-2010-ch-velier-habitation-68-5', 1395, TRUE, NULL, 68.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/5/m57339.jpg', 'Det er blevet en "god" vane at finde vintage Hampden i Habitation Velier-serien, da de formår at få en samhørighed mellem intensitet og aroma på et yderst højt niveau. Denne "C H" fra 2010 er ingen undtagelse og udtrykker de funky egenskaber ved Trelawny-destilleriet med en højt esterniveau og stadig mere udtalt aroma: ristet tropisk frugt, rørsukker. kogt, bourbon vanille og antydninger af krydderier', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Privateer 2017 New England Pure Single Rum Habitation Velier 55,6%', 'https://www.uhrskov-vine.dk/privateer-2017-new-england-habitation-velier-55-6', 899, TRUE, NULL, 55.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/-/p/-privateer-2017-habitation-velier-556.jpg', 'Privateer er et destilleri fra staten Massachusetts i USA, der har gjort gennemsigtighed sin credo. Denne 2017-vintage minder om nogle af de store rums af Barbados og har forskellige aromaer af vanilje, nødder og varmt smør.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Lamb''s Navy Rum 40% 100cl', 'https://www.uhrskov-vine.dk/lambs-navy-rum-100cl', 239, TRUE, 100, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/lambs_1.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes 13 Års Guyana Diamond Sherry Wood Rum, 57,2%', 'https://www.uhrskov-vine.dk/cdi-guyana-diamond-sherry-wood-57-2', 699, TRUE, NULL, 57.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50640923.jpg', 'BOTTLED FOR DENMARK. Compagnie des Indes Guyana Diamond Sherry Finish er en single cask-rom tappet udelukkende til det danske marked. Den kommer fra ét af verdens mest legendariske destillerier, Diamond Distillers, i Guyana. Den franske aftapper, Compagnie des indes, har nøje overvåget den afsluttende lagring, som er foregået på et sherryfad. Det har haft en profund, men meget klædelig effekt på rommen, som kombinerer stor Guyana-power med let sherrysødme. Rommen er tappet ved 57,2% uden tilsat sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Daddy''s Rum Carribean Blend XO, 40%', 'https://www.uhrskov-vine.dk/daddys-rum-carribean-blend-xo', 349, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/daddysrum.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes 14 Års Barbagaya Small Batch Destillery Rum, 43%', 'https://www.uhrskov-vine.dk/cdi-14-barbagaya-small-batch-destillery-43', 699, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdibarbagaya.png', 'Som du måske har gættet ud fra navnet, er aftapningen Barbagaya en blanding af rom fra Barbados og Guyana. Det er 3. gang, Compagnie des Indes laver sådan et ”small batch” blend (Dominidad og Veneragua var de første) – og de bliver bedre og bedre! Her er det ét fad fra Barbados og ét fra Guyana, begge fyldt i april 2007 og lagret delvist i tropisk klima og delvist (40%) kontinentalt, som er blandet og efterfølgende tappet ved 43% alkohol uden kølefiltrering.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Panama Vintage 2008, Limited Edition 45,7%', 'https://www.uhrskov-vine.dk/plantation-panama-vintage-2008-limited-edition-45-7', 599, TRUE, NULL, 45.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantationpanama2008.png', 'Release: 26/10 Første aftapning af Plantation''s nye "Sea"-serie.  Vi har netop sagt farvel til den sidste rom i Plantations ”Bird”-serie, og kan med denne Plantation Panama 2008 tage hul på den 1. aftapning i deres nye ”Sea”-serie. ”Sea”-serien vil fremadrettet, når de alle er samlet ved siden af hinanden, skabe et sammenhængende marine-motiv. Plantation Panama 2008 er destilleret på ”Alcoholes del Istmo” i Panama, hvor den også har ligget 12 år på Bourbon fade, inden den har fået det sidste år på Pierre Ferrand cognac fade. Den er tappet ved 45,7% og uden nogen tilsætning af sukker. Destilleret på ”Alcoholes del Istmo” i Panama, hvor den også har ligget 12 år på Bourbon fade, inden den har fået det sidste år på Pierre Ferrand cognac fade. Den er tappet ved 45,7% og uden nogen tilsætning af sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 9, Belize 8 års Rum, 60%, RomDeluxe', 'https://www.uhrskov-vine.dk/belize-8-collectors-series-rum-no-9-romdeluxe-60', 695, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/belizerdl.png', 'Collectors Series Rum No. 9 Belize er en lækker kolonne destilleret rom fra det meget anerkendte destilleri Travellers.  Vi har flere gange tidligere stiftet bekendtskab med rom herfra. F.eks. er vores Wild Series rom nr. 4 fra dette destilleri. Dennegang er rommen 100% continentalt lagret i et 130 L PX sherryfad. Det har givet rommen en sødmefuld smag med masser af tørret tropisk frugt, rosiner, appelsinskal og chokolade.   Fakta: Travellers Distillery Based on Molasse Distilled in column still Continental ageing Aged In 130 L. PX Sherry cask Cask no. 560 Bottled March 2022 1 of 182 bottles 59,1 % ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Stroh Punsch, Der Klassiker, Austria 30%', 'https://www.uhrskov-vine.dk/stroh-punsch-70cl', 169, TRUE, NULL, 30, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/t/stroh-punch.jpg', 'STROH Rum Punch skylder sin unikke og umiskendelige smag til en speciel ingrediens: STROH Inländer Rum. Når det blandes med varmt vand, kan det tilberedes på ingen tid, hvilket giver en dejlig fornøjelse på kolde dage.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Origins No. 5 Guadeloupe, 60%', 'https://www.uhrskov-vine.dk/wild-series-origins-no-5-guadeloupe-60', 649, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guadeloupe.png', 'Wild series rum origin er en serie håndplukkede, ulagrede rom, der er særligt udvalgt på grund af deres kraftige smagsprofil. Denne rom kommer fra Montebello Distillery og er baseret på sukkerrørsjuice i fransk romstil.  Rommen kan nydes ren eller i fantastiske cocktails. Fakta Guadeloupe 1. Batch Distilled 2023 At Montebello Distillery Unaged Based on sugarcane juice Cask Strength at 60% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distillery Edition 2024 Old Pure Single Jamaican Rum, 57%', 'https://www.uhrskov-vine.dk/hampden-great-house-2024-57', 1099, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50643808-hampden-great-house-distillery-edition-2024.jpg', 'Hampden Estate Great House er en rom fra et af Caribiens vigtigste og ældste destillerier. Hos Hampden produceres rom, som ikke har sin lige noget andet sted i verden! Enormt kraftig, intens og frugtig, med den blandt romnørder så populære funky karakter. Denne særlige udgave er en officiel aftapning fra destilleriet, distribueret af La Maison du Whisky og Velier , som frigives én gang om året: 2024 er den sjette udgave. Den er lagret på bourbonfade og tappet ved 57% alkohol. Lyden af navnet ”Velier” får en helt særlig følelse frem hos romnørder. Gang på gang formår masterminded bag firmaet, Luca Gargano, at chokere og henrykke romverdenen med udgivelser der sætter nye standarder for kvalitet, gennemsigtighed og nørderi. Veliers ry for exceptionel kvalitet cementeredes allerede i ’00’erne med en perlerække af kompromisløse demerara-rom. Disse flasker er i dag højdemålet af kultrom og skifter ejere for astronomiske summer på spiritusauktioner verden over. Senere er firmaet blevet kendt for tropisk lagret Caroni, en særegen rom fra et nu lukket destilleri på Trinidad, med noter af røg, tjære og bacon. En ”acquired taste”, men når først du har den… Sammen med Foursquares Richard Seale er Luca standhaftig (og højlydt) modstander af tilsætningsstoffer eller fusk med aldersbetegnelser, og derfor sætter Veliers nyeste serie af rom, Habitation Velier, gennemsigtigheden i højsædet. På etiketten blotlægges stolt enhver detalje om produktionen, lige fra ”angel’s share” til ester-indhold.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Fiji 2002 South Pacific Rom 57,1%', 'https://www.uhrskov-vine.dk/sbs-fiji-2002-south-pacific', 1199, TRUE, NULL, 57.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs_fiji_2002._dansk.jpg', 'S.B.S står for Single Barrel Selection. S.B.S. Fiji 2002 rom er destilleret på Pot still, på South Pacific Distillery. South Pacific Distillery formår at producer rom, som smager frugtig, esterfuld, ”røget”, medicinsk og vild. South Pacific Distillery var også repræsenteret, med en af 3 rom, ved vores første lancering af SBS. Nu bare i en 18 år gammel udgave. Rommen har lagret i ex bourbonfade, og er tappet ved fadstyrke. 240 flasker er der blevet af dette fad.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 4 år Mhoba 2017 South African Pure Single Rum 64,6%', 'https://www.uhrskov-vine.dk/habitation-velier-4-mhoba-2017', 899, TRUE, NULL, 64.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/h/mhoba.png', 'Mhoba 2017 er resultatet af partnerskabet mellem Luca Gargano, præsident for Velier og Robert Greaves, grundlæggeren af ​​Mhoba.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes 14 Års Guyana Armagnac Cask Finish Rum, 61,2%', 'https://www.uhrskov-vine.dk/cdi-14-guyana-armagnac-cask-finish-61-2', 899, TRUE, NULL, 61.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdiguyanaarmangac.png', 'Demerara-rom lagret på armagnac-fade er usædvanligt, men aftapperen Compagnie des Indes er jo fransk, så hvis nogen skulle gøre det, må det være Florent og  Compagnie ! Inden de 36 måneders  affinage  på armagnac-fadet, har rommen ligget på bourbonfad i 11 år. Den er tappet ved 61,2% uden tilsat sukker eller kølefiltrering. Fadet, som havde nummer GDA61, gav i alt 479 flasker og selvom det ikke står på etiketten, er den tappet udelukkende til det danske marked!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin 2020 Ansyen Communal 49,3%', 'https://www.uhrskov-vine.dk/clairin-ansyen-communal-49-3', 499, TRUE, NULL, 49.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/l/clairinansyencommunal.png', 'Clairin Communal Ansyen er en helt særlig rom fra Haiti.  Clairin  er en traditionel rom-stil, som ikke har sin lige noget andet sted i verden. Dette er en blanding af Clairin fra fire forskellige destillerier i henholdsvis Barraderes, Cavaillon, Pignon og St. Michel de l’Attalaye, alle lavet med økologisk dyrkede sukkerrør, fermenteret med naturligt forekommende gær og destilleret på pot stills.  Ansyen- udgaven er lagret på egetræsfade, både romfade (fra bl.a. Caroni, Bielle og Mount Gay) og whisk(e)y-fade (fra bl.a. Buffalo Trace, Widow Jane og BenRiach). Til sidst er den tappet ved 49,3% alkohol, uden tilsat farvestof eller sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 15 år Rare Rums 2003-2018 Diamond Rom 58%', 'https://www.uhrskov-vine.dk/rum-nation-15-aar-rare-rums-2003-2018-diamond-rom-58', 999, TRUE, NULL, 58, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/rom04411_-_rr_diamond_2003-2018_15_yo_med_box.jpg', 'Rum Nation Rare Rums mål er at præsentere stilarter, med et særligt fokus på forskellene mellem de forskellige geografiske produktionslandes unikke kvaliteter og aromaer. Tiderne ændrer sig - kendere kræver mere viden om hver flaske: destillerinavn, styrke, blandingsforhold, lagringsform og fadtyper. Kravet er at flere og flere rom skal være ”anderledes”, udover at være af højeste kvalitet fra øverste hylde. Hver udgivelse af Rum Nation Rare Rum, er en small batch-aftapning med individuelt nummererede flasker og destillerinavn. For at fejre denne nye serie har vi også designet en frisk stil til flaskerne med en elegant glasstop i stedet for den sædvanlige kork. Minimalt og klassisk design til etiketterne og et nyt rør til en elegant gavepræsentation. Diamond 15 år - Guyana 58% En særdeles ren og tør rom fra Diamond Distillery i Britisk Guyana, som fuldt ud bevarer destillatets elegante, lækre, medicinske og pebrede karakter, uden alt for stor indflydelse fra egetræsfadet. Alt takket være dens langsomme modning i et kontinentalt klima. For yderligere at forbedre den delikate side af smagen, får den lov til at modne de sidste 14 måneder i fade fra en af de blideste og mest duftende Speyside-maltwiskyer i Skotland.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana Vintage 2007 Limited Edition, 51%', 'https://www.uhrskov-vine.dk/plantation-guyana-vintage-2007-bottled-2022-51', 749, TRUE, NULL, 51, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50641191.jpg', 'Endnu en glimrende Guyana-rom fra Plantation – denne gang destilleret i 2007 (bl.a. på den legendariske Port Mourant pot still) og tappet i 2022 efter 15 års lagring. De første 13 er foregået i tropisk klima på bourbonfade, og de sidste 2 i kontinentalt klima på franske fade som det er kutyme hos Plantation. Den er tappet ved 51% alkohol, og er hverken tilsat sukker eller farvestof. En flot tilføjelse til serien af limited editions med tilnavnet Under the Sea.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 15, Jamaica 17 års Rum, 54,4%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-15-jamaica-54-4-rom-deluxe', 995, TRUE, NULL, 54.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaica15_boks.jpg', 'Her er tale om en fantastiks Jamaica rom fra et destilleri vi ikke må nævne navnet på. Det er en rom som er rund og fynky i sit udtryk, den er potstills destilleret på en Forsyth Potstill, som er med til at give den sit meget smagfulde udtryk. I denne rom er der ægte Jamaican funk, sammen med noter af tørret frugt, overmodne bananer, læder, jod, kandis og ikke mindst krydderier. Fakta: Jamaica Single cask                                                                                              Distilled Aug. 2005 At Secret Distillery Bottled Oct. 2022 Marque JMWP Aged in Ex. Bourbon cask Cask no. 19 Continentally aged 252 bottles Cask Strength at 54,4% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados 2015 6 års Single Cask Rum, Bottled for Uhrskov 47%', 'https://www.uhrskov-vine.dk/plantation-barbados-2015-6-uhrskov-47', 599, TRUE, NULL, 47, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/barbados.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Origins No. 1 Belize Draw 1, 60%', 'https://www.uhrskov-vine.dk/wild-series-origins-no-1-belize-draw-1-60', 649, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/wsoriginbelize1.png', 'Vi har her at gøre med nogle helt specielle hvide rom som er udvalgt pga. deres fantastiske smagsprofil. I dette tilfælde er det en rom fra Belize, hvor vi har fået muligheden for at tappe den rom som kommer ud af kedlen umiddelbart efter hovedet er ''cuttet'' fra. 1. Draw, har den mildeste smag i et destillat, hvorefter smagen intensiveres hen mod 5. Draw som er det sidste inden man igen ''cutter'' destilatet for ikke at få for mange urenheder med. Rommen er ulagret og destilleret ret kort tid inden den er tappet på flaske. Velegnet til at nyde ren, men er også helt fantastisk til cocktails   Fakta Belize Unaged 1. Batch Distilled 2022 At Travellers Distillery 1 draw at distillation Strength at 60% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Origins No. 2 Belize Draw 5, 60%', 'https://www.uhrskov-vine.dk/wild-series-origins-no-2-belize-draw-5-60', 649, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/wsoriginbelize2.png', 'Vi har her at gøre med nogle helt specielle hvide rom som er udvalgt pga. deres fantastiske smagsprofil. I dette tilfælde er det en rom fra Belize, hvor vi har fået muligheden for at tappe den rom som kommer ud af kedlen umiddelbart efter hovedet er ''cuttet'' fra. 5. Draw, har den mest intense smag i et destillat, det erdet sidste inden man igen ''cutter'' destilatet for ikke at få for mange urenheder med. Her er der tale om en virkelig kraftfuld rom. Rommen er ulagret og destilleret ret kort tid inden den er tappet på flaske. Velegnet til at nyde ren, men er også helt fantastisk til cocktails   Fakta: Belize Unaged 1. Batch Distilled 2022 At Travellers Distillery 5 draw at distillation Strength at 60% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Centenario 23 Sistema Solera 100cl', 'https://www.uhrskov-vine.dk/ron-zacapa-centenario-23-sistema-solera-1-liter', 499, TRUE, 100, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/o/ron-zacapa-centenario-23-sistema-100cl.jpg', 'Bemærk 1 Liter !!! Verdens bedste Rom! For sjette år i træk er Ron Zacapa Centenario huset kåret som verdens bedste rom, i kategorien Premium Category. Kåringen er sket ved Caribbian Week "Rumfest"/Rumfestival i 1998, 1999, 2000, 200, 2002 og 2003.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier LROK 6 år Hampden 2010 Jamaica Pure Single Rum 67%', 'https://www.uhrskov-vine.dk/habitation-velier-lrok-6-ar-hampden-2010-jamaica-pure-single-rum-67', 999, TRUE, NULL, 67, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/e/velier-hampden-6yo-2010-jamaica-rum_2.jpg', 'Hampden 2010 LROK er den første aftapning i rom-historien, som er fuldstændig færdig lagret på Hampden Destilleriet i Trelawny, Jamaica. Aftappet med en fadstyrke på 67% alkohol efter 6 år på fad med en “Angelshare” på 40%, LROK indentificere at rommen er mellem 350 og 450 esters: en klassisk Hampden. En rim-historisk verdenspremiere.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diamond 1999 15 år Very Old Demerara Rum 53,1%', 'https://www.uhrskov-vine.dk/diamond-1999-15-ar-very-old-demerara-rum-53-1', 1995, TRUE, NULL, 53.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/i/diamond-1999-15-demerara_2_1.jpg', 'En 1999 vintage Diamond rom aftappet ved høj fadstyrke på 53,1%. Dette er en blend af 4 tønder destilleret i en Coffey Still og herefter lagret i 15 år (i troperne, som etiketten siger) og aftappet i juli 2014. Forsvindende få flasker tilbage.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes 13 år Panama 2004 56,9%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-13-ar-panama-2004-56-9', 649, TRUE, NULL, 56.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-panama-13yo-secrete_2.jpg', 'Aftappet kun til Danmark. Single Cask Rom fra Florent Beuchet - manden bag Compagnie des Indes serien. En 13 års aftapning fra Panama. Destilleret i februar 2004, efterfølgende importeret til Frankrig og aftappet i april 2017, fra et enkelt fad på kun 279 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation Guatemala XO 20th Anniversary Decanter 40%', 'https://www.uhrskov-vine.dk/rum-nation-guatemala-xo-20th-anniversary-40', 549, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/m/image-1.png', 'For at fejre Rum Nations 20 års jubilæum, har vi håndplukket nogle af de bedste og mest sødmefulde fade, som indeholder denne vidunderlige rom fra Guatemala og destilleriet S.A. TULULA..', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rammstein Rum, Laphroaig Whisky Cask Finish 46%', 'https://www.uhrskov-vine.dk/ramstein-rum-laphroaig-finish', 399, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/a/ramstein-rum-laphroaig-finish_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare 2011 12 Års Exceptional Cask Selection 60%', 'https://www.uhrskov-vine.dk/foursquare-2011-12-exceptional-cask-selection', 899, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/o/foursquare_1.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Infernal Rum Paris to Berlin Tropically Aged Rum 40%', 'https://www.uhrskov-vine.dk/infernal-rum-tropically-aged-40', 399, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/n/infernalrum.png', 'Infernal has been producing music for the dance floor for 25 years, and 8 years ago they turned their passion to rum and created their own rum brand. Over the years, they have gradually become more and more ambitious in their search for the ultimate sipping rum. Rum Paris to Berlin is the 7th rum in the series and the first to be available to all the Wine and Spirits stores in Denmark. With Rum Paris To Berlin, Infernal wanted to make a rum that can both be enjoyed at the party, but also enjoyed as it is. A rum for beginners but also for those who love to enjoy a good rum. They have chosen rum from Venezuela and the Dominican Republic, which are both aged in ex bourbon, French and American oak and in addition combine molasses and sugar cane juice based rum in the best way.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Dark Navy Blend No. 3, Rom De Luxe, 40,6%', 'https://www.uhrskov-vine.dk/selected-series-dark-navy-blend-rom-de-luxe-40-6', 495, TRUE, NULL, 40.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/dark_navy.png', 'Her kommer tredie skud på stammen i Selected Series Rum. Denne gang er der tale om et blend bestående af Rom fra Trnidad, Jamaica, Barbados og Guyana. En rom i den søde ende af skalaen, som er en rigtig hygge rom. Mundfølelsen i denne rom er en sødmefuld oplevelse med noter af Toffee, Flødekarameller, Vanilje, nødder, chokolade og en lille smule tobak. Et rigtig dejligt glas som kan suppleres med en bid mørk chokolade. Abv er 40,6% Spansk stil – sød rom', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Dominican Republic 2007 Madeira Finish Rom 50%', 'https://www.uhrskov-vine.dk/sbs-dominican-madeira-2007-rom', 629, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-dominican-madeira-2007-rom_2_1_1.jpg', 'Duft : En rund og behagelig repræsentant for klassiske noter af karamel, vanilje og ristet eg kombineret med et let surt touch.  Smag : Masser af aromatisk vanilje med noter af kokosnød, modne blommer og let brændte skumfiduser. S.B.S Dominican Republic 2007 er en enkeltfads-aftapning med kun 390 flasker. Rommen kommer fra et Dominikansk destilleri og er baseret på frisk sukkerrør juice. I 2007 blev rommen destilleret i en kolonne still, der blev tappet på vores lager i Danmark i august 2020. Rommen har lagret på et ex-bourbon fad og har fået et yderligt Madeira vin finish. S.B.S Dominican Republic 2007 blev tappet med 50% vol. Som almindelig praksis for vores Single Barrel Selection rom er det gjort uden brug af koldfiltrering.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HAMPDEN ESTATE EUPHONIA SINGLE CASK JUULS ENDEMIC BIRDS SERIES 62,2%', 'https://www.uhrskov-vine.dk/hampden-estate-euphonia-single-cask-62-2', 4995, TRUE, NULL, 62.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/9/0/90601049.jpg', 'Endelig er den her! Hampden Estate LROK Single Cask #496 2010 Selected by Juul’s Vin & Spiritus er den sidste af de to danske single casks fra Hampdens nye serie ”Trelawny Endemic Birds”. Hver aftapning prydes af en tegning af én af de mange fugle, som kun findes på Jamaica, og vores fad viser den smukke  Euphonia Jamaica,  som trives over stort set hele øen. Rommen er en såkaldt LROK, hvilket står for  Light Rum Owen Kelly , og hos Hampden betegner en rom, der umiddelbart efter destillationen indeholder mellem 300 og 400 gram estere pr. hektoliter ren alkohol. Den er naturligvis lagret i Jamaica i alle de 10 år, tappet ved fadstyrke (62,2%) og hverken tilsat sukker eller farve.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Boulet de Canon no 2 Compagnie Des Indes 46%', 'https://www.uhrskov-vine.dk/boulet-de-canon-2-compagnie-des-indes-46', 950, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Boulet de Canon nr. 2 fra Compagnie des Indes er en begrænset udgave. Denne rom er en blanding af forskellige rom fra Caribien (Guyana, Barbados og Trinidad-og-Tobago. Den modnede i 7 måneder i en whiskyfade fra det berømte destilleri Caol Ila på øen Islay. Det imponerende alkoholindhold (75 %) blev reduceret til 46%, vil denne anden udgave uden tvivl være lige så populær som den første', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Boulet de Canon no 1 Compagnie Des Indes 46%', 'https://www.uhrskov-vine.dk/boulet-de-canon-no1-compagnie-des-indes-46', 999, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Boulet de Canon er en skotsk fadlageret rom baseret på en blanding af forskellige rom fra Caribien. Efter det færdige blend modtog de efterfølgende modning over 7 måneder i single malt whisky-fade fra Isle of Skye, destilleriet Talisker. En spændende karakter, der ledsages af tør røg, der giver en stor dosis “wow”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Ghana 2020 Rum, 60,3%, RomDeluxe', 'https://www.uhrskov-vine.dk/rom-deluxe-ghana', 795, TRUE, NULL, 60.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/h/ghana.png', 'Der tappes kun 188 fl, ved en fadstyrke på 60,3%. Der er ikke tilsat sukker eller farve, og den tappes ufiltreret. Det er det eneste lagrede Ghana rom der findes i DK. (Sandsynligvis i hele Europa).', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Panama 21 års Rum, 57,18%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-panama-21', 799, TRUE, NULL, 57.18, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/panama.png', 'Limited batch series Panama Det er en spændende gammel aftapning fra Panama. Destilleriet er som med de fleste rom herfra hemmeligt. Den er destilleret i 1999 og tappet i 2020, lagret alle årene i tropisk klima. ABV er  Navy Strenght 57,18% og sidst men ikke mindst så er der tilsat 9,2 gr. sukker pr liter. Og nu til det det virkelig handler om. Rommen i flasken.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Privateer 2020 New England Pure Single Rum Habitation Velier 62%', 'https://www.uhrskov-vine.dk/privateer-2020-new-england-pure-single-rum', 799, TRUE, NULL, 62, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/r/privateer.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes DK 18 Års Guadeloupe Bellevue Rum, 55,1% #GMB57', 'https://www.uhrskov-vine.dk/compagnie-des-indes-dk-18-ar-guadeloupe-bellevue-rum', 1299, TRUE, NULL, 55.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdiguadeloupe.png', '95 point / TESTVINDER - Bedste Rom  - Whisky&-magasinet "Kæmpestor næse med mokka, nedfalgsfrugt og flotte, syrlige citrusnoter. Smagen er eminent og byder på bitter chokolade, frugt og enestående fadnoter som er i perfekt balance. Dette er en fantastisk god rom!" Compagnie des Indes Guadeloupe 18 Years er en single cask aftappet eksklusivt til det danske marked. Denne rom er fra Bellevue i Guadeloupe og er destilleret på kolonne-stills før den lagres 18 år på bourbonfade. I tråd med de andre ”Denmark Exclusives” fra CDI, er den tappet ved fadstyrke – i dette tilfælde 55,1%. En smagsbombe af højeste karat!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes 9 Års Secrete Jamaica Rum, 53,50% #JWSP1', 'https://www.uhrskov-vine.dk/compagnie-des-indes-9-ars-secrete-jamaica-rum-53-50', 749, TRUE, NULL, 53.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdijamaica9.png', 'Compagnie des Indes Secrete Jamaica 9 Years Old cask #JWSP1 er en enkeltfadsaftapning fra Jamaica. Selve producenten er ikke oplyst – under ”destilleri” har flasken påskriften ”Secrete”.  Det er ikke ualmindeligt, at aftapperen underskriver en fortrolighedsaftale om, at man ikke afslører hvilket destilleri, der har leveret rommen. Men det er naturligvis også smagen der tæller, og her skuffer denne Jamaica-rom ikke! Stor og frugtig med power og en laaaang eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Beenleigh 2006 Tropical Ageing Pure Single Rum, Velier 59%', 'https://www.uhrskov-vine.dk/velier-tropical-ageing-2006-beenleigh-pure-single-rum-59', 1499, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/beenleigh_2006.png', 'Lagret i 15 år med en samlet Angel''s Share-procent på over 23 %, 2006 Tropical Aging-versionen blev destilleret i Single Column og Pot Still, derefter lagret i tidligere Brandy-fade, derefter ex-Bourbon American Oak og til sidst i Kauri Pine-fade med over 120 års levetid. Tappet ved fuld fadstyrke ved 59% ABV.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 21 St. Lucia 21 års Single Cask Rum Batch 6 49,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-21-st-lucia-21-aar-single-cask-batch-6-49-1', 3995, TRUE, NULL, 49.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/batch6.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot, British Royal Navy Rum 54,3%', 'https://www.uhrskov-vine.dk/black-tot-navy-rom', 7495, TRUE, NULL, 54.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/l/black-tot-navy-rom_2.jpg', 'Black Tot er det sidste tilbageværende lager af den originale Royal Naval Rum Tot. Den 31. juli 1970 sluttede en 300 år gammel Royal Naval-tradition, da den sidste romration blev udstedt ombord på Royal Navy''s skibe. Denne dag ville blive husket som "Black Tot Day". Siden da har rommen været opbevaret stille i keramiske fade på lagre og kun serveret ved statslige arrangementer og kongelige bryllupper.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Vieux Sajous 5 ans 2017 Caroni Cask', 'https://www.uhrskov-vine.dk/clairin-vieux-sajous-5-ans-2017-caroni-cask', 1049, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/5/0/50625248-clairin-vieux-sajous-5-ans-2017-caroni-cask.jpg', 'Mødet mellem to giganter: Clairin og Caroni! Den allerede intense og højaromatiske clairin Sajous har tilbragt 5 lange år på Caroni-fade, før den er tappet ved 52,4% i ganske få eksemplarer, som nok skal få ben at gå på… Farve : Gylden. Duft : Kraftig og kompleks duft af kakao, eksotiske krydderier og tropisk frugt. Smagsnoter : En fyldig og intens rom med noter af mørk honning, lakrids, citrus og muskatnød. Serveringsforslag : Bør nydes rent.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2019 Long Pond Jamaica Pure Single Rum 60%', 'https://www.uhrskov-vine.dk/habitation-velier-2019-long-pond-jamaica-pure-single-rum-60', 799, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/habitationlong.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2017 Hampden Jamaica Pure Single Rum 60,50%', 'https://www.uhrskov-vine.dk/habitation-velier-2017-hampden-jamaica-pure-single-rum-60-50', 1399, TRUE, NULL, 60.5, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 34 Guyana 20 års Single Cask 59,8%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-no-34-guyana-20-single-caks-59-8-rom-deluxe', 2995, TRUE, NULL, 59.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws34.png', 'Denne rom er oprindeligt præsenteret i Unicorn Vol 2 Tasting kit. Efter at have produceret Coffret-sættene var der lidt mere rom i tønden. Da vi virkelig godt kan lide Guyanesisk rom, ville vi lave noget særligt med den. Det er en rom fra Diamond destilleri i Guyana. Det er baseret på melasse. Mærket for denne rom er MEE, som produceres på Enmore EHP Coffey Still. Den eneste kolonne kedel, der er lavet af træ, som stadig producerer rom. Den blev Lagret kontinentalt i Ex. Bourbon fad, uden tilsat farve. Fakta Diamond Distillery Marque MEE Distilled Feb. 2002 Bottled Oct. 2022 Continentally aged Barrel No. 14 27 bottles Cask Strength at 59,8 % ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 36 Guyana 18 års Single Cask 54,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-36-guyana-single-cask-54-9-rom-deluxe', 2995, TRUE, NULL, 54.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws3654_9.png', 'Denne rom er oprindeligt præsenteret i Unicorn Vol 2 Tasting kit. Efter at have produceret Coffret-sættene var der lidt mere rom i tønden. Da vi virkelig godt kan lide Guyanesisk rom, ville vi lave noget særligt med den. Det er en rom fra Diamond destilleri i Guyana. Det er baseret på melasse. Det er potStill destilleret på deres berømte Versailles Still, som er den eneste enkelt træ pot still, der stadig fungerer på Diamond destilleriet. Den blev lagret kontinentalt i Ex. Bourbonfad, og der er tilsat farve til rommen under lagring. Fakta Diamond Distillery Marque MDXC Distilled July 2004 Bottled Oct. 2022 Continentally aged Barrel No. 5 23 bottles Cask Strength at 54,9% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 2002 Barbados 8 år', 'https://www.uhrskov-vine.dk/rum-nation-2002-barbados-8-ar', 325, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-2002-barbados-8yo_1.jpg', 'Bestseller - Rum Nation 2002 Barbados 8 Year Old', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 13 år 1995 Barbados Rum', 'https://www.uhrskov-vine.dk/rum-nation-13-ar-1995-barbados-rum', 479, TRUE, NULL, NULL, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-13yo-1995_1.jpg', 'The Original Still Rum Limited Edition Den anerkendte aftapper Fabio Rossi, har skabt denne spændende romserie Rum Nation. Det er håndplukkede fade, som bliver tappet enkeltvis, og det er kun det bedste af det bedste der ryger igennem nåleøjet til disse aftapninger.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 2, 18 år Guyana 59,7%', 'https://www.uhrskov-vine.dk/plantation-extreme-no-2-18-ar-guyana-59-7', 1850, TRUE, NULL, 59.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-extr2-guyana_2.jpg', 'Plantation Extreme No. 2 er først fadlagret i bourbon tønder i 15 år i Guyana. Efterfølgende fadlagret i 3 år hos Maison Ferrand i cognacfade. En meget intens og kompleks krydret smag af delikate indtryk af hasselnød, marcipan, lakrids, chokolade, kaffe og muskatnød. En lang eftersmag af appelsinskal, eg og muskatnød.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Jamaica 2008 Single Barrel Selection 62,8%', 'https://www.uhrskov-vine.dk/sbs-jamaica-2008-628', 765, TRUE, NULL, 62.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-jamaica-2008-628_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Brazil/Barbados, Single Barrel Selection, 2015 52%', 'https://www.uhrskov-vine.dk/sbs-brazil-barbados-2015-52', 675, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-brazil-barbados-2015-52_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Columbia, Single Barrel Selection, 2009, 46%', 'https://www.uhrskov-vine.dk/sbs-columbia-2009-46', 625, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-columbia-2009-46_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Malteco Rom Seleccion 1986 40%', 'https://www.uhrskov-vine.dk/malteco-rum-seleccion-1986', 1199, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/malteco-rum-seleccion-1986_2.jpg', 'Denne Malteco Rom fra Guatemala har en himmelsk smag med noter af tørrede frugter, vanilje, chokolae, marmelade og krydderier. Du kan her prøve en ægte 28 års gammel rom fra Guatemala. Flasken kommer i en rigtig flot trækasse, som får den til at fremstå ekstra elegant. Malteco rom bliver typisk lavet på frisk sukkerrørsjuice som giver et ekstra smagsoplevelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Papas Pilar Sherry Finish, Limited Edition Rum 43%', 'https://www.uhrskov-vine.dk/papas-pilar-sherry-finish', 599, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/papas-pilar-sherry-finish.jpg', 'Papa’s Pilar Sherry Finish er en fyldig og sødmefuld rom sammensat af destillater fra Caribien og Nord-, Syd- og Mellemamerika. Denne ”limited edition” er baseret på Papa’s Pilar Dark Rum, men undergår en såkaldt ”finish” på en helt særlig slags fade, bygget af fransk limousin-eg, som i en periode har indeholdt den nøddeagtige oloroso-sherry.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 3 Panama 20 års Blended Rum 65,2%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-3-panama-20-rom-de-luxe-65-2', 895, TRUE, NULL, 65.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/i/wild-series-3-panama-20yo-rom-de-luxe_2.jpg', 'Wild Series Panama 20 år er den 3. rom i den såkaldte "Wild Series" serie. Den uafhængige aftapper "Rom de Luxe" har denne gang fundet et 20 år gammelt fad fra Panama, hvorfra rommen hos et unavngivent destilleri er et blend af Pot Still og Kolonnedestillering fra 1999 el. tidligere. Wild Series 3 Panama 20 års rom er lagret i bourbonfade, den er tappet ved fadstyrken 65%, og der er tilsat 9 gram sukker/L. Kun 279 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 4 Belize 10 års Single Cask Rum 71,8%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-4-belize-10-rom-de-luxe-71-8', 995, TRUE, NULL, 71.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/i/wild-series-4-belize-10yo-rom-de-luxe_2.jpg', 'Wild Series 4 Belize 10 år Single Cask er den 4. rom i Romdeluxe "Wild Series" serie. De gode folk fra Rom de Luxe har her fundet et 10 år gammelt Single Cask fra Belize, hvorfra rommen er destilleret hos Traveller Distillery og tropisk lagret i 10 år. Denne rom er et blend af Pot Still og Kolonnedestillering fra 2009, og er lagret i bourbonfade, tappet ved fadstyrken 71,8% i januar 2020, og der er ikke tilsat hverken sukker eller farve. Kun 252 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2012 Sainte-Lucie 45%', 'https://www.uhrskov-vine.dk/la-maison-rum-2012-sainte-lucie', 549, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2012-sainte-lucie.jpg', 'St. Lucia Distillers blev født i 1972 fra fusionen af to destillerier på øen. Dets internationale anerkendelse skyldes i vid udstrækning Laurie Barnard, direktør for destilleriet i fire årtier. I dag bruger destilleriet fire kolonne stills og tre pot stills til destillering. Kombineret med deres ”savoir-faire” stil ift. lagring og blending producerer St. Lucia Distillers et imponerende portfolie af traditionel rom, såsom Chairman’s Reserve og Admiral Rodney…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series No. 49 Jamaica 11 års Single Cask 61,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/wild-series-49-jamaica-11-single-cask-61-9', 995, TRUE, NULL, 61.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/j/a/jamaica.png', 'Her har vi en ret ung Jamaica-rom fra et hemmeligt destilleri i Trelawny Parish. Lagret primært i kontinentalt klima, hvilket har givet denne rom en meget frugtagtig smag. Den er destilleret på en dobbelt Retort potstill. Vi forsøger at variere rommene i denne serie, så denne gang er det en ret ung rom fra et velkendt og meget respekteret destilleri. Fakta: Jamaica Based on Molasse Distilled July 2012 At A secret distillery Distilled at Double retort potstill Bottled August 2023 Marque MJH3 Tropical & Continental aged Aged in Ex Bourbon cask Cask no. 13 248 bottles Cask Strength at 61,9% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 1753, Pure Single Jamaican Rum 46%', 'https://www.uhrskov-vine.dk/hampden-estate-1753-pure-single-jamaican-rum-46', 599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/h/a/hampden1753.png', 'Hampden Estate 1753 er det nyeste skud på stammen hos det gamle destilleri på Jamaica. Rommen er navngivet efter året for destilleriets grundlæggelse – det er det ældste på øen! Og tingene har ikke ændret sig ret meget: de bruger stadig kobber-pot stills, naturligt gær, fuld tropisk lagring og nul sukker. 1753 er lagret 3 år, og har et højt ”ester-niveau”, som Hampden jo er særligt kendt for. En perfekt introduktion til destilleriets unikke stil!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S. Belize 2011 Bourbon & Cognac Cask Rom 52%', 'https://www.uhrskov-vine.dk/sbs-belize-2011-bourbon-cognac-cask-rom-52', 629, TRUE, NULL, 52, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbsbelize.png', 'Single Barrel Selection Belize 2011 er en enkeltfadsrom, der er baseret på melasse og destilleret i et kolonne still i 2011. Rommen er modnet på ex-Bourbon og Cognac fade og er aftappet ved en styrke på 52% vol i August 2024. Fra Travellers-destilleriet i Belize kommer denne 13-årige skønhed, der har tilbragt 12 år i troperne efterfulgt af yderligere 1 år i et cognacfad i Danmark. Rommen er ikke koldfiltreret. S.B.S Belize 2011 er begrænset til kun 499 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Belize Vintage Collection 2008 Terravera Limited Edition 48,3%', 'https://www.uhrskov-vine.dk/planteray-belize-vintage-2008-lmt-edt-48-3', 799, TRUE, NULL, 48.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/planteraybelize.png', 'TERRAVERA Vintage Collection NO. 3 - Limited Edition x19 casks', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series 5 Års Dominican Republic No. 2, Rom De Luxe, 41%', 'https://www.uhrskov-vine.dk/selected-series-dominican-republic-41', 399, TRUE, NULL, 41, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/o/dominican_republic.png', 'Selected Series Rum no. 2 kommer fra den Dominikanske Republic. Det er en dejlig rom i den søde ende af skalaen. En rigtig dejlig rom i den spanske stil, som med fordel kan nydes med et lille stykke mørk Chokolade.  Rommen har lagret 5 år i det tropiske klima, på amerikanske Bourbonfade. Den har noter af kaffe, mørk chokolade og vanilje. Den er kolonne destilleret med en ABV på 41% Der er tilsat ca. 20 gr. sukker i denne rom. Spansk stil – sød rom', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 9 Long Pond 19 års Single Cask Rum, 59%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-long-pond-19-rom-de-luxe-59-150', 4995, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Wild Series 9 Long Pond 19 Års Single Cask er den 9. rom i Romdeluxe "Wild Series" serie. De gode folk fra Rom de Luxe har her fundet et 19 år gammelt Single Cask fra  Jamaica, hvorfra rommen er destilleret Long Pond Distillery og tropisk lagret i alle 19 år. Denne rom er Pot Still´s destilleret i 2001, og efterfølgende lagret på amerikanske bourbonfade- Tappet ved  fuld fadstyrke 59% i August 2020, og der er ikke tilsat hverken sukker eller farve. Kun 209 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 13 år Rare Rums 2007-2020 Savanna Rom 62,6%', 'https://www.uhrskov-vine.dk/rum-nation-savanna-07-20-rom', 809, TRUE, NULL, 62.6, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-savanna-07-20-rom.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kirk & Sweeney XO Edition Limitada No. 1 Den Dominikanske Republik 65,5%', 'https://www.uhrskov-vine.dk/kirk-sweeney-xo-den-dominikanske-republik', 2699, TRUE, NULL, 65.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/k/i/kirksweeneyxo.jpg', 'Opkaldt efter "skonnerten", som smuglede Rom fra Caribien til den nordøstlige del af USA i løbet af forbudstiden i det gamle Amerika. Kirk & Sweeneys XO er en rig og kompleks rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Peru Vintage 2006, Spring 2021 14 år 47,9%', 'https://www.uhrskov-vine.dk/plantation-peru-2006-limited-edition-14-aar-47-9', 699, TRUE, NULL, 47.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/1/6/161304322547143667.png', 'Peru 2006 er en limited edition på kun 21 fade, der udtrykker al personlighed i den peruvianske terroir og rigdommen af sukkerrør fra Chicama-dalen, der ligger kun få hundrede kilometer fra den ecuadorianske grænse.  Destilleret i 2006, derefter blev denne rom først modnet i elleve år i 200-liters ex-bourbon-fade i kældre i det peruanske destilleri, hvor Angle''s Share er reguleret takket være teknisk kontrol af ventilation og fugtighed. Rommen foretog derefter en lang sørejse til Frankrig, hvor den blev ældet yderligere i tre år i Javrezac, i det sydvestlige Frankrig, i 400 liter franske egetønder for at tilføje det berømte Plantation-touch.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Barbados 15 års Rum, 61%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-barbados', 695, TRUE, 50, 61, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Det er ikke uden en vis stolthed at vi har fået fingre i dette gamle fad med Barbados rom. Rommen er destilleret på det navnkundige Foursquare destilleri, hvor Richard Seale udfører sin magi og sit håndværk. Vi har fået fingre i et 15 år gammelt fad, som har lagret sine første år i troperne, for herefter at få den sidste forfinede afrunding ved at ligge nogle år i det kølige europæiske klima. Den er tappet ved fuld fadstyrke, som er 61% ABV. Der er tidligere tappet 238 flasker, som hver især indeholder 50 cl, og er u-nummerede. Samt denne version som er tappet i 70 cl. flasker, hvor der blev 104 stk Vi har tappet den ufiltreret d. 30/12 2020', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Worthy Park Special Cask Series Madeira 10 år Jamaica Rum 45%', 'https://www.uhrskov-vine.dk/worthy-park-special-cask-series-jamaica-10-45', 649, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/o/worthy131.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Boulet de Canon no 10 Compagnie Des Indes 46%', 'https://www.uhrskov-vine.dk/boulet-de-canon-no-10-compagnie-des-indes-46', 599, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/o/boulet10.png', 'Gal eller genial? Uanset, så fortsætter serien  Boulet de Canon  fra Compagnie des Indes med sin nu 10. udgivelse. Det er selvfølgelig samme tema, som altid:  rom med røg. Denne gang har rommen, som består af et blend af Panama og Nicaragua, fået en 6-måneder-lang finish på quarter casks (små fade på 125 liter) fra et berømt whiskydestilleri på Islay. Vi ved ikke hvilket, men vi har da et bud… Inden fadet er fyldt med rom, har det ovenikøbet været forbi en særlig rygeovn, som normalt bruges til pølser og skinker i Jura! Rommen er tappet ved 46% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Limited Batch Series, Cuba 5 års Rum, 65,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/limited-batch-series-cuba-rom-de-luxe', 595, TRUE, NULL, 65.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/i/limitedbatchseriesrumcuba-31.png', 'Denne rom er seneste skud på stammen af lækre rom som kkommer i meget små aftapninger En rom fra Cuba er normalt en sødmefuld fløjlsblød oplevelse som i det fleste tilfælde har en alkoholstyrke på 40% ABV Men ikke denne gang.  Næ Denne rom er en potent sag, som er tappet ved fuld fadstyrke på 65,1%. Den er 5 år gammel, og tropisk lagret. Herefter har vi benyttet os af muligheden for at give den lidt ekstra kant ved at lagre den i yderligere 6 mdr i et American Virgin Oak fad i vores lidt koldere kontinetale klima. Dette har tilført rommen lidt ekstra fadnoter og givet den en helt fantastisk gylden farve. Både i næsen og i munden fornemmer man at denne unge rom er fuld af rå muskelstyrke. Der er med denne aftapning som med de andre Limited Batch Series aftapninger tappet et meget lille antal på 191 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Compagnie Des Indes Jamaica 5 år Navy Strength 57%', 'https://www.uhrskov-vine.dk/magnum-compagnie-des-indes-jamaica-5-navy-strength-57', 849, TRUE, NULL, 57, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Jamaica Navy Strength er en blanding af de bedste Compagnie des Indes Jamaica rom. Denne Navy Strength er en blanding fra fire forskellige producenter - hver med en lige stor andel iblandet (25% hver) til den endelige blanding i. Hver af disse 4 Jamauca rom er lagret i minimum 5 år på Jamaica. Et virkelig godt køb og så i fadstyrke.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Isautier 2005 Velier 16 Year Old Single Cask Rhum Agricole Cask#16/17 65%', 'https://www.uhrskov-vine.dk/isautier-2005-16-ar-melasse-rom-65', 1449, TRUE, NULL, 65, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/s/isautieragricole_1.png', 'Isautier 2005 Velier 16 Year Old Single Cask #16/17 The Isautier distillery was founded in 1845 by brothers Charles and Louis, twelve years after they first arrived on the Île de la Réunion. Following their deaths, Charles’ wife took over the company, renaming it Widow of Ch. Isautier & Sons in 1865. The distillery’s trademark stoneware bottles were also introduced around this time. The distillery was modernised by Alfred Isautier in 1910. He added a column still, increasing production and allowing its rum to be distributed around the world. 100 years later, it was modernised again when the company moved to a new state of the art distillery in 2011, where today it produces both molasses-based and agricole rums. This single cask release is the first collaboration by the distillery with Velier in its iconic black bottle.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Isautier 2005 Velier 16 Year Old Single Cask Rhum Traditionnel Cask #38 65%', 'https://www.uhrskov-vine.dk/isautier-2005-16-ar-agricole-rom-65', 1499, TRUE, NULL, 65, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/s/isautiermelasse_1.png', 'Lyden af navnet ”Velier” får en helt særlig følelse frem hos romnørder. Gang på gang formår masterminded bag firmaet, Luca Gargano, at chokere og henrykke romverdenen med udgivelser der sætter nye standarder for kvalitet, gennemsigtighed og nørderi. Veliers ry for exceptionel kvalitet cementeredes allerede i ’00’erne med en perlerække af kompromisløse demerara-rom. Disse flasker er i dag højdemålet af kultrom og skifter ejere for astronomiske summer på spiritusauktioner verden over. Senere er firmaet blevet kendt for tropisk lagret Caroni, en særegen rom fra et nu lukket destilleri på Trinidad, med noter af røg, tjære og bacon. En ”acquired taste”, men når først du har den… Sammen med Foursquares Richard Seale er Luca standhaftig (og højlydt) modstander af tilsætningsstoffer eller fusk med aldersbetegnelser, og derfor sætter Veliers nyeste serie af rom, Habitation Velier, gennemsigtigheden i højsædet. På etiketten blotlægges stolt enhver detalje om produktionen, lige fra ”angel’s share” til ester-indhold.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Trois Rivières, Cuvée Princess Rhum Agricole Hors D´Age 43%', 'https://www.uhrskov-vine.dk/trois-rivieres-cuvee-princess-43', 1349, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/troisrivieresprincess.jpg', 'Fransk rom-stil, her fra Martinique kaldes for Rhum Agricole - landbrugsrom. Rom på Martinique er måske den mest ”ærlige rom” i verden. De franske regler (AOC) forbyder at tilsætte sukker og farvekaramel. Der må heller ikke ”fifles” med alderen. Det er den yngste rom i blandingen, der sætter alderen på flasken. Sukkerrørene presses lige efter de er høstet og sukkerrørssaften gæres. Metoden kom i slutningen af 1800-tallet i Martinique. Sukkerpriserne på verdensmarkedet var så lave, så Homère Clement kom med idéen, at lave rom af den friske sukkerrørs juice. Ikke en kvalitetsbeslutning, mere ud fra realitet. Trois Rivières Cuvée Princesse er et resultat af de 8 bedste og exceptionelle fade, som derefter har gennemgået en langvarig blending proces for at opnå den bedst mulige rom.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Trois Rivières, Rhum Agricole VSOP 40%', 'https://www.uhrskov-vine.dk/trois-rivieres-rhum-agricole-vsop-40', 419, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/t/r/troisvsop.jpg', 'Fransk rom-stil, her fra Martinique kaldes for Rhum Agricole - landbrugsrom. Rom på Martinique er måske den mest ”ærlige rom” i verden. De franske regler (AOC) forbyder at tilsætte sukker og farvekaramel. Der må heller ikke ”fifles” med alderen. Det er den yngste rom i blandingen, der sætter alderen på flasken. Sukkerrørene presses lige efter de er høstet og sukkerrørssaften gæres, uden at først udvinde sukker. Metoden kom i slutningen af 1800-tallet i Martinique. Sukkerpriserne på verdensmarkedet var så lave, så Homère Clement kom med idéen, at lave rom af den friske sukkerrørs juice. Ikke en kvalitetsbeslutning, mere ud fra realitet. Produktionsmetoden og brug af de franske egetræstønder, får Rhum Agricole en vis lighed med Cognac i både duft og smag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation 2004 Fidji Single Cask Rum, Bottled for Denmark 46%', 'https://www.uhrskov-vine.dk/plantation-2004-fidji-single-cask-rum-46', 1199, TRUE, NULL, 46, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/f/i/fidji.jpg', 'Plantation Fidji 2004 Denmark Cask er en rom fra South Pacific Distillery aftappet af Plantation Rum udelukkende til det danske marked. Den har fået en afsluttende lagring på et fad, der tidligere har indeholdt portvin, og får derfra både vinøsitet og masser af juicy, rød frugt i duften. De 46% alkohol klæder virkelig rommen og giver ekstra dybe og intensitet i smagen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 5 2000 Barbados Rum, 47,8%', 'https://www.uhrskov-vine.dk/plantation-extreme-5-2000-barbados-47-8', 2999, TRUE, NULL, 47.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/x/extremeseriesv_barbados2000_70cl_eu_box.png', 'West Indies Rum Distillery', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 18 år Panama Sistema Solera Rum 40%', 'https://www.uhrskov-vine.dk/rum-nation-18-panama-sistema-solera-40', 509, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/panama18.jpg', 'Rum Nation har kommet til  Panama . Rum Nation - en verdensomspændende romserie, udelukkende bestående af udvalgte fade. Et udvalg af ”single rom”, tro mod spiritussens hjerte, unik og uforglemmelig. Denne Panama rom far Rum Nation er er del blødere og rundere end sin ”lillebror” på 10 år. Rommen er lagret og blended efter solera metoden, og der er brugt Ex-Bourbonfade til lagringen. Både fade, der lige er kommet fra USA og nogle, der har være brugt til rom tidligere. Også kaldet ”1st and 2nd fill bourbon casks”. Det er ikke beskrevet, hvilket destilleri den kommer fra, men de fleste kendere gætter på Varela Hermanos, som også laver deres egen Abuelo serie.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guatemala Single Cask Rum, Bottled for Uhrskov Limited Edition, 43%', 'https://www.uhrskov-vine.dk/plantation-guatemala-4-single-cask-rum-uhrskov-43', 499, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/g/u/guatemala_1.jpg', 'Elegant og afbalanceret rom med notere af træ, krydderier (allspice - allehånde) og frugter. En skøn bouquet af honning, appelsinblomst, solbær, kokos og vanilje. Herefter udvikler det sig til banan, abrikos og nødder med nogle blomsteragtige noter. Tropical Ageing 2 years in Bourbon casks Continental Ageing 1 year in Ferrand casks Further maturation Finished 4 months in red Pineaudes Charentes wine cask', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 36 Guyana 18 års Single Cask 56,9%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-no-36-guyana-18-single-cask-56-9-rom-deluxe', 2995, TRUE, NULL, 56.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/w/s/ws3654_9_1.png', 'Denne rom er oprindeligt præsenteret i Unicorn Vol 2 Tasting kit. Efter at have produceret Coffret-sættene var der lidt mere rom i tønden. Da vi virkelig godt kan lide Guyanesisk rom, ville vi lave noget særligt med den. Det er en rom fra Diamond destilleri i Guyana. Det er baseret på melasse. Det er potStill destilleret på deres berømte Versailles Still, som er den eneste enkelt træ pot still, der stadig fungerer på Diamond destilleriet. Den blev lagret kontinentalt i Ex. Bourbonfad, og der er tilsat farve til rommen under lagring. Fakta Diamond Distillery Marque MDXC Distilled July 2004 Bottled Oct. 2022 Continentally aged Barrel No. 6 15 bottles Cask Strength at 56,9% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Guyana Rom 27 år 52,7%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-guyana-rom-27-ar-52-7', 3495, TRUE, NULL, 52.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/o/com-indes-guyana-27yo_2.jpg', 'Compagnie des Indes 27 årige Guyana Rom, præsenterer sig selv som en unik rom med masser af smag. Den er fremstillet i Guyana, af Enmore destilleriet, der førhen hed Demerara, som i dag er ejet af El Dorado. Denne flaske er special lavet til det danske marked, men er aftappet og importeret fra Frankrig. Compagnie des Indes Enmore 27 Years Old Cask #MEC7 er en særdeles gammel rom fra det legendariske destillationsapparat, Enmore. Denne kolonne-kedel står i dag hos Diamond Distillery i Guyana, efter det oprindelige destilleri lukkede i 1993. Da rommen her er fra 1988, er den altså produceret på den gamle Enmore-estate. En sjældenhed. Både historie- og kvalitetsmæssigt.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM XO, Agricole Rom, Martinique 45% + 2 Glas', 'https://www.uhrskov-vine.dk/rhum-j-m-xo-agricole-rom-martinique-45-2-glas', 499, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/h/rhum-jm-xo-martinique-2glas_2.jpg', 'Et god aldret agricole rom fra Martiniques Rhum JM. Den har en dyb farve og stor aroma efter års modning i gamle Bourbon fade. Den har en generøs buket af ristede noter og citron, som komplimenterer de søde toner af mango og passionsfrugt. Oplevelsen er er forstærket af et strejf af peber, kanel og muskatnød. Concours Mondial de Bruxelles 2012 : Guld Medalje', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Rare Collection 1993 Enmore Rum, Cask Strength 56,5%, Guyana', 'https://www.uhrskov-vine.dk/el-dorado-rare-collection-1993-enmore-rum-cask-strength-56-5-guyana', 1950, TRUE, NULL, 56.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/e/l/el-dora-rare-coll-1993.jpg', 'Spændende nyhed fra El Dorado & Demerara Destillers. For første gang kommer der nu en række aftapninger i full proof / fuld fadstyrke og tappet i et meget begrænset oplag. Denne aftapning er fra Enmore, destilleret i 1993 fra en wooden continuous Coffey Still og lagret 22 år i tidligere Bourbon barrels. NB: Først på lager fra primo Februar 2016 !', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Extreme No. 2, 16 år Fiji 61,1%', 'https://www.uhrskov-vine.dk/plantation-extreme-no-2-16-ar-fiji-61-1', 1725, TRUE, NULL, 61.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-ext2-16yo-fiji_2.jpg', 'En intenst aromatiske rom, destilleret i pot stills på Fiji i marts 2001. Fadlagret i bourbon fade på øen i 13,5 år, derefter transporteret til Frankrig for yderligere lagring i to og et halvt år på Cognac fade. En del af Plantation''s “Extreme” serie, der fokuserer på rom med særprægede smag, tilbyder træagtige og frugtfyldt duft efterfulgt af en rig og fed gane, der minder om “peat malt whisky”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Panama 2010 Single Barrel Selection 54%', 'https://www.uhrskov-vine.dk/sbs-panama-2010-54', 625, TRUE, NULL, 54, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-panama-2010-54_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('S.B.S Cuba 2013 Single Barrel Selection 50%', 'https://www.uhrskov-vine.dk/sbs-cuba-2013-50', 649, TRUE, NULL, 50, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/b/sbs-cuba-2013-50_2.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Royal Navy Rom 2. Edition 2019 Tiger Shark 57,18%', 'https://www.uhrskov-vine.dk/velier-rom-2-edt-tiger-shark-2019', 1485, TRUE, NULL, 57.18, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/e/velier-rom-2-edt-tiger-shark-2019_2org_copy.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Monymusk EMB Tropical 14 år Continental Aging 69,7% Jamaica (Velier)', 'https://www.uhrskov-vine.dk/monymusk-emb-tropical-14-yo-continental-aging', 1250, TRUE, NULL, 69.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/1/4/14ans-rum-emb-tropical-aging-plummer.jpg', '100 Pot Still Tropical Aging. A blend of 10 casks of EMB 2006, 2 casks of EMB 2004 and 4 casks of EMB 2002, totally aged in Jamaica. Jamaica Vatted SIngle Rum. A joint bottling between E&A Scheer Amsterdam and Velier, Genoa.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Papas Pilar Bourbon Finish, Limited Edition Rum 43%', 'https://www.uhrskov-vine.dk/papas-pilar-bourbon-finish', 599, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/papas-pilar-bourbon-finish.jpg', 'Papa’s Pilar Bourbon Finish er en fyldig og sødmefuld rom blandet af destillater fra Caribien og Nord-, Syd- og Mellemamerika. Denne ”limited edition” er baseret på Papa’s Pilar Dark Rum, men undergår en såkaldt ”finish” på amerikanske egetræsfade, der før har indeholdt bourbon-whiskey. Den er tappet ved 43% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2010 Ile de la Réunion 45%', 'https://www.uhrskov-vine.dk/la-maison-rum-2010-reunion', 549, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2010-reunion.jpg', 'Grundlagt i 1886, er Rivière du Mât en af de sjældne destillerier i verden, der producerer traditionel rom såvel som rom i Agricole stil. Destilleriet er udstyret med to kolonne stills: En, der igennem en enkelt destillation, producerer aromatiske rom, og en anden, der igennem en tredobbelt destillation, producerer en lettere rom stil. Rommen modner derefter for det meste i franske egetræsfade og overvåges af master destillatøren Jean Grondin, som assisteres af Christian Vergier, en af de førende eksperter inden for lagring af spiritus…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('La Maison Du Rhum 2009 Panama 45%', 'https://www.uhrskov-vine.dk/la-maison-rum-2009-panama', 549, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/l/a/la-maison-rum-2009-panama.jpg', 'Traditionen med at producerer sukker i Panama, har eksisteret i årtier. I dag er over 1.200 hektar dedikeret til produktionen af rom og landet har et af de fineste samlinger af tønder, dedikeret til denne nektar. Jorden tilføres konstant et væld af næringsstoffer og mineraler fra dets aktive vulkaner. Fra denne livgivende jord, blomstrer de smukkeste sukkerrør, der senere omdannes til melasse af høj kvalitet og destilleres i kolonne stills…', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Beenleigh 2013 10 Years Tropical Ageing Rum, Velier 59%', 'https://www.uhrskov-vine.dk/beenleigh-2013-10-years-tropical-velier-rum-59', 1499, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/beenleigh2013_1.png', 'Beenleigh er Australiens ældste destilleri. Og når det gælder rom, er det formentlig også landets bedste. Alligevel har Beenleigh altid været ret vanskeligt at få fat på i Danmark, men heldigvis er der begyndt at dryppe lidt ind fra Velier en gang i mellem! Rommen her er destilleret i 2013 og lagret på bourbonfade i tropisk klima indtil den blev tappet i 2023 ved hele 59% alkohol. Yderst begrænsede mængder.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mauritius Vintage Collection 2013 Terravera Limited Edition 46,5%', 'https://www.uhrskov-vine.dk/planteray-mauritius-vintage-collection-2013-terravera-limited-edition-46-5', 699, TRUE, NULL, 46.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/mauritius2013.png', 'Planterays limited edition Vintage Collection bliver nu beriget med en rom fra Mauritius! Ikke verdens mest kendte romdestination, men utroligt spændende og med sin helt egen stil. Rommen her er destilleret i 2013 på base af melasse (på Mauritius ser man både sukkerrørssaft og melasse), på en column still. Den har tilbragt 9 år på bourbonfade i Mauritius, suppleret af 2 år hos Ferrand på franske fade. Den er tappet ved 46,5% alkohol, med en dosage på 4,5 gram sukker per liter, hvilket netop afrunder smagen og bidrager med en ganske let sødme.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XII Two Oaks Panama Rom 40% 20cl', 'https://www.uhrskov-vine.dk/abuelo-two-oaks-panama-rom-40-20', 219, TRUE, 20, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/2/1/213123312.jpg', 'En fantastisk blød smag - der tænder op for en ny lidenskab overfor rom. Abuelo Two Oaks er en dejligt blød 12 år gammel rom, der er blevet modnet i to karakteristiske egetræsfade. Først i udvalgte ex-bourbon fade, derefter i helt nye men ekstra forkullede fade af amerikansk eg. Fadene tilberedes af eksperter i Napa Valley, Californien. De udvælger dem, rister dem ved 180 ° C i 60 minutter for at forsigtigt åbne træet og skruer derefter varmen op til 220 ° C for at få den dybe forkullning på 8mm, som de gerne vil have. Denne totrinsproces, gør det muligt for rommen at trække ekstremt meget smag fra træet og der skabes et naturligt kulfilter, der giver en usædvanligt blød Two Oaks finish.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XV 15 års Napoleon Cognac Cask Finish, 40% 20cl', 'https://www.uhrskov-vine.dk/abuelo-xv-15-napoleon-cask-finish-20', 209, TRUE, 20, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/2/1/21389712378123.jpg', 'Ron Abuelo XV 15 års Napoleon Cognac Cask Finish Rum er en mørk Panama rom med bløde noter af tørret frugt og kaffe. Abuelo Napoleon er blot en ud af en spændende triologi fra Abuelo. De 2 andre rom i serien har lagt på delvis "Sherry Finish" og en på "Port Finish". Abuelo Napoleon Cognac Cask Finish er lagret på amerikanske bourbonfade og efterlagret på Cognacfade.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Caribbean Blend No. 4, Rom De Luxe, 42%', 'https://www.uhrskov-vine.dk/selected-series-caribbean-blend-42', 495, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/carribean_blend.png', 'Selected Series Rum no. 4 – Caribbean Blend Her kommer næste udgave af Selected Series Rum. Denne gang er det et blend af rom fra Guyana og Den Dominikanske republik. Rommen er i den søde ende af skalaen, hvor man får noter af karamel, Vanilje, brun farin og brændt træ. Det er en solera rom som er op til 12 år gammel. ABV er på 42% Spansk stil – sød rom', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Strong Navy No. 5, Rom De Luxe, 57,5%', 'https://www.uhrskov-vine.dk/selected-series-strong-navy-rom-de-luxe-57-5', 495, TRUE, NULL, 57.5, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/t/strong_navy.png', 'Strong navy er et  blend af de fineste og lækreste rom fra nogle af Caribiens dygtigste romproducenter fra bla. Trinidad, Jamaica, Barbados og Guyana. Den henvender sig til pirater og andet godtfolk som gerne vil have selskab af en kraftfuld fætter på de lange søtogter. Smagen er dyb, fyldig, kraftfuld og blød, men stadigvæk med en kant af en lang og karakterfuld eftersmag. Kompleks krydret duft af karamel, mørk chokolade og lakrids – præcis som enhver pirat kan lide det. Den er aftappet ved Navy strenght på 57,5 %', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Monymusk 2007 Pure Single Rum # 132 by Warren King Villa Paradisetto 68,5% (Velier)', 'https://www.uhrskov-vine.dk/monymusk-2007-mmw-villa-paradisetto-velier', 3500, TRUE, 70, 68.5, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Distilled 2007 - Bottled 2020 # 132 by Warren King  Type: Pure Single Destilleri:Monymusk Navn: Villa Paradisetto - MMW Aftapper: Velier Region: Jamaica Indhold: 70 cl Alkohol-%: 68.5% Destillationsår: 2007 Aftapningsår: 2020 "Warren Khong, artist and professor, already the author of masterpieces for Velier, has created these labels which artistically interpret the place where Velier has worked for 30 years. Monymusk 2007, pure single rum, highlights the mark "MMW". After 13 years of aging in a tropical climate, it was bottled at its natural level in 2020."', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 8 New Yarmouth 25 års Single Cask Rum 68,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-8-new-yarmouth-25-rom-de-luxe-68-1-150', 7495, TRUE, NULL, 68.1, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Wild Series 8 New Yarmouth 25 Års Single Cask er den 8. rom i Romdeluxe "Wild Series" serie. De gode folk fra Rom de Luxe har her fundet et 25 år gammelt Single Cask fra  Jamaica, hvorfra rommen er destilleret New Yarmouth Distillery og tropisk lagret i alle 25 år. Denne rom er Pot Still´s destilleret i 1994, og efterfølgende lagret på amerikanske bourbonfade- Tappet ved  fuld fadstyrke 68,1% i August 2020, og der er ikke tilsat hverken sukker eller farve. Kun 224 flasker aftappet.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 15 år Rare Rums 2005-2020 Diamond Rom 59%', 'https://www.uhrskov-vine.dk/rum-nation-diamond-05-20-rom', 839, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-diamond-05-20-rom.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series CARONI Single Cask 23 Years Old Rum Bottled for Uhrskov Vine 63,1% 150cl.', 'https://www.uhrskov-vine.dk/magnum-wild-series-caroni-uhrskov-rom-de-luxe-63-1-150', 8500, TRUE, 150, 63.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/_/d/_dsc7065_1.png', '****OBS** Kommer til salg fra på lørdag d. 6 Februar 2021 kl. 10.00 !!! *****BREAKING RUM NEWS ***** KALDER ALLE CARONI RUM-Aficionados !!! Vi har glædet os helt vildt til at kunne breake denne her nyhed for jer !! Det er med en stor portion stolthed og glæde at vi nu kan præsentere denne spændende og unikke Caroni aftapning "Bottled for Uhrskov Vine" i samarbejde med Romdeluxe. Denne fantastiske Caroni er en 23 År gammel Single Cask rom som er den #12. rom i Romdeluxe´s Wild Series. Det er ikke nogen hemmelig at vi (Anders og Kristian fra Uhrskov Vine) længe har været på udkig efter et helt unikt og spændende fad rom, og meget gerne i den "Heavy" stil af skalaen.  At det så samtidig skulle lykkedes os at få fat på et fad Caroni var lidt udover hvad vi turde håbe på. Vi har i samarbejde med de gode folk fra Romdeluxe fundet dette 23 år gammel Single Cask fra det lukkede destilleri Caroni på Trinidad. Rommen har fadlagret alle sine 23 år på Bourbon Cask og der er ingen tilsat sukker. Der er kun kommet beskedne 220 flasker x 0,70cl ud af dette fad og alt sammen tappet i fuld fadstyrke på 63,1% ABV.  Land:   Trinidad  Destilleri: Caroni Destilleret:    Januar 1998 Flasket: Januar 2021 Alder:  23 år   Fad:Ex. Burbon Lagret: Tropisk og kontinentalt. Antal:  220 stk.  ABV: 63,1% Farve:  Dyb Kobberfarve / Mahogni Duft:  Potent og helt klassisk Caroni med duft af jernbanesveller, lak og lim. Lidt engelsk lakrids, muscovadosukker, kandiseret frugter og mentol, figner og tobak.  Smagsnoter:  Lakrids, tørrede frugter, brændt træ, Vanilje og petroleum. En fuldmoden Caroni. Gulvlak, lim, syrlige frugter, grape, citrus. Lidt salt og behageligt fadpræg. Alkoholen er velintegreret i rommen. Om Caroni:  Caroni er rom fra det nu efterhånden hedengangne destilleri af samme navn og som indtil omkring 2002/2003 producerede rom af en meget speciel stil i Trinidad. Blandt smagsnoterne finder man ting som tjære og petroleum, og Caroni er – mildt sagt – en "acquired" taste. Men det kan man ', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Seven Seas Blend, Rom De Luxe, 40%', 'https://www.uhrskov-vine.dk/selected-series-seven-seas-blend', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/e/seven_seas.png', 'Selected Series - Seven Seas er en rom i den søde kategori. Det er et blend af Rom fra Panama og Den Dominikanske Republik. Begge rom er kolonne destilleret og lagret på brugte Bourbonfade i op til 12 år. Der er tilsat under 20gr. sukker/l i denne rom men til trods for dette får man en spændende sødmefuld oplevelse Rommen er ufiltreret for mest mulig smag. I munden får man en en dyb blød rom sødmefuld som de caribiske kvinder på en hvid sandstrand, hertil kommer noter af Vanilje, læder og brændt sukker. ABV 40%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Deep Water Blend, Rom De Luxe, 40%', 'https://www.uhrskov-vine.dk/selected-series-deep-water-blend-40', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/e/deep_water.png', 'Selected Series - Deep Water er en blended rom hvor vi har blended rom fra Den dominikanske republik, med rom fra Nicaragua. Rom fra Nicaragua har lidt mere kant og kan være med til at give rommen karakter. Begge rom er kolonne destilleret, hvilket giver en mere forfinet smag. De er lagret i op til 12 år på gamle brugte fade som tidligere har indeholdt Bourbon whisky. Smags noter her får du Vanilje, karamel, melasse, røde bær og en lille smule smør. Et rigtigt dejligt glas. ABV 40%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Sailors 2nd Choice, Rom De Luxe, 40%', 'https://www.uhrskov-vine.dk/selected-series-sailors-second-choice', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Sailors 2nd. Choice er en overflod af smag Her er tale om et blend af 2 rom fra henholdsvis Guyana og den Dominikanske republik. Rommen fra Guyana er potstill destilleret og rommen fra den Dominikanske Republik er kolonne destilleret. Begge rom har ligget på ex bourbontønder. Rommen tappes ufiltreret for at sikre mest mulig smag. Duft: Karamel, lidt “brændt” træ og vanilje. Smag: toffee, vanilje, mørk chokolade, demerarasukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Captains Dream, Rom De Luxe, 40%', 'https://www.uhrskov-vine.dk/selected-series-captains-dream-40', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/a/captains_dreams.png', 'Selected Series - Captains Dream Denne rom er et blend af rom fra 3 meget anerkendte romlande. Der er rom fra Nicaragua, Venezuela og Panama. alle rom i dette blend er op til 9 år gamle. Der er ikke tilsat sukker til denne aftapning, hvilket gør at man får en smagfuld karakterfuld rom som kun har den naturlige sødme der kommer fra lagringen i brugte bourbonfade. Vi syntes det er vigtigt at vise at man det også er muligt at lave gode rom uden at tilsætte Sukker. I denne rom får man en eksplosion af smag, der er vanilje, toffee, en smule fadpræg, læder og tørret tropisk frugt. ABV 40%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Selected Series Treasure Island, Rom De Luxe, 40%', 'https://www.uhrskov-vine.dk/selected-series-treasure-island-40', 395, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/static/version1793962392/frontend/Wogw/uhrskov_hyva/da_DK/Magento_Catalog/images/product/placeholder/image.jpg', 'Selected Series - Treasure Island I denne rom får man toppen af poppen. Det er et blend af rom fra Den dominikanske Republik, Venezuela, Nicaragua og Panama. Her får man som titlen antyder et væld af forskellige smage og oplevelser. Rommen er lagret i op til 12 år på amerikanske bourbonfade. Herefter er den nænsomt blended og tappet uden brug af filtrering. Enjoy Abv 40%', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie des Indes 8 Års Multi Distilleries Rum, 64,9%', 'https://www.uhrskov-vine.dk/cdi-8-multi-distilleries-rum-64-9', 949, TRUE, NULL, 64.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi8multi.png', 'Compagnie des Indes har tappet nogle af de allerbedste Jamaica-rom, vi nogensinde har smagt, fra destillerier som New Yarmouth og Hampden. Med denne  Bottled for Denmark- ­aftapning går de lidt anderledes til værks. Det er nemlig et ”multi-distillery blend”. De forskellige destillater kommer alle fra juli 2012, og er så blandet sammen i ét fad, hvor de er lagret indtil rommen blev tappet i april 2021 som 8 år gammel. Fadet (nummer JDM71) gav 247 flasker ved hele 64,9%. Og det er alt sammen til Danmark!', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('MAGNUM Wild Series No. 21 St. Lucia 21 års Single Cask Rum Batch 5 47,7%, RomDeluxe', 'https://www.uhrskov-vine.dk/magnum-wild-series-21-st-lucia-21-aar-single-cask-batch-5-47-7', 3995, TRUE, NULL, 47.7, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/batch5.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Jamaica Rom 8 år 54,9%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-jamaica-rom-8-ar-54-9', 575, TRUE, NULL, 54.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/o/com-jamaica8yo-worthy-549pct_2.jpg', 'enne aftapning fra Compagnie Des Indes er destilleret på Worthy Park Estate, et destilleri lokaliseret midt i Jamaica, i en smuk dal med sukkerrørsmarker omgivet af bjerglandskab. Destilleret i december 2007 og aftappet april 2016. En smagsfuld 8 års Cask Strength rom på 54,9% alkohol.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Samaroli 1998 Cask No 54 Cuba 17 år Rom 45%', 'https://www.uhrskov-vine.dk/samaroli-1998-cask-no-54-cuba-17-ar-rom-45', 989, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/samaroli-1998-cask-no-54-cuba_2.jpg', 'En 17 års Cuba Rom fra Samaroli. Syd Amerika har arvet alle destillations og aldrings metoder fra kolonitiden, hvilket resultere i en lang række forskellige rom stilarter. I Rio Demerara er der flere aktive destillerier, der producerer den efterspurgte Demerara rom der anses af fans som værende en Rom i sin helt egen særskilt kategori. Denne Rom er fragtet til Cuba hvor den er lagret og forædlet. Vi ender altså ud med en caribisk Rom med et væld af store komplekse noter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Samaroli 1993 Cask No 40 Jamaica 22 år Rom 45%', 'https://www.uhrskov-vine.dk/samaroli-1993-cask-no-40-jamaica-22-ar-rom-45', 1989, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/s/a/samaroli-1993-cask-no-40-jamaica_2.jpg', '22 års rom fra Jamaica er et land, der har nogle af verdens bedste melasse, der ofte sælges til andre producerende lande. Mange destillerier er nu inaktiv og kun efterspørgslen på ​​gamle tønder kan sikre overlevelsen af traditionen. Den jamaicanske stil er meget karakteristiske inden for Rommen, den er stærke, intens og bidende - helt uforglemmelig. I denne Jamaica Rom finder du en dybden og styrken af ​​parfume der eksploderende når denne rom hældes op.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Uhrskovs RastaRom 5 års Jamaica Rom 49% 50cl', 'https://www.uhrskov-vine.dk/uhrskov-rastarom', 449, TRUE, 50, 49, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/u/h/uhrskov-rastarom_2.jpg', 'Limited Edition rom fra Jamaica, som har lagret et år i Uhrskov butikken på sherryfade, hvor den forinden har lagt på Bourbonfade i 4 år. Selve smagen er meget kraftfuld og samtidig blød med noter af ristede bananer og abrikos. OBS. Meget begrænset oplæg.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier 2015 Monymusk Jamaica Pure Single Rum 59%', 'https://www.uhrskov-vine.dk/habitation-velier-2015-monymusk-jamaica-pure-single-rum-59', 1195, TRUE, NULL, 59, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/o/monymusk.png', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Uhrskov Legacy 5, Jamaica 9 år Cask Strength Rum 55,1%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-uhrskov-legacy-5-jamaica-9-ar-cask-strength-rum-55-1', 599, TRUE, NULL, 55.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdi-uhrskov-legacy-5-jamaica_2.jpg', 'Så er vi klar med den næste "Uhrskov Legacy" her nr. 5 en spændende 9 års Rom udgivet af franske CDI (Compagnie Des Indes). Destilleret på Worthy Park Destillery i Jamaica, decmberer 2007 og aftappet april 2017. En Cask Strength aftapning på solide 55,1% alkohol. Der er aftappet 249 flasker af dette fad: JWP13.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Rhum Vieux 19 år Cask Strength 1991 Rum 54,4% 50cl', 'https://www.uhrskov-vine.dk/damoiseau-rhum-vieux-19-ar-cask-strength-1991-rum-54-4-50cl', 750, TRUE, 50, 54.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/damoiseau-rhum-vieux-19yo_2.jpg', 'Som en af de sidste "skjulte perler" i verden af spiritus, er dette et produkt fjerntliggende fra markedsføring kneb, reklameskilte og multinationale brands. Ikke let at få fat på og endnu mindre kendt, selv om det hurtigt er ved at ændre sig, den er repræsenteret af en håndfuld traditionalister, der fortsat findes med vilde sukkerrør ("vin de Canne«, eller »sukkerrørs vin« som franskmændene kalder det).', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum Nation 23 år 1989 Demerara Specially Selected 45%', 'https://www.uhrskov-vine.dk/rum-nation-23-ar-1989-demerara-specially-selected-45', 985, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rum-nation-23yo-1989-demerara_2.jpg', 'Britsh Guyana - The Original Still Rum Rum nation 23 års Demerara rom har en flot livlig farve med orange reflekser. Duften er meget harmonisk og udover den gode melasse duft, så er der noter af hvid chokolade og frugter.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Rhum Vieux Millesime 1980 60,3%', 'https://www.uhrskov-vine.dk/damoiseau-rhum-vieux-millesime-1980-60-3', 4500, TRUE, NULL, 60.3, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/d/a/damoiseau-rhum-vieux_2_1.jpg', 'Rom''en modner gennem 18 år i små brugte amerikansk bourbon tønder. Den blev overført til store egetræsfade for at begrænse fordampningsprocessen. Der hviler den op til sit aftapning. Den tappes i fad styrke og kun efter efterspørgslen.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Guyana 1993 21 år 51% DK', 'https://www.uhrskov-vine.dk/compagnie-des-indes-guyana-1993-21-ar-51-dk', 1695, TRUE, NULL, 51, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/i/n/indes-guyana-21yo-51pct_2.jpg', 'Compagnie des Indes Guyana, destilleret i oktober 1993 ved Uitvlugt destilleriet, og aftappet igen i marts 2015. Bottled For Denmark .', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Basseterre Rhum Vieux Guadeloupe 1997 49,2%', 'https://www.uhrskov-vine.dk/basseterre-rhum-vieux-guadeloupe-1997-49-2', 2285, TRUE, NULL, 49.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/basseterre-rom-1997.jpg', 'Denne rom fra Montebello destilleri i Basseterre, Guadeloupe er et pragteksemplar af en traditionel rom destilleret i 1997 af Velier. Den dufter af nelliker, karamel, spidskommen, citron og har en virkelig rar og lang eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Basseterre Rhum Vieux Guadeloupe 1995 58,2%', 'https://www.uhrskov-vine.dk/basseterre-rhum-vieux-guadeloupe-1995-58-2', 2695, TRUE, NULL, 58.2, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/a/basseterre-rom-1995.jpg', 'Denne rom fra Montebello destilleri i Basseterre, Guadeloupe er som traditionelt rom placeret på egetræsfad, og derefter aftappet. Med en kraftig duft af nelliker, karamel, spidskommen, citron følger en super rar og lang eftersmag.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ping X Plantation 26 år Trinidad 53%', 'https://www.uhrskov-vine.dk/ping-x-plantation-26-ar-trinidad-53', 18750, TRUE, NULL, 53, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/i/ping-x-plantation_2.jpg', 'Denne 26 års Ping Xs farve er mørk med en imponerende farvemætning som ahornsirup. Duften er af Mokka, vaniljestang, ristet eg, kandiseret appelsinskal og et hint af læder. Smagen er moden og vellagret med en tung prikkende karamelsødme. Rommen har noter af lagret sukkerrørssirup, bourbonvanilje, friskristet kaffe og sukat med en underliggende tone af rancio. Faddet Ping X og 11 er særligt udvalgt for at fejre Michael Madsens 40 års forretningsjubilæum.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Belize 2005 S.B.S. Single Barrel Selection 14 år Rom 58%', 'https://www.uhrskov-vine.dk/sbs-belize-2005-58pct', 899, TRUE, NULL, 58, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/b/e/belize-2005-e1566899547149.png', 'S.B.S Rom fra den Belize 2005 denne ”single cask” er lavet med kun 315 flasker. Den er produceret i 2005 og tappet i Danmark i August 2019.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Rum Fiji Vintage 2009 Old Reserve 44,8%', 'https://www.uhrskov-vine.dk/plantation-peru-2006-vintage-rum-43-1', 475, TRUE, NULL, 44.8, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/l/plantation-fiji-2009-old-reserve-rum-44-8_2.jpg', 'Fiji er en af de nyere kilder til Plantations Vintage-serie, og Plantation Fiji Old Reserve Vintage 2009 har lynhurtigt charmeret romnørder med sin potente, nærmest Jamaica-agtige intensitet og fyldige krop. Rommen er destilleret på South Pacific Distillery og er lagret 7 år på Fiji før den afsluttes på cognacfade hos Ferrand i Frankrig. Rommen er ikke tilsat sukker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes 18 år UITVLUGT 1997 Guyana 57,9%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-uitvlugt-1997-guyana-57-9', 995, TRUE, NULL, 57.9, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/o/com_indes_port_morant_2002_13_1.jpg', 'Compagnie des Indes Uitvlugt Single Cask #MGA5 kommer fra en såkaldt Savalle-still, der i dag står hos Diamond Distillery – det eneste destilleri, der er tilbage i Guyana. Rommen er lagret i 18 år mellem 1997 og 2016, og der blev tappet i alt 387 flasker fra fadet – alle i ”cask strength”. En imponerende, tør og smagfuld rom fra Florent og Co.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Wild Series Origins No. 4 Jamaica, 60%', 'https://www.uhrskov-vine.dk/wild-series-origins-4-long-pond-60', 649, TRUE, NULL, 60, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/r/u/rumorigins4.jpg', 'Her kommer den fjerde rom i serien af Wild Series Rum Origins. Det er en smagsbombe, som kommer fra LongPond Destilleriet. Her får man rom af meget høj kvalitet og med en helt utrolig masse smagsnuancer, som opstår ved brugen af deres egen specielle dunder, der blandes i under fermenteringen. Denne rom har det Rum marque som hedder TECC. Det betyder at den indeholder mellem 15 og 1700 esterforbindelser, som er dem der er med til at skabe den gode smag. Vi har valgt at tappe den på 60% ABV som vi syntes er en rigtig dejlig styrke, der gør at den kan drikkes rent, og benyttes i cocktails med stor nydelse.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 16, Venezuela 12 års Rum, 64,1%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-15-jamaica-54-4-rom-deluxe-12615', 795, TRUE, NULL, 64.1, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/v/e/venezuela_1.png', 'Denne rom kommer fra et hemmeligt destilleri i Venezuela. Dette destilleri laver nogle dejligt bløde rom med masser af smag og sødme.  Efter destillationen har den lagret på eks. bourbonfade. Der er ikke tilsat farve eller sukker til denne rom, og den er ikke chillfiltreret. Det er første gang, vi har en rom fra Venezuela i denne serie. Fakta: Venezuela Single cask Distilled Jan 2011 At CACD Distillery Bottled Aug. 2023 Based on molasse Aged in Ex. Bourbon cask. Cask no. 664 9 y Tropical, 3 y Continentally aged 252 bottles Cask Strength at 64,1% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Collectors Series No. 17, Australia 6 års Rum, 64,4%, RomDeluxe', 'https://www.uhrskov-vine.dk/collectors-series-no-17-australia-6-64-4-romdeluxe', 695, TRUE, NULL, 64.4, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/u/australia.png', 'Denne rom kommer fra et destilleri i Australien. Inden for de sidste par år er australsk rom blevet meget populær. Så vi ville gerne prøve noget, der er ret ungt og har lagret på et ex. Palo cortado-fad. Dette gamle vinfad har tilført rommen nogle meget bløde og frugtagtige noter. Denne rom er molassebaseret, og der er ikke tilsat farve eller sødme til denne rom. Vi er meget stolte af den måde, denne rom har udviklet sig.. Fakta: Australia Single cask Distilled Jan. 2017 At Secret Distillery Bottled Aug. 2023 Based on molasse Aged in Ex. Palo Cortado cask. Cask no. 59 3 Y Tropical & 3 Y Continentally aged 164 bottles Cask Strength at 64,4% ABV', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ypioca Castanheira Cachaca 39% 100cl', 'https://www.uhrskov-vine.dk/ypioca-castanheira-100cl', 239, TRUE, 100, 39, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/y/p/ypioca-prata-cachaca_1.jpg', '-', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Foursquare Absolutio 15 års Single Blended Rum, Foursquare / Velier 62%', 'https://www.uhrskov-vine.dk/foursquare-absolutio-15', 1999, TRUE, NULL, 62, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/a/b/absolutio.png', 'Samarbejdet mellem Luca Gargano og Foursquare Distillery har affødt nogle af romverdenens mest eftertragtede flasker, og nu frigives den 9. aftapning i serien: Absolutio. Rommen er en blanding af to komponenter, begge 15 år gamle. Den første del er lagret 15 år på bourbonfade, mens den anden del er lagret 10 år på bourbonfade og 5 år på portvinsfade. Der er naturligvis tale om tropisk lagring, og rommen er tappet ved  barrel proof  62% alkohol. Der er 4.800 flasker på verdensplan og selvfølgelig alt for få til Danmark.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Tawny Port Cask Finish 45%', 'https://www.uhrskov-vine.dk/patridom-tawny-port-cask-45', 595, TRUE, NULL, 45, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomtawny.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium rom fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave med Cognac Cask Finish har derudover gennemgået en ekstra lagring i ex-Tawny Port fade, hvilket tilføjer rommen en sød note. Patridom XO Tawny Port Cask Finish er blevet aftappet i juli 2023 med et resultat på 19 61 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Cognac Cask Finish 43%', 'https://www.uhrskov-vine.dk/patridom-lmt-edt-cognac-cask-43', 595, TRUE, NULL, 43, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/a/patridomcognac.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium rom fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave med Cognac Cask Finish har derudover gennemgået en ekstra lagring i ex-Cognacfade, hvilket tilføjer rommen en frugtagtig note. Patridom XO Cognac Cask Finish er blevet aftappet i august 2022 med et resultat på 1373 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Abuelo XV 15 Års Oloroso Sherry Cask Finish 40% 20cl', 'https://www.uhrskov-vine.dk/abuelo-xv-oloroso-sherry-cask-finish-40-20', 209, TRUE, 20, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/4/1/4122131245.jpg', 'Abuelo XV Oloroso er endnu et godt bud på, at Abuelo er igang med at producere verdens bedste rom. Abuelo XV Oloroso er en af 3 aftapninger i XV Finish Collection. Alle 3 rom er 15 år gammel og har fået en efterlagring (finish), på et fad der tidligere har været brugt til lagring af anden spiritus. Navnet på de 3 rom afspejler ikke blot karakteren fra fadet, men også stedet har inspireret til rommens endelig udformning. Napoleon er Cognac fra Frankrig, Oloroso er Sherry fra Spanien og Tawny er Portvin fra Portugal. Duft Læder, vanilje, mandarin og tørret frugt Smag Fed og cremet, noter af brændt orangeskal, abrikos samt søde krydderier Eftersmag Lang sødmefyldt og krydret eftersmag med noter af sød pibetobak og orange skal Kommentar En rafineret, elegant og helt rigtig ”Single estate rom” - sukkerrørene dyrkes på egne marker, rommen destilleres på egne kolonne kedler og rommen lagres på ex bourbonfade i egne lagerhuse! Baggrundshistorie Rommen laves af Varela Hermanos i Panama. Deres historie strækker sig tilbage til 1908, hvor Don José Varela Blanco, en ung spansk immigrant, oprettede San Isidro sukkermøllen i byen Pesé. Den første sukkermølle i den daværende nyligt skabte Panama republik. Byen Pesé, som selv blev oprettet i midten af det attende århundrede, ligger i en frugtbar dal i midten af Panama. Hovederhvervet i denne dal er nu dyrkning af sukkerrør, som beskæftiger mange lokale bønder. Den moderate nedbør, de kolde nætter og fugtige dage spiller alt sammen en rolle i udviklingen og modningen af rommen. Jo større forskel i temperaturen på de meget varme dage og de kolde nætter, jo hurtigere modnes rommen og jo flere smags- og duftstoffer udvikles der. Så Abuelo romfabrikken ligger ikke tilfældigt i dette ”smørhul”.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Cherry Wine Cask Finish 42%', 'https://www.uhrskov-vine.dk/ron-patridom-xo-lmt-edt-cherry-wine-cask-finish-42', 595, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/h/cherry_2.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium spiritus fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave har gennemgået en ekstra lagring i ex-cherry vinfade, hvilket tilføjer spiritussen en frugtagtig note. Patridom XO Cherry Wine Cask Finish er blevet aftappet i juni 2024 med et resultat på 2237 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Marsala Wine Cask Finish 42%', 'https://www.uhrskov-vine.dk/ron-patridom-xo-lmt-edt-marsala-wine-cask-42', 595, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/m/a/marsala.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium spiritus fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave har gennemgået en ekstra lagring i ex-Marsala fade, hvilket tilføjer spiritussen fyldige og cremet noter. Patridom XO Marsala Cask Finish er blevet aftappet i juni 2024 med et resultat på 2237 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Patridom XO Limited Edition Pineau des Charentes Cask Finish 42%', 'https://www.uhrskov-vine.dk/patridom-xo-lmt-edt-pineau-des-charentes-cask-42', 595, TRUE, NULL, 42, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/p/i/pineadesucharetnes.png', 'Patridom XO Limited Edition er baseret på Patridom XO, som er en premium spiritus fremstillet af frisk sukkerrørsaft og melasse. Patridom XO er lagret i tropisk klima i amerikanske og franske egetræsfade i den Dominikanske Republik. Denne Limited Edition udgave har gennemgået en ekstra lagring i ex-Cognacfade, hvilket tilføjer spiritussen en frugtagtig note. Patridom XO Cognac Cask Finish er blevet aftappet i juli 2023 med et resultat på 2333 flasker.', '2026-11-08 12:00:00+01');
INSERT INTO stg_uhrskov_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Compagnie Des Indes Rum Spiced 40%', 'https://www.uhrskov-vine.dk/compagnie-des-indes-rum-spiced-40', 299, TRUE, NULL, 40, 'https://www.uhrskov-vine.dk/media/catalog/product/cache/f438d0b91aceecad0fcc94fe30062643/c/d/cdispiced.png', 'Glem alt hvad du ved om konventionel spiced rum. Dette er langt fra de sirupssøde og kunstige udgaver, som alt for længe har dominereret kategorien! Compagnie des Indes Spiced er lavet på 80% rom fra Den Dominikanske Republik og 20% rom fra Venezuela, som over en periode på 2 uger nænsomt infuseres med ægte krydderier. Opskriften tæller blandt andet ingefær, vanilje, lakrids, muskatnød og sort peber, og de kun 15 gram sukker per liter giver en helt ny oplevelse af Spiced Rum. Den er ikke engang tilsat karamelfarve! Bravo!', '2026-11-08 12:00:00+01');
