-- Uhrskov-vine.dk import (staging) - 566 rom
-- Kilde: uhrskov-vine.dk (Magento/Hyvaa), 24 katalogsider + 566 produktsider, 2026-11-08
-- NB: Anubis proof-of-work loest programmatisk (SHA-256, difficulty 6).
-- NB: Lagerstatus er client-renderet paa dette site og findes ikke i server-HTML -> in_stock=TRUE antaget.
-- NB: Volumen er kun sat hvor butikken oplyser den (navn/beskrivelse), oevrige = NULL.
-- Koer: 1) hele filen, 2) SELECT * FROM import_shop('Uhrskov Vine', 'https://www.uhrskov-vine.dk', 'stg_uhrskov_dk', 'Rom');

CREATE TABLE IF NOT EXISTS stg_uhrskov_dk (
    name TEXT, url TEXT, price_dkk NUMERIC, in_stock BOOLEAN,
    volume_cl NUMERIC, abv NUMERIC, image_url TEXT, description TEXT,
    scraped_at TIMESTAMPTZ
);

-- Standard: tøm staging før hver gen-import, så gamle rækker aldrig blandes med nye.
TRUNCATE stg_uhrskov_dk;
ALTER TABLE stg_uhrskov_dk ENABLE ROW LEVEL SECURITY;

-- Kontrol: forventer total=566, uden_volumen=509, uden_abv=25
SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE in_stock) AS paa_lager,
       COUNT(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       COUNT(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       MIN(price_dkk) AS billigste, MAX(price_dkk) AS dyreste
FROM stg_uhrskov_dk;
